
window.calculatePricesFromPercentages = function() {
    const cost = parseFloat(document.getElementById('item_cost_price')?.value) || 0;
    const repPct = parseFloat(document.getElementById('item_markup_rep')?.value) || 0;
    const wholesalePct = parseFloat(document.getElementById('item_markup_wholesale')?.value) || 0;
    const retailPct = parseFloat(document.getElementById('item_markup_retail')?.value) || 0;

    if (cost > 0) {
        const repPrice = cost + (cost * repPct / 100);
        const wholesalePrice = cost + (cost * wholesalePct / 100);
        const retailPrice = cost + (cost * retailPct / 100);

        if (document.getElementById('item_rep_price')) {
            document.getElementById('item_rep_price').value = (Math.round(repPrice * 100) / 100).toFixed(2).replace(/\.00$/, '');
        }
        if (document.getElementById('item_wholesale_price')) {
            document.getElementById('item_wholesale_price').value = (Math.round(wholesalePrice * 100) / 100).toFixed(2).replace(/\.00$/, '');
        }
        if (document.getElementById('item_price')) {
            document.getElementById('item_price').value = (Math.round(retailPrice * 100) / 100).toFixed(2).replace(/\.00$/, '');
        }
    }
};

// Global pure string XSS protection sanitizer
function escapeHtml(text) {
    if (text === null || text === undefined) return '';
    return String(text)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}
window.escapeHtml = escapeHtml;

function toEnglishDigits(val) {
    if (val === null || val === undefined) return '';
    return String(val)
        .replace(/[٠-٩]/g, d => '0123456789'['٠١٢٣٤٥٦٧٨٩'.indexOf(d)])
        .replace(/[۰-۹]/g, d => '0123456789'['۰۱۲۳۴۵۶۷۸۹'.indexOf(d)])
        .trim();
}
window.toEnglishDigits = toEnglishDigits;

document.addEventListener('input', function(e) {
    if (e.target && (e.target.type === 'number' || e.target.classList.contains('variant-price') || e.target.classList.contains('variant-wholesale-price') || e.target.classList.contains('variant-rep-price') || e.target.classList.contains('variant-cost-price') || e.target.id === 'item_price' || e.target.id === 'item_wholesale_price' || e.target.id === 'item_rep_price' || e.target.id === 'item_cost_price')) {
        const raw = e.target.value;
        const normalized = toEnglishDigits(raw);
        if (raw !== normalized) {
            e.target.value = normalized;
        }
    }
}, true);

