// Direct Supabase PostgREST helper.
// Security: always sends the logged-in user's JWT (never the bare anon key) so Row Level Security
// policies are enforced with the real tenant-owner identity.
window.supabaseDirectRestCall = async function(table, method, queryParams, bodyObj) {
    try {
        let accessToken = '';
        try {
            if (supabaseClient && supabaseClient.auth) {
                const { data } = await supabaseClient.auth.getSession();
                accessToken = data?.session?.access_token || '';
            }
        } catch (_) {}
        if (!accessToken) {
            return { data: null, error: { code: '401', message: 'No authenticated session' } };
        }
        const url = `${SUPABASE_URL}/rest/v1/${table}${queryParams ? `?${queryParams}` : ''}`;
        const res = await fetch(url, {
            method,
            headers: {
                'apikey': SUPABASE_ANON_KEY,
                'Authorization': `Bearer ${accessToken}`,
                'Content-Type': 'application/json',
                'Prefer': 'return=representation'
            },
            body: bodyObj !== undefined ? JSON.stringify(bodyObj) : undefined
        });
        const text = await res.text();
        let parsed = null;
        try { parsed = text ? JSON.parse(text) : []; } catch (_) { parsed = []; }
        if (!res.ok) {
            return {
                data: null,
                error: {
                    code: (parsed && parsed.code) || String(res.status),
                    message: (parsed && (parsed.message || parsed.error || parsed.details)) || text || `HTTP ${res.status}`
                }
            };
        }
        return { data: Array.isArray(parsed) ? parsed : (parsed ? [parsed] : []), error: null };
    } catch (err) {
        return { data: null, error: { code: 'NETWORK_ERROR', message: err.message || String(err) } };
    }
};

// Guaranteed Supabase write helper: tries primary client, falls back to direct REST with SUPABASE_ANON_KEY & without tenant_id filter if 0 rows matched
window.supabaseWriteRow = async function(table, action, payload, matchId, tenantId) {
    let lastRes = { data: null, error: null };

    if (action === 'insert') {
        const rows = Array.isArray(payload) ? payload : [payload];
        if (supabaseClient) {
            const res = await supabaseClient.from(table).insert(rows).select();
            lastRes = res;
            if (!res.error && Array.isArray(res.data) && res.data.length > 0) {
                return res;
            }
            if (res.error && res.error.code !== '42501' && !(res.error.message && res.error.message.includes('row-level security'))) {
                const restRes = await window.supabaseDirectRestCall(table, 'POST', '', rows);
                if (!restRes.error && Array.isArray(restRes.data) && restRes.data.length > 0) {
                    return restRes;
                }
                return restRes.error ? restRes : res;
            }
        }
        const restRes = await window.supabaseDirectRestCall(table, 'POST', '', rows);
        if (!restRes.error && Array.isArray(restRes.data) && restRes.data.length > 0) {
            return restRes;
        }
        return restRes.error ? restRes : lastRes;
    } else if (action === 'update') {
        if (supabaseClient) {
            let q = supabaseClient.from(table).update(payload).eq('id', matchId);
            if (tenantId) q = q.eq('tenant_id', tenantId);
            const res = await q.select();
            lastRes = res;
            if (!res.error && Array.isArray(res.data) && res.data.length > 0) {
                return res;
            }
        }
        // Fallback: Direct REST PATCH scoped by id + tenant_id (never by id alone, to keep tenant isolation)
        if (tenantId) {
            const qWithTenant = `id=eq.${encodeURIComponent(matchId)}&tenant_id=eq.${encodeURIComponent(tenantId)}`;
            const restRes = await window.supabaseDirectRestCall(table, 'PATCH', qWithTenant, payload);
            if (!restRes.error && Array.isArray(restRes.data) && restRes.data.length > 0) {
                return restRes;
            }
            if (restRes.error) return restRes;
        }
        return lastRes;
    } else if (action === 'delete') {
        if (supabaseClient) {
            let q = supabaseClient.from(table).delete().eq('id', matchId);
            if (tenantId) q = q.eq('tenant_id', tenantId);
            const res = await q.select();
            if (!res.error && Array.isArray(res.data) && res.data.length > 0) {
                return res;
            }
            lastRes = res;
        }
        if (!tenantId) return lastRes;
        const qScoped = `id=eq.${encodeURIComponent(matchId)}&tenant_id=eq.${encodeURIComponent(tenantId)}`;
        return await window.supabaseDirectRestCall(table, 'DELETE', qScoped);
    }
    return lastRes;
};

// Guaranteed batch update helper (e.g. linking/unlinking multiple products to a brand)
window.supabaseWriteBatch = async function(table, payload, filterCol, filterVals, tenantId) {
    if (!Array.isArray(filterVals) || filterVals.length === 0) return { data: [], error: null };
    let lastRes = { data: [], error: null };
    if (supabaseClient) {
        let q = supabaseClient.from(table).update(payload).in(filterCol, filterVals);
        if (tenantId) q = q.eq('tenant_id', tenantId);
        const res = await q.select();
        if (!res.error && Array.isArray(res.data) && res.data.length > 0) {
            return res;
        }
        lastRes = res;
    }
    // Never run an unscoped batch update across tenants
    if (!tenantId) return lastRes;
    const inList = filterVals.map(v => `"${String(v).replace(/"/g, '')}"`).join(',');
    const query = `${filterCol}=in.(${encodeURIComponent(inList)})&tenant_id=eq.${encodeURIComponent(tenantId)}`;
    return await window.supabaseDirectRestCall(table, 'PATCH', query, payload);
};

