async function validateTenantSession(force = false) {
    if (!force && window.currentTenantProfile && (Date.now() - (window._lastTenantValidationTs || 0) < 15000)) {
        return true;
    }
    // Fail-closed: without the Supabase SDK there is no way to verify the session
    if (typeof supabaseClient === 'undefined' || !supabaseClient) return false;
    try {
        const { data } = await supabaseClient.auth.getSession();
        const session = data ? data.session : null;
        const userEmail = session && session.user ? session.user.email : null;
        const activeTenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';

        // ARMOR: Require a valid cryptographic Supabase JWT session. localStorage flags alone are NEVER accepted.
        if (!session || !userEmail) {
            console.warn('⚠️ No valid cryptographic session detected! Redirecting to login.html...');
            sessionStorage.clear();
            localStorage.removeItem('sb-auth-token');
            localStorage.removeItem('admin_demo_email');
            sessionStorage.setItem('admin_logged_out', 'true');
            if (typeof supabaseClient !== 'undefined' && supabaseClient?.auth) {
                try { await supabaseClient.auth.signOut(); } catch(_) {}
            }
            window.location.replace('login.html');
            return false;
        }

        const { data: tenantRow, error: tenantErr } = await supabaseClient
            .from('tenants')
            .select('*')
            .eq('tenant_id', activeTenantId)
            .maybeSingle();

        if (tenantErr) {
            // Transient network/server error: keep the verified JWT session instead of force-logging-out.
            // Data access remains protected server-side by RLS.
            console.warn('Tenant query note:', tenantErr.message);
            return true;
        }

        const currentEmail = (userEmail || '').trim().toLowerCase();

        if (tenantRow) {
            const dbEmail = (tenantRow.owner_email || '').trim().toLowerCase();
            const isActive = tenantRow.is_active !== false && tenantRow.status !== 'suspended' && tenantRow.status !== 'disabled';
            const expDateStr = tenantRow.expiry_date;
            const isExpired = expDateStr ? (new Date(expDateStr) < new Date()) : false;

            // Mismatch if dbEmail in database does not match current logged-in email
            const isEmailMismatch = (dbEmail !== currentEmail);

            if (isEmailMismatch || !isActive || isExpired) {
                console.warn('⚠️ SESSION INVALIDATED! Redirecting to login.html...', { dbEmail, currentEmail, activeTenantId, isActive, isExpired });

                sessionStorage.clear();
                localStorage.removeItem('sb-auth-token');
                localStorage.removeItem('admin_demo_email');
                localStorage.removeItem('local_tenant_profile_' + activeTenantId);
                sessionStorage.setItem('admin_logged_out', 'true');

                if (typeof supabaseClient !== 'undefined' && supabaseClient?.auth) {
                    try { await supabaseClient.auth.signOut(); } catch(_) {}
                }

                // Immediate forced redirection to login page
                window.location.replace('login.html');
                return false;
            }
        } else {
            console.warn('⚠️ Tenant row not found for:', activeTenantId);
            sessionStorage.clear();
            localStorage.removeItem('sb-auth-token');
            localStorage.removeItem('admin_demo_email');
            sessionStorage.setItem('admin_logged_out', 'true');
            window.location.replace('login.html');
            return false;
        }
    } catch (e) {
        console.warn('Tenant session validation note:', e);
    }
    return true;
}

function setupTenantRealtimeListener() {
    if (!supabaseClient) return;
    try {
        const activeTenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
        supabaseClient
            .channel('tenant_session_realtime_' + activeTenantId)
            .on('postgres_changes', {
                event: '*',
                schema: 'public',
                table: 'tenants',
                // Only listen to this tenant's row instead of every tenant on the platform
                filter: `tenant_id=eq.${activeTenantId}`
            }, (payload) => {
                console.log('Realtime change in tenants table detected:', payload);
                validateTenantSession();
            })
            .subscribe();
    } catch (e) {
        console.warn('Tenant realtime listener note:', e);
    }
}

async function initApp() {
    if (typeof supabase !== 'undefined') {
        supabaseClient = supabase.createClient(SUPABASE_URL, SUPABASE_ANON_KEY);
    } else {
        console.error("Supabase SDK missing");
    }

    // STRICT ANTI-BREACH AUTH GATE: Block execution until session and tenant ownership are verified
    const isSessionValid = await validateTenantSession();
    if (!isSessionValid) return; // Completely halt app execution!

    setupNavigation();
    setupEventListeners();
    startLiveClock();
    initCustomDropdowns();
    initScrollToTop();
    initPwaInstallPrompt();

    // Auto-restore drafts for any open page/form on page refresh
    try {
        document.querySelectorAll('form').forEach(form => {
            if (form.id) restoreFormDraft(form);
        });
    } catch (e) {}

    const savedLang = localStorage.getItem('adminLang') || 'ar';
    applyLanguage(savedLang);

    // Scalability Armor: Instant Realtime listener handles live changes; background check runs every 60s only when tab is active
    setInterval(() => {
        if (document.visibilityState === 'visible') {
            validateTenantSession();
        }
    }, 60000);
    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState === 'visible') {
            validateTenantSession();
        }
    });
    setupTenantRealtimeListener();

    try {
        if (supabaseClient) {
            const { data } = await supabaseClient.auth.getSession();
            const session = data ? data.session : null;
            if (!session && sessionStorage.getItem('admin_logged_out') === 'true') {
                window.location.href = 'login.html';
                return;
            }
            const userEmail = (session && session.user && session.user.email) || sessionStorage.getItem('admin_demo_email');
            if (userEmail) {
                currentAdminName = userEmail.split('@')[0];
                const adminNameEl = document.getElementById('admin-display-name');
                if (adminNameEl) adminNameEl.textContent = currentAdminName;
            }
            const activeTenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
            try {
                const tenantProfile = window.currentTenantProfile;
                if (tenantProfile && tenantProfile.owner_name) {
                    const adminNameEl = document.getElementById('admin-display-name');
                    if (adminNameEl) adminNameEl.textContent = tenantProfile.owner_name;
                } else {
                    const storedProfile = localStorage.getItem('local_tenant_profile_' + activeTenantId);
                    if (storedProfile) {
                        const prof = JSON.parse(storedProfile);
                        if (prof && prof.owner_name) {
                            const adminNameEl = document.getElementById('admin-display-name');
                            if (adminNameEl) adminNameEl.textContent = prof.owner_name;
                        }
                    }
                }
            } catch (_) {}
        }
    } catch (err) {
        console.warn("Auth check note:", err);
    }

    // Immediately load site settings & tenant branding so store name & logo display on initial page load
    if (typeof loadSettingsData === 'function') {
        loadSettingsData();
    }

    const targetHash = window.location.hash.replace('#', '');
    switchToSection(targetHash || 'dashboard');

    // Defer heavy background prefetch until idle (4500ms) so initial dashboard overview renders at maximum speed
    const startPrefetch = () => {
        if (typeof window.prefetchAllDashboardSections === 'function') {
            window.prefetchAllDashboardSections(targetHash || 'dashboard');
        }
    };
    if (typeof window.requestIdleCallback === 'function') {
        window.requestIdleCallback(() => setTimeout(startPrefetch, 4500), { timeout: 7000 });
    } else {
        setTimeout(startPrefetch, 4500);
    }
}

window.sectionLoadedState = {};
window.isPrefetchingSections = false;

window.prefetchAllDashboardSections = async function(activeSectionId) {
    if (window.isPrefetchingSections) return;
    window.isPrefetchingSections = true;
    try {
        const prefetchQueue = [
            { id: 'sections', fn: () => typeof loadSectionsData === 'function' && loadSectionsData(false) },
            { id: 'menu', fn: () => typeof loadMenuData === 'function' && loadMenuData(false) },
            { id: 'brands', fn: () => typeof loadBrandsData === 'function' && loadBrandsData(false) },
            { id: 'announcements', fn: () => typeof loadAnnouncementsData === 'function' && loadAnnouncementsData(false) },
            // 'orders' & 'general_reviews' are intentionally NOT prefetched: they are not in the sidebar
            // and their tables were removed by supabase_saas_security_rules.sql (they still load on demand via #hash).
            { id: 'customers', fn: () => typeof loadCustomersData === 'function' && loadCustomersData() },
            { id: 'representatives', fn: () => typeof loadRepresentativesData === 'function' && loadRepresentativesData() },
            { id: 'coupons', fn: () => typeof loadCouponsData === 'function' && loadCouponsData() },
            { id: 'about_store', fn: () => typeof loadAboutStoreData === 'function' && loadAboutStoreData() },
            { id: 'customer_service', fn: () => typeof loadCustomerServiceData === 'function' && loadCustomerServiceData() },
            { id: 'faqs', fn: () => typeof loadFaqsData === 'function' && loadFaqsData() },
            { id: 'privacy', fn: () => typeof loadPrivacyData === 'function' && loadPrivacyData() },
            { id: 'product_reviews', fn: () => typeof loadProductReviewsData === 'function' && loadProductReviewsData() },
            { id: 'dashboard', fn: () => typeof loadDashboardOverview === 'function' && loadDashboardOverview() }
        ];

        // 1. Run high-priority catalog sections in parallel right away
        const highPriority = prefetchQueue.slice(0, 4).filter(item => item.id !== activeSectionId && !window.sectionLoadedState[item.id]);
        await Promise.allSettled(highPriority.map(async (item) => {
            try {
                await item.fn();
                window.sectionLoadedState[item.id] = true;
            } catch (_) {}
        }));

        // 2. Run remaining sections in fast batches
        const remaining = prefetchQueue.slice(4).filter(item => item.id !== activeSectionId && !window.sectionLoadedState[item.id]);
        for (let i = 0; i < remaining.length; i += 3) {
            const batch = remaining.slice(i, i + 3);
            await Promise.allSettled(batch.map(async (item) => {
                try {
                    await item.fn();
                    window.sectionLoadedState[item.id] = true;
                } catch (_) {}
            }));
        }
    } finally {
        window.isPrefetchingSections = false;
    }
};

/**
 * Scroll to Top Floating Button Controller
 */
function initScrollToTop() {
    const btn = document.getElementById('btnScrollToTop');
    if (!btn) return;

    function handleScroll() {
        const scrolled = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0;
        const workspaceScrolled = document.querySelector('.main-workspace')?.scrollTop || 0;
        const maxScroll = Math.max(scrolled, workspaceScrolled);
        const fullPageThreshold = Math.max(550, Math.floor((window.innerHeight || 600) * 0.85));
        if (maxScroll > fullPageThreshold) {
            btn.classList.add('show');
        } else {
            btn.classList.remove('show');
        }
    }

    window.removeEventListener('scroll', handleScroll);
    document.removeEventListener('scroll', handleScroll);

    window.addEventListener('scroll', handleScroll, { passive: true });
    document.addEventListener('scroll', handleScroll, { passive: true });
    document.querySelector('.main-workspace')?.addEventListener('scroll', handleScroll, { passive: true });

    btn.onclick = function() {
        scrollToTopSmoothly();
    };

    handleScroll();
}
window.initScrollToTop = initScrollToTop;

