window.renderVariantsEmptyState = () => {
    const container = document.getElementById('variants-container');
    if (!container) return;
    const isAr = document.documentElement.getAttribute('lang') === 'ar';
    if (container.children.length === 0 || container.querySelector('.variants-empty-hint')) {
        container.innerHTML = `
            <div class="variants-empty-hint">
                <i class="fas fa-info-circle"></i>
                <span>${isAr ? 'لا توجد خيارات مضافة بعد (انقر على "+ إضافة خيار" أو اختر قالب جاهز)' : 'No variants added yet (click "+ Add Variant" or pick a preset)'}</span>
            </div>
        `;
    }
    updateBasePricesVisibility();
};

window.updateBasePricesVisibility = () => {
    const basePrices = document.getElementById('base-prices-container');
    if (!basePrices) return;
    const hasVariants = document.querySelectorAll('#sizes-container .variant-row-compact, #units-container .variant-row-compact, #variants-container .variant-row-compact').length > 0;
    if (hasVariants) {
        basePrices.classList.add('hidden-prices');
        basePrices.style.setProperty('display', 'none', 'important');
    } else {
        basePrices.classList.remove('hidden-prices');
        basePrices.style.removeProperty('display');
    }
};

/**
 * Helpers & Utils
 */
function isNullOrEmpty(val) { return val === null || val === undefined || val === "" || val === "null"; }

function transliterateArabic(text) {
    const mapping = {
        'أ': 'a', 'إ': 'i', 'آ': 'a', 'ا': 'a', 'ب': 'b', 'ت': 't', 'ث': 'th', 'ج': 'j',
        'ح': 'h', 'خ': 'kh', 'د': 'd', 'ذ': 'dh', 'ر': 'r', 'ز': 'z', 'س': 's', 'ش': 'sh',
        'ص': 's', 'ض': 'd', 'ط': 't', 'ظ': 'z', 'ع': 'a', 'غ': 'gh', 'ف': 'f', 'ق': 'q',
        'ك': 'k', 'ل': 'l', 'م': 'm', 'ن': 'n', 'ه': 'h', 'و': 'w', 'ي': 'y', 'ة': 'h',
        'ى': 'y', ' ': '-', 'ئ': 'y', 'ء': 'a', 'ؤ': 'w'
    };
    return text.split('').map(char => mapping[char] || char).join('').toLowerCase().replace(/[^a-z0-9-]/g, '').replace(/-+/g, '-');
}

const TOAST_TRANSLATION_MAP = {
    'حدث خطأ أثناء حفظ الحساب': 'Error occurred while saving account',
    'حدث خطأ أثناء اعتماد الحساب': 'Error occurred while approving account',
    'حدث خطأ أثناء حذف الحساب': 'Error occurred while deleting account',
    'حدث خطأ أثناء تحديث الحالة': 'Error occurred while updating status',
    'حدث خطأ أثناء حفظ الحساب الشخصي': 'Error occurred while saving personal profile',
    'حدث خطأ أثناء حفظ الإعدادات': 'Error occurred while saving settings',
    'حدث خطأ أثناء تحديث البيانات': 'Error refreshing data',
    'حدث خطأ أثناء التحديث': 'Refresh failed',
    'حدث خطأ غير متوقع': 'An unexpected error occurred',
    'تم الحفظ بنجاح': 'Saved successfully',
    'تم التحديث بنجاح': 'Updated successfully',
    'تم الحذف بنجاح': 'Deleted successfully',
    'تم النسخ بنجاح': 'Copied successfully',
    'يرجى ملء جميع الحقول المطلوبة': 'Please fill in all required fields',
    'بريد إلكتروني غير صحيح': 'Invalid email address',
    'رقم هاتف غير صحيح': 'Invalid phone number',
    '✨ تم تحديث البيانات بنجاح': '✨ Data refreshed successfully',
    '✨ تم حذف الصنف نهائياً': '✨ Item permanently deleted',
    '✨ تم حفظ إعدادات المتجر ورابط الموقع بنجاح': '✨ Store settings and website link saved successfully'
};

function showToast(arg1, arg2, arg3) {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    let msg = '';
    let type = 'info';

    if (typeof arg3 !== 'undefined') {
        msg = isAr ? arg1 : arg2;
        type = arg3;
    } else if (typeof arg2 !== 'undefined') {
        if (['success', 'error', 'info', 'warning'].includes(arg2)) {
            msg = arg1;
            type = arg2;
        } else {
            msg = isAr ? arg1 : arg2;
            type = 'info';
        }
    } else {
        msg = arg1;
        type = 'info';
    }

    if (!isAr && TOAST_TRANSLATION_MAP[msg]) {
        msg = TOAST_TRANSLATION_MAP[msg];
    }

    const cont = document.getElementById('toast-container');
    if (!cont) return;
    cont.innerHTML = '';
    const t = document.createElement('div');
    t.className = `toast ${type}`;
    const icon = type === 'success' ? 'check-circle' : (type === 'error' ? 'exclamation-triangle' : 'info-circle');
    t.innerHTML = `<i class="fas fa-${icon}"></i><span>${msg}</span>`;
    cont.appendChild(t);
    setTimeout(() => {
        t.style.opacity = '0';
        setTimeout(() => t.remove(), 500);
    }, 3000);
}

/* ==========================================================================
   GLOBAL AUTO-SAVE DRAFTS SYSTEM (ميزة الحفظ المسبق التلقائي لجميع النماذج)
   ========================================================================== */

const DRAFT_PREFIX = 'sahala_form_draft_';

window.saveFormDraft = function(formElement) {
    if (!formElement || !formElement.id) return;
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';

    const hiddenIdEl = formElement.querySelector('input[type="hidden"][id$="_id"], input[type="hidden"][id="item-id"], input[type="hidden"][id="app_user_id"], input[type="hidden"][id="section-id"]');
    if (hiddenIdEl && hiddenIdEl.value && hiddenIdEl.value.trim() !== '') {
        return;
    }

    const formData = {};
    let hasValues = false;

    const inputs = formElement.querySelectorAll('input:not([type="password"]):not([type="hidden"]), select, textarea');
    inputs.forEach(el => {
        if (!el.id && !el.name) return;
        const key = el.id || el.name;

        if (el.type === 'checkbox') {
            formData[key] = el.checked;
        } else if (el.type === 'radio') {
            if (el.checked) formData[key] = el.value;
        } else {
            const val = el.value;
            if (val && val.trim() !== '') {
                hasValues = true;
            }
            formData[key] = val;
        }
    });

    if (hasValues) {
        const draftPayload = {
            timestamp: Date.now(),
            data: formData
        };
        try {
            localStorage.setItem(`${DRAFT_PREFIX}${formElement.id}_${tenantId}`, JSON.stringify(draftPayload));
            showDraftSaveIndicator(formElement);
        } catch (e) {
            console.warn('Draft save error:', e);
        }
    }
};

window.restoreFormDraft = function(formElement) {
    return false;
};

window.clearFormDraft = function(formId) {
    if (!formId) return;
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const draftKey = `${DRAFT_PREFIX}${formId}_${tenantId}`;
    try {
        localStorage.removeItem(draftKey);
    } catch (e) {}

    const formElement = document.getElementById(formId);
    if (formElement) {
        const badge = formElement.querySelector('.draft-notice-badge');
        if (badge) badge.remove();
        const indicator = formElement.querySelector('.draft-save-indicator');
        if (indicator) indicator.remove();
    }
};

function showDraftSaveIndicator(formElement) {
    let indicator = formElement.querySelector('.draft-save-indicator');
    if (!indicator) {
        indicator = document.createElement('div');
        indicator.className = 'draft-save-indicator';
        indicator.style.cssText = 'font-size:0.75rem; color: #10b981; font-weight:700; display:inline-flex; align-items:center; gap:4px; opacity:0.9; transition: opacity 0.3s ease;';

        const header = formElement.querySelector('.modal-header') || formElement;
        if (header) {
            header.appendChild(indicator);
        }
    }
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    indicator.innerHTML = `<i class="fas fa-check-circle" style="color:#10b981;"></i> <span>${isAr ? 'حفظ مسبق تلقائي' : 'Auto-saved draft'}</span>`;
    indicator.style.opacity = '1';

    if (window.draftSaveTimeout) clearTimeout(window.draftSaveTimeout);
    window.draftSaveTimeout = setTimeout(() => {
        if (indicator) indicator.style.opacity = '0';
    }, 2500);
}

function showDraftBadge(formElement, draftKey) {
    let badge = formElement.querySelector('.draft-notice-badge');
    if (!badge) {
        badge = document.createElement('div');
        badge.className = 'draft-notice-badge glass';
        badge.style.cssText = 'padding: 8px 12px; margin-bottom: 14px; border-radius: 12px; background: rgba(217, 119, 6, 0.12); border: 1px solid rgba(217, 119, 6, 0.35); display: flex; align-items: center; justify-content: space-between; font-size: 0.8rem; font-weight: 700; color: var(--text-main); width: 100%; box-sizing: border-box;';

        formElement.insertBefore(badge, formElement.firstChild);
    }

    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    badge.innerHTML = `
        <div style="display:flex; align-items:center; gap:6px;">
            <i class="fas fa-magic" style="color:var(--primary-gold);"></i>
            <span>${isAr ? 'تم استرجاع مسودة الحفظ المسبق التلقائي' : 'Restored auto-saved draft'}</span>
        </div>
        <button type="button" onclick="clearAndResetDraft('${formElement.id}', '${draftKey}')" style="background:rgba(239,68,68,0.15); color:#ef4444; border:1px solid rgba(239,68,68,0.3); padding:3px 8px; border-radius:8px; font-size:0.75rem; font-weight:700; cursor:pointer; display:inline-flex; align-items:center; gap:4px;">
            <i class="fas fa-trash-alt"></i> ${isAr ? 'مسح المسودة' : 'Clear Draft'}
        </button>
    `;
}

window.clearAndResetDraft = function(formId, draftKey) {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    try {
        localStorage.removeItem(draftKey);
    } catch (e) {}

    const formElement = document.getElementById(formId);
    if (formElement) {
        formElement.reset();
        const badge = formElement.querySelector('.draft-notice-badge');
        if (badge) badge.remove();
        const indicator = formElement.querySelector('.draft-save-indicator');
        if (indicator) indicator.remove();
        if (typeof showToast === 'function') {
            showToast(isAr ? '🗑️ تم مسح المسودة وإعادة ضبط النموذج' : 'Draft cleared and form reset', 'info');
        }
    }
};

let globalDraftDebounce = null;
document.addEventListener('input', (e) => {
    const form = e.target.closest('form');
    if (!form || !form.id) return;

    if (globalDraftDebounce) clearTimeout(globalDraftDebounce);
    globalDraftDebounce = setTimeout(() => {
        saveFormDraft(form);
    }, 400);
});

document.addEventListener('change', (e) => {
    const form = e.target.closest('form');
    if (!form || !form.id) return;
    saveFormDraft(form);
});

document.addEventListener('submit', (e) => {
    const form = e.target.closest('form');
    if (form && form.id) {
        clearFormDraft(form.id);
    }
});

/* ==========================================================================
   SAAS OFFLINE & SLOW-NETWORK ENGINE (نظام الحفظ والمزامنة المؤقتة عند بطء النت)
   ========================================================================== */

const OFFLINE_CACHE_PREFIX = 'sahala_offline_cache_';
const OFFLINE_QUEUE_PREFIX = 'sahala_offline_queue_';

window.saveDataToOfflineCache = function(cacheKey, data) {
    if (!cacheKey || !data) return;
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    try {
        const payload = {
            timestamp: Date.now(),
            data: data
        };
        localStorage.setItem(`${OFFLINE_CACHE_PREFIX}${cacheKey}_${tenantId}`, JSON.stringify(payload));
    } catch (e) {
        console.warn('Offline cache save error:', e);
    }
};

window.getDataFromOfflineCache = function(cacheKey) {
    if (!cacheKey) return null;
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    try {
        const stored = localStorage.getItem(`${OFFLINE_CACHE_PREFIX}${cacheKey}_${tenantId}`);
        if (stored) {
            const parsed = JSON.parse(stored);
            return parsed.data || null;
        }
    } catch (e) {
        console.warn('Offline cache read error:', e);
    }
    return null;
};

window.queueOfflineOperation = function(tableName, action, payload, recordId = null) {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const queueKey = `${OFFLINE_QUEUE_PREFIX}${tenantId}`;

    let queue = [];
    try {
        const stored = localStorage.getItem(queueKey);
        if (stored) queue = JSON.parse(stored);
    } catch (e) {}

    const queueItem = {
        id: 'off_' + Date.now() + '_' + Math.random().toString(36).substr(2, 5),
        tableName,
        action,
        payload,
        recordId,
        timestamp: Date.now()
    };

    queue.push(queueItem);
    try {
        localStorage.setItem(queueKey, JSON.stringify(queue));
    } catch (e) {}

    if (typeof showToast === 'function') {
        showToast(
            isAr ? '📶 تم الحفظ مؤقتاً محلياً بسبب بطء النت! سيتم الإرسال تلقائياً فور تحسن الاتصال.' : 'Saved locally due to slow network. Will auto-sync when online.',
            'warning'
        );
    }
    updateOfflineStatusBadge();
    return queueItem;
};

window.processOfflineQueue = async function() {
    if (!navigator.onLine) return;
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const queueKey = `${OFFLINE_QUEUE_PREFIX}${tenantId}`;

    let queue = [];
    try {
        const stored = localStorage.getItem(queueKey);
        if (stored) queue = JSON.parse(stored);
    } catch (e) {}

    if (!queue || queue.length === 0) return;

    let successCount = 0;
    const remainingQueue = [];

    for (const item of queue) {
        try {
            let res = null;
            const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
            if (item.action === 'insert') {
                const insertPayload = { ...item.payload, tenant_id: tenantId };
                res = await supabaseClient.from(item.tableName).insert([insertPayload]);
            } else if (item.action === 'update') {
                res = await supabaseClient.from(item.tableName).update(item.payload).eq('id', item.recordId).eq('tenant_id', tenantId);
            } else if (item.action === 'delete') {
                res = await supabaseClient.from(item.tableName).delete().eq('id', item.recordId).eq('tenant_id', tenantId);
            }

            if (res && res.error) {
                console.warn('Sync queue item error:', res.error);
                remainingQueue.push(item);
            } else {
                successCount++;
            }
        } catch (err) {
            console.warn('Sync queue exception:', err);
            remainingQueue.push(item);
        }
    }

    try {
        localStorage.setItem(queueKey, JSON.stringify(remainingQueue));
    } catch (e) {}

    updateOfflineStatusBadge();

    if (successCount > 0 && typeof showToast === 'function') {
        showToast(
            isAr ? `✨ تم مزامنة ${successCount} إجـراء مـحـفـوظ مؤقتاً بـنـجـاح مـع قـاعـدة الـبـيـانـات!` : `Successfully synced ${successCount} offline items!`,
            'success'
        );
    }
};

function updateOfflineStatusBadge() {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const queueKey = `${OFFLINE_QUEUE_PREFIX}${tenantId}`;

    let queue = [];
    try {
        const stored = localStorage.getItem(queueKey);
        if (stored) queue = JSON.parse(stored);
    } catch (e) {}

    const pendingCount = queue ? queue.length : 0;
    const headerRight = document.querySelector('.header-right');

    let badge = document.getElementById('offline-sync-badge');
    if (pendingCount > 0) {
        if (!badge && headerRight) {
            badge = document.createElement('div');
            badge.id = 'offline-sync-badge';
            badge.style.cssText = 'padding: 4px 10px; border-radius: 12px; background: rgba(245, 158, 11, 0.15); border: 1px solid rgba(245, 158, 11, 0.4); color: #f59e0b; font-size: 0.75rem; font-weight: 800; display: inline-flex; align-items: center; gap: 6px; cursor: pointer; user-select: none;';
            badge.onclick = () => window.processOfflineQueue();
            headerRight.insertBefore(badge, headerRight.firstChild);
        }
        if (badge) {
            badge.innerHTML = `<i class="fas fa-wifi" style="color:#f59e0b;"></i> <span>${isAr ? `حفظ مؤقت (${pendingCount})` : `Offline Queued (${pendingCount})`}</span>`;
        }
    } else {
        if (badge) badge.remove();
    }
}

window.addEventListener('online', () => {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    if (typeof showToast === 'function') {
        showToast(isAr ? '🌐 تم استعادة الاتصال بالإنترنت! جاري المزامنة...' : 'Internet connection restored! Syncing...', 'info');
    }
    window.processOfflineQueue();
});

window.addEventListener('offline', () => {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    if (typeof showToast === 'function') {
        showToast(isAr ? '📶 انقطع الاتصال! تعمل المنصة في وضع الحفظ المؤقت المحلي بآمان' : 'Network offline! Operating in local offline cache mode safely', 'warning');
    }
});

setInterval(() => {
    if (navigator.onLine) {
        window.processOfflineQueue();
    }
}, 10000);

