function normalizeCategoryObject(c) {
    if (!c) return null;
    let pid = c.parent_id;
    if (pid === 0 || pid === '0' || pid === 'null' || pid === 'undefined' || pid === '' || pid === null || pid === undefined) {
        pid = null;
    } else {
        pid = String(pid);
    }
    return { ...c, id: String(c.id), parent_id: pid };
}

function mergeCategoriesWithLocal(tenantId, cloudCategories = []) {
    try {
        const localCats = getLocalCategoriesOverrides(tenantId);
        const deletedIds = new Set(JSON.parse(localStorage.getItem('local_deleted_category_ids_' + tenantId) || '[]').map(String));
        const map = new Map();
        (cloudCategories || []).forEach(raw => {
            const c = normalizeCategoryObject(raw);
            if (c && c.id && !deletedIds.has(String(c.id))) {
                map.set(String(c.id), c);
            }
        });
        localCats.forEach(raw => {
            const c = normalizeCategoryObject(raw);
            if (c && c.id && !deletedIds.has(String(c.id))) {
                const existing = map.get(String(c.id)) || {};
                map.set(String(c.id), { ...existing, ...c });
            }
        });
        return Array.from(map.values()).sort((a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0));
    } catch (_) {
        return (cloudCategories || []).map(normalizeCategoryObject).filter(Boolean);
    }
}

