/**
 * Menu Management - Luxury Grid, Table & KPI Statistics
 */
window.menuViewMode = 'grid';
window.allMenuItemsData = [];

function getTrashedMenuItemIds() {
    try {
        const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
        return JSON.parse(localStorage.getItem('trashedMenuItemIds_' + tenantId) || '[]');
    } catch (e) {
        return [];
    }
}

function setTrashedMenuItemIds(ids) {
    try {
        const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
        localStorage.setItem('trashedMenuItemIds_' + tenantId, JSON.stringify(ids));
    } catch (e) {}
}

async function loadMenuData(forceRefresh = false) {
    const gridWrapper = document.getElementById('menu-grid-wrapper');
    const tableBody = document.getElementById('menu-full-body');
    const alertBox = document.getElementById('menu-category-filter-alert');
    const catNameEl = document.getElementById('menu-filter-cat-name');
    if (!gridWrapper && !tableBody) return;

    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';

    if (forceRefresh) {
        window.clearTenantStaleLocalOverrides(tenantId, 'menu');
    }

    const hasExistingData = Array.isArray(window.allMenuItemsData) && window.allMenuItemsData.length > 0 && window.sectionLoadedState && window.sectionLoadedState['menu'];

    if (!hasExistingData || forceRefresh) {
        if (tableBody) tableBody.innerHTML = `<tr><td colspan="7" style="padding:15px;">${renderShimmerTable(5)}</td></tr>`;
        if (gridWrapper) gridWrapper.innerHTML = renderShimmerCards(8);
    } else {
        updateMenuKPIStats();
        renderMenuItems();
    }

    try {
        const [itemRes, catRes, varRes, brandRes] = await Promise.all([
            supabaseClient.from('menu_items').select('*').eq('tenant_id', tenantId).order('created_at', { ascending: false }),
            supabaseClient.from('categories').select('*').eq('tenant_id', tenantId),
            supabaseClient.from('item_variants').select('*').eq('tenant_id', tenantId).order('created_at', { ascending: true }),
            supabaseClient.from('brands').select('*').eq('tenant_id', tenantId).order('display_order', { ascending: true })
        ]);

        window.allMenuItemsData = mergeMenuItemsWithLocal(tenantId, itemRes.data || []);
        window.allCategoriesData = mergeCategoriesWithLocal(tenantId, catRes.data || []);
        window.allBrandsData = typeof mergeBrandsWithLocal === 'function' ? mergeBrandsWithLocal(tenantId, brandRes.data || []) : (brandRes.data || []);
        if (window.sectionLoadedState) window.sectionLoadedState['menu'] = true;
        const cloudVariants = varRes.data || [];
        let localVariants = [];
        try {
            localVariants = JSON.parse(localStorage.getItem('local_item_variants_data_' + tenantId) || '[]');
        } catch (e) {}
        const mergedVariantsMap = new Map();
        cloudVariants.forEach(v => {
            const compositeKey = String(v.item_id || '') + '_' + (v.name_ar || v.name_en || '').trim();
            mergedVariantsMap.set(compositeKey, { ...v });
        });
        localVariants.forEach(v => {
            const compositeKey = String(v.item_id || '') + '_' + (v.name_ar || v.name_en || '').trim();
            if (mergedVariantsMap.has(compositeKey)) {
                const existing = mergedVariantsMap.get(compositeKey);
                mergedVariantsMap.set(compositeKey, {
                    ...existing,
                    ...v,
                    id: existing.id || v.id,
                    image_url: v.image_url || existing.image_url || null,
                    r2_key: v.r2_key || existing.r2_key || null,
                    image_hash: v.image_hash || existing.image_hash || null
                });
            } else {
                mergedVariantsMap.set(compositeKey, { ...v });
            }
        });
        window.allItemVariantsData = Array.from(mergedVariantsMap.values());

        // Populate Category Filter Select Dropdown
        const catSelect = document.getElementById('menuCategorySelectFilter');
        if (catSelect) {
            const curVal = catSelect.value || 'all';
            let optionsHtml = `<option value="all" data-ar="جميع الأقسام" data-en="All Categories">${isAr ? 'جميع الأقسام' : 'All Categories'}</option>`;
            (window.allCategoriesData || []).forEach(c => {
                const cName = isAr ? c.name_ar : (c.name_en || c.name_ar);
                optionsHtml += `<option value="${c.id}">${cName}</option>`;
            });
            catSelect.innerHTML = optionsHtml;
            catSelect.value = curVal;
            makeCustomDropdown('menuCategorySelectFilter', true);
            makeCustomDropdown('menuStatusFilter');
            makeCustomDropdown('menuSortFilter');
        }

        // Populate Brand Filter Select Dropdown
        const brandSelect = document.getElementById('menuBrandSelectFilter');
        if (brandSelect) {
            const curBrandVal = window.selectedMenuBrandId || brandSelect.value || 'all';
            let brandOptionsHtml = `<option value="all" data-ar="جميع العلامات التجارية" data-en="All Brands">${isAr ? 'جميع العلامات التجارية' : 'All Brands'}</option>`;
            brandOptionsHtml += `<option value="none" data-ar="بدون علامة تجارية" data-en="No Brand">${isAr ? 'بدون علامة تجارية' : 'No Brand'}</option>`;
            (window.allBrandsData || []).forEach(b => {
                const bName = isAr ? b.name_ar : (b.name_en || b.name_ar);
                brandOptionsHtml += `<option value="${b.id}">${bName}</option>`;
            });
            brandSelect.innerHTML = brandOptionsHtml;
            brandSelect.value = curBrandVal;
            makeCustomDropdown('menuBrandSelectFilter', true);
        }

        if (typeof window.populateMenuPricingPreviewSelect === 'function') {
            try { window.populateMenuPricingPreviewSelect(); } catch (_) {}
        }

        // Update KPI Stats Counters
        updateMenuKPIStats();

        // Render Menu Items
        renderMenuItems();

    } catch (e) {
        console.error(e);
        if (!hasExistingData && tableBody) tableBody.innerHTML = `<tr><td colspan="6" style="text-align:center; color:red">Error: ${e.message}</td></tr>`;
    }
}

function updateMenuKPIStats() {
    const items = window.allMenuItemsData || [];
    const trashedIds = getTrashedMenuItemIds();

    const activeItems = items.filter(i => !trashedIds.includes(String(i.id)));
    const trashedItems = items.filter(i => trashedIds.includes(String(i.id)));

    const total = activeItems.length;
    const available = activeItems.filter(i => i.is_available !== false).length;
    const unavailable = activeItems.filter(i => i.is_available === false).length;
    const special = activeItems.filter(i => i.is_special).length;
    const categoriesCount = (window.allCategoriesData || []).length;
    const trash = trashedItems.length;

    if (document.getElementById('kpi-menu-total')) document.getElementById('kpi-menu-total').textContent = total;
    if (document.getElementById('kpi-menu-available')) document.getElementById('kpi-menu-available').textContent = available;
    if (document.getElementById('kpi-menu-unavailable')) document.getElementById('kpi-menu-unavailable').textContent = unavailable;
    if (document.getElementById('kpi-menu-special')) document.getElementById('kpi-menu-special').textContent = special;
    if (document.getElementById('kpi-menu-categories')) document.getElementById('kpi-menu-categories').textContent = categoriesCount;
    if (document.getElementById('kpi-menu-trash')) document.getElementById('kpi-menu-trash').textContent = trash;
}

function getMenuItemsEmptyMessage(isAr) {
    const query = (document.getElementById('menuSearchInput')?.value || '').trim();
    const statusFilter = document.getElementById('menuStatusFilter')?.value || 'all';
    const catVal = document.getElementById('menuCategorySelectFilter')?.value || 'all';
    const targetCatId = window.selectedMenuCategoryId || (catVal !== 'all' ? catVal : null);

    if (query) {
        return isAr ? 'لا توجد أصناف تطابق شروط البحث والرؤية' : 'No items match your search criteria';
    }

    if (statusFilter === 'trash') {
        return isAr ? 'سلة مهملات الأصناف فارغة' : 'Menu trash bin is empty';
    }

    if (statusFilter === 'available') {
        return isAr ? 'لا توجد أصناف متوفرة حالياً' : 'No available items found';
    }

    if (statusFilter === 'unavailable') {
        return isAr ? 'لا توجد أصناف غير متوفرة حالياً' : 'No unavailable items found';
    }

    if (statusFilter === 'special') {
        return isAr ? 'لا توجد أصناف مميزة أو عروض حالياً' : 'No featured or special items found';
    }

    if (targetCatId) {
        return isAr ? 'لا توجد أصناف مضافة في هذا القسم بعد' : 'No items added in this category yet';
    }

    const brandVal = document.getElementById('menuBrandSelectFilter')?.value || 'all';
    const targetBrandId = window.selectedMenuBrandId || (brandVal !== 'all' ? brandVal : null);
    if (targetBrandId) {
        return isAr ? 'لا توجد منتجات مرتبطة بهذه العلامة التجارية حالياً' : 'No products linked to this brand yet';
    }

    return isAr ? 'لا توجد أصناف مضافة بالقائمة بعد' : 'No menu items added yet';
}

window.switchCardVariantImage = function(chipEl, varImgUrl, mainImgUrl) {
    if (!chipEl) return;
    if (typeof event !== 'undefined' && event) event.stopPropagation();
    const card = chipEl.closest('.menu-card');
    if (!card) return;
    const cImg = card.querySelector('.menu-card-img img');
    if (cImg) {
        cImg.style.transition = 'opacity 0.15s ease';
        cImg.style.opacity = '0.5';
        setTimeout(() => {
            cImg.src = varImgUrl || mainImgUrl;
            cImg.style.opacity = '1';
        }, 120);
    }
    const siblings = card.querySelectorAll('.luxury-variant-chip');
    siblings.forEach(c => {
        c.style.background = 'rgba(255,255,255,0.06)';
        c.style.borderColor = 'var(--border-subtle)';
        c.style.boxShadow = 'none';
    });
    chipEl.style.background = 'rgba(217, 119, 6, 0.22)';
    chipEl.style.borderColor = '#d97706';
    chipEl.style.boxShadow = '0 0 8px rgba(217, 119, 6, 0.35)';
};

window.getAllChildCategoryIds = function(parentId, categoriesList = window.allCategoriesData || [], ids = new Set()) {
    if (!parentId) return ids;
    ids.add(String(parentId));
    const children = (categoriesList || []).filter(c => String(c.parent_id) === String(parentId));
    children.forEach(c => {
        if (!ids.has(String(c.id))) {
            window.getAllChildCategoryIds(c.id, categoriesList, ids);
        }
    });
    return ids;
};

window.getCategoryEffectivePriceHide = function(catId, explicitTenantId = null) {
    const result = {
        hide_price_override: false,
        hide_retail_price: false,
        hide_wholesale_price: false,
        hide_rep_price: false
    };
    if (!catId) return result;
    const tenantId = explicitTenantId || ((typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01');
    const catList = (window.allCategoriesData || []).filter(c => !c.tenant_id || String(c.tenant_id) === String(tenantId));
    const visited = new Set();
    let currentId = String(catId);

    while (currentId && !visited.has(currentId)) {
        visited.add(currentId);
        const cat = catList.find(c => String(c.id) === currentId);
        if (!cat) break;
        if (cat.hide_price_override === true) {
            result.hide_retail_price = true;
            result.hide_wholesale_price = true;
            result.hide_rep_price = true;
        }
        if (cat.hide_retail_price === true) result.hide_retail_price = true;
        if (cat.hide_wholesale_price === true) result.hide_wholesale_price = true;
        if (cat.hide_rep_price === true) result.hide_rep_price = true;
        currentId = cat.parent_id ? String(cat.parent_id) : '';
    }

    if (result.hide_retail_price && result.hide_wholesale_price && result.hide_rep_price) {
        result.hide_price_override = true;
    }
    return result;
};

window.isItemPriceHidden = function(item, targetType = 'override') {
    if (!item) return false;
    const itemTenantId = item.tenant_id || ((typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01');
    const catHide = item.category_id ? window.getCategoryEffectivePriceHide(item.category_id, itemTenantId) : {
        hide_price_override: false,
        hide_retail_price: false,
        hide_wholesale_price: false,
        hide_rep_price: false
    };

    const itemHideRetail = item.hide_retail_price === true;
    const itemHideWholesale = item.hide_wholesale_price === true;
    const itemHideRep = item.hide_rep_price === true;
    const itemHideAll = (item.hide_price_override === true) || (itemHideRetail && itemHideWholesale && itemHideRep);

    const catHideRetail = catHide.hide_retail_price === true;
    const catHideWholesale = catHide.hide_wholesale_price === true;
    const catHideRep = catHide.hide_rep_price === true;
    const catHideAll = (catHide.hide_price_override === true) || (catHideRetail && catHideWholesale && catHideRep);

    if (targetType === 'retail') return itemHideRetail || itemHideAll || catHideRetail || catHideAll;
    if (targetType === 'wholesale') return itemHideWholesale || itemHideAll || catHideWholesale || catHideAll;
    if (targetType === 'rep') return itemHideRep || itemHideAll || catHideRep || catHideAll;
    if (targetType === 'override' || targetType === 'all') return itemHideAll || catHideAll;

    return itemHideAll || catHideAll;
};

window.quickToggleItemPriceHide = async function(itemId, fieldName) {
    if (!itemId || !fieldName) return;
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = window.getActiveTenantId ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';

    const item = (window.allMenuItemsData || []).find(i => String(i.id) === String(itemId));
    if (!item) return;

    let newStatus = !item[fieldName];
    let updatePayload = {};

    if (fieldName === 'hide_price_override') {
        updatePayload = {
            hide_price_override: false,
            hide_retail_price: newStatus,
            hide_wholesale_price: newStatus,
            hide_rep_price: newStatus
        };
        item.hide_price_override = false;
        item.hide_retail_price = newStatus;
        item.hide_wholesale_price = newStatus;
        item.hide_rep_price = newStatus;
    } else {
        item[fieldName] = newStatus;
        updatePayload[fieldName] = newStatus;
        updatePayload.hide_price_override = false;
        item.hide_price_override = false;
    }

    saveLocalMenuItemOverride(tenantId, item);
    if (typeof renderMenuItems === 'function') renderMenuItems();

    const fieldTitles = {
        hide_price_override: isAr ? 'إخفاء عن الكل' : 'Hide All',
        hide_retail_price: isAr ? 'إخفاء التجزئة' : 'Hide Retail',
        hide_wholesale_price: isAr ? 'إخفاء الجملة' : 'Hide Wholesale',
        hide_rep_price: isAr ? 'إخفاء المناديب' : 'Hide Reps'
    };
    const actionLabel = newStatus ? (isAr ? 'إخفاء' : 'Hidden') : (isAr ? 'إظهار' : 'Visible');
    const msg = isAr
        ? `✨ تم ${actionLabel} ${fieldTitles[fieldName] || ''} للمنتج`
        : `✨ ${fieldTitles[fieldName] || ''} is now ${actionLabel}`;

    if (window.showToast) window.showToast(msg, newStatus ? 'warning' : 'success');

    try {
        let currentPayload = { ...updatePayload };
        let tryCount = 0;
        while (tryCount < 10) {
            tryCount++;
            const res = await supabaseClient.from('menu_items').update(currentPayload).eq('id', itemId).eq('tenant_id', tenantId);
            if (!res.error) break;

            const errCode = res.error.code || '';
            const errMsg = res.error.message || '';
            const isColumnErr = errCode === '42703' || errCode === 'PGRST204' || errMsg.includes('column') || errMsg.includes('schema cache');

            if (isColumnErr) {
                const colMatch = errMsg.match(/Could not find the ['"]([^'"]+)['"] column|column ['"]([^'"]+)['"]/i);
                const missingCol = colMatch ? (colMatch[1] || colMatch[2]) : null;
                if (missingCol && (missingCol in currentPayload)) {
                    delete currentPayload[missingCol];
                    continue;
                }
                const optionalCols = ['hide_rep_price', 'hide_wholesale_price', 'hide_retail_price', 'hide_price_override'];
                let stripped = false;
                for (const col of optionalCols) {
                    if (col in currentPayload) {
                        delete currentPayload[col];
                        stripped = true;
                        break;
                    }
                }
                if (stripped) continue;
            }
            break;
        }
    } catch (_) {}
};

function renderMenuItems() {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const gridWrapper = document.getElementById('menu-grid-wrapper');
    const tableBody = document.getElementById('menu-full-body');
    const alertBox = document.getElementById('menu-category-filter-alert');
    const catNameEl = document.getElementById('menu-filter-cat-name');
    const brandAlertBox = document.getElementById('menu-brand-filter-alert');
    const brandNameEl = document.getElementById('menu-filter-brand-name');

    const searchVal = (document.getElementById('menuSearchInput')?.value || '').trim().toLowerCase();
    const catVal = document.getElementById('menuCategorySelectFilter')?.value || 'all';
    const brandVal = document.getElementById('menuBrandSelectFilter')?.value || 'all';
    const statusVal = document.getElementById('menuStatusFilter')?.value || 'all';
    const sortVal = document.getElementById('menuSortFilter')?.value || 'created_desc';

    const trashedIds = getTrashedMenuItemIds();
    let items = window.allMenuItemsData || [];
    const categories = window.allCategoriesData || [];
    const brands = window.allBrandsData || [];

    // Filter by Category Banner alert
    if (window.selectedMenuCategoryId) {
        const filterCat = categories.find(c => String(c.id) === String(window.selectedMenuCategoryId));
        const filterCatName = filterCat ? (isAr ? filterCat.name_ar : (filterCat.name_en || filterCat.name_ar)) : '';
        if (alertBox && catNameEl) {
            catNameEl.textContent = filterCatName || (isAr ? 'القسم المحدد' : 'Selected Category');
            alertBox.style.display = 'flex';
        }
    } else {
        if (alertBox) alertBox.style.display = 'none';
    }

    // Filter by Brand Banner alert
    if (window.selectedMenuBrandId) {
        const filterBrand = brands.find(b => String(b.id) === String(window.selectedMenuBrandId));
        const filterBrandName = filterBrand ? (isAr ? filterBrand.name_ar : (filterBrand.name_en || filterBrand.name_ar)) : '';
        if (brandAlertBox && brandNameEl) {
            brandNameEl.textContent = filterBrandName || (isAr ? 'العلامة التجارية المحددة' : 'Selected Brand');
            brandAlertBox.style.display = 'flex';
        }
    } else {
        if (brandAlertBox) brandAlertBox.style.display = 'none';
    }

    // Filter by Trash Status
    if (statusVal === 'trash') {
        items = items.filter(i => trashedIds.includes(String(i.id)));
    } else {
        items = items.filter(i => !trashedIds.includes(String(i.id)));

        if (statusVal === 'available') items = items.filter(i => i.is_available !== false);
        if (statusVal === 'unavailable') items = items.filter(i => i.is_available === false);
        if (statusVal === 'special') items = items.filter(i => i.is_special);
    }

function getAllChildCategoryIds(parentId, categoriesList = window.allCategoriesData || [], ids = new Set()) {
    if (!parentId) return ids;
    ids.add(String(parentId));
    const children = categoriesList.filter(c => String(c.parent_id) === String(parentId));
    children.forEach(c => {
        if (!ids.has(String(c.id))) {
            getAllChildCategoryIds(c.id, categoriesList, ids);
        }
    });
    return ids;
}

    // Filter by Selected Category Dropdown or Banner
    const targetCatId = window.selectedMenuCategoryId || (catVal !== 'all' ? catVal : null);
    if (targetCatId) {
        const allowedCatIds = getAllChildCategoryIds(targetCatId, categories);
        const filterCat = categories.find(c => String(c.id) === String(targetCatId));
        items = items.filter(i => {
            if (!i.category_id) return false;
            const matchId = allowedCatIds.has(String(i.category_id).trim());
            const matchName = filterCat && (
                (i.category_name && i.category_name === filterCat.name_ar) ||
                (i.category_name && i.category_name === filterCat.name_en)
            );
            return matchId || matchName;
        });
    }

    // Filter by Selected Brand Dropdown or Banner
    const targetBrandId = window.selectedMenuBrandId || (brandVal !== 'all' ? brandVal : null);
    if (targetBrandId) {
        if (targetBrandId === 'none') {
            items = items.filter(i => !i.brand_id || String(i.brand_id).trim() === '');
        } else {
            items = items.filter(i => i.brand_id && String(i.brand_id).trim() === String(targetBrandId).trim());
        }
    }

    // Search Filter (By Item Name Only)
    if (searchVal) {
        items = items.filter(i => {
            const nameAr = (i.name_ar || '').toLowerCase();
            const nameEn = (i.name_en || '').toLowerCase();
            return nameAr.includes(searchVal) || nameEn.includes(searchVal);
        });
    }

    // Sorting
    items.sort((a, b) => {
        if (sortVal === 'price_asc') return (a.price || 0) - (b.price || 0);
        if (sortVal === 'price_desc') return (b.price || 0) - (a.price || 0);
        if (sortVal === 'name_asc') {
            const nameA = isAr ? (a.name_ar || '') : (a.name_en || '');
            const nameB = isAr ? (b.name_ar || '') : (b.name_en || '');
            return nameA.localeCompare(nameB);
        }
        return new Date(b.created_at || 0) - new Date(a.created_at || 0);
    });

    const isTrashMode = statusVal === 'trash';

    const totalItems = items.length;
    const paginationWrapper = document.getElementById('menu-pagination-wrapper');

    const selectToggleBtn = document.getElementById('btn-toggle-menu-select');
    if (selectToggleBtn) {
        selectToggleBtn.style.display = totalItems > 0 ? 'inline-flex' : 'none';
    }

    const menuSection = document.getElementById('menu-section');
    const tableWrapper = document.getElementById('menu-table-wrapper');

    if (window.isMenuSelectionModeActive) {
        if (gridWrapper) gridWrapper.classList.add('selection-mode-active');
        if (tableWrapper) tableWrapper.classList.add('selection-mode-active');
        if (menuSection) menuSection.classList.add('selection-mode-active');
    } else {
        if (gridWrapper) gridWrapper.classList.remove('selection-mode-active');
        if (tableWrapper) tableWrapper.classList.remove('selection-mode-active');
        if (menuSection) menuSection.classList.remove('selection-mode-active');
    }

    // Empty state
    if (totalItems === 0) {
        window.isMenuSelectionModeActive = false;
        if (window.selectedMenuItemIds) window.selectedMenuItemIds.clear();
        if (selectToggleBtn) selectToggleBtn.style.display = 'none';
        const bulkBar = document.getElementById('menu-bulk-actions-bar');
        if (bulkBar) bulkBar.style.display = 'none';

        const emptyMsg = getMenuItemsEmptyMessage(isAr);

        if (gridWrapper) {
            gridWrapper.classList.remove('selection-mode-active');
            gridWrapper.innerHTML = `<div style="grid-column: 1 / -1; text-align:center; padding:60px 20px; opacity:0.7;"><i class="fas fa-box-open" style="font-size:2.5rem; margin-bottom:12px; display:block; color:var(--primary-gold);"></i><h3 style="font-size:1.1rem; color:var(--text-main); font-weight:700; margin:0;">${emptyMsg}</h3></div>`;
        }
        if (tableBody) tableBody.innerHTML = `<tr><td colspan="8" style="text-align:center; padding:50px; opacity:0.7;"><i class="fas fa-box-open" style="font-size:2rem; margin-bottom:10px; display:block; color:var(--primary-gold);"></i><h3 style="font-size:1rem; color:var(--text-main); font-weight:700; margin:0;">${emptyMsg}</h3></td></tr>`;
        if (paginationWrapper) paginationWrapper.innerHTML = '';
        return;
    }

    // Pagination Calculation (Max 24 Items per page)
    const itemsPerPage = 24;
    const totalPages = Math.ceil(totalItems / itemsPerPage) || 1;
    if (!window.menuCurrentPage || window.menuCurrentPage < 1) window.menuCurrentPage = 1;
    if (window.menuCurrentPage > totalPages) window.menuCurrentPage = totalPages;

    const startIndex = (window.menuCurrentPage - 1) * itemsPerPage;
    const endIndex = Math.min(startIndex + itemsPerPage, totalItems);
    const paginatedItems = items.slice(startIndex, endIndex);

    // Save current page IDs for Select All feature
    window.currentPaginatedMenuItemIds = paginatedItems.map(i => String(i.id));

    const previewUserId = (document.getElementById('menuUserPricingPreviewSelect')?.value || '').trim();

    // Render Grid View
    if (gridWrapper) {
        gridWrapper.innerHTML = paginatedItems.map(item => {
            const cat = categories.find(c => c.id === item.category_id);
            const catName = cat ? (isAr ? cat.name_ar : (cat.name_en || cat.name_ar)) : (isAr ? 'قسم رئيسي' : 'Primary');
            const isAvail = item.is_available !== false;
            const isTrashed = trashedIds.includes(String(item.id));
            const rawVariantsCard = (window.allItemVariantsData || []).filter(v => String(v.item_id) === String(item.id));
            const seenKeysCard = new Set();
            const itemVariants = rawVariantsCard.filter(v => {
                const nameKey = (isAr ? (v.name_ar || v.name_en) : (v.name_en || v.name_ar) || '').trim().toLowerCase();
                const priceKey = String(v.price !== undefined && v.price !== null ? v.price : '');
                const key = `${nameKey}_${priceKey}`;
                if (!nameKey || seenKeysCard.has(key)) return false;
                seenKeysCard.add(key);
                return true;
            });
            const isSelected = window.selectedMenuItemIds ? window.selectedMenuItemIds.has(String(item.id)) : false;

            const itemPriceInfo = previewUserId && typeof window.calculateUserCustomPrice === 'function'
                ? window.calculateUserCustomPrice(item, previewUserId)
                : { finalPrice: item.price, isModified: false };
            const effectiveItemPrice = (itemPriceInfo && itemPriceInfo.finalPrice !== undefined) ? itemPriceInfo.finalPrice : item.price;

            return `
            <div class="menu-card-item glass ${isSelected ? 'selected-card' : ''}" onclick="handleMenuCardClick(event, '${item.id}')">
                <div class="menu-card-img-box" style="position: relative;">
                    <label class="menu-card-checkbox-wrapper" onclick="event.stopPropagation();">
                        <input type="checkbox" class="menu-item-checkbox" value="${item.id}" ${isSelected ? 'checked' : ''} onchange="toggleMenuItemSelection('${item.id}', this.checked)">
                        <span class="custom-card-checkbox"><i class="fas fa-check"></i></span>
                    </label>
                    <img src="${escapeHtml(item.image_url || 'https://cdn.sahalacompany.com/placeholder.webp')}" onerror="this.src='https://cdn.sahalacompany.com/placeholder.webp'" alt="${escapeHtml(item.name_ar)}">
                    ${item.is_special ? `
                        <div class="menu-card-badges" style="position: absolute; top: 10px; left: 10px; right: auto; z-index: 2; pointer-events: none; margin: 0;">
                            <span class="badge gold" title="${isAr ? 'صنف مميز' : 'Special Item'}" style="gap: 4px !important; padding: 3px 8px !important; pointer-events: auto; display: inline-flex !important; align-items: center !important;">
                                <i class="fas fa-star" style="font-size: 0.68rem;"></i>
                                <span>${isAr ? 'مميز' : 'Featured'}</span>
                            </span>
                        </div>
                    ` : ''}
                </div>
                <div class="menu-card-body">
                    <div class="menu-card-title-group">
                        <div class="luxury-card-header-row" style="display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; width: 100%;">
                            <span class="menu-card-title-ar" title="${isAr ? (item.name_ar || item.name_en) : (item.name_en || item.name_ar)}" style="flex: 1; min-width: 0; font-size: 0.95rem; font-weight: 800; line-height: 1.35;">${isAr ? (item.name_ar || item.name_en || '') : (item.name_en || item.name_ar || '')}</span>
                            ${(itemVariants.length === 0 && effectiveItemPrice !== undefined && effectiveItemPrice !== null) ? `
                                <div style="display: flex; flex-direction: column; align-items: flex-end; gap: 2px;">
                                    <span class="luxury-card-price" style="font-size: 1.05rem; font-weight: 800; color: ${itemPriceInfo.isModified ? 'var(--icon-purple)' : 'var(--primary-gold)'}; flex-shrink: 0; display: inline-flex; align-items: center; gap: 4px; direction: ltr;">
                                        ${isAr ? `<span>${getCurrencySymbol()}</span><span>${Number(effectiveItemPrice).toLocaleString()}</span>` : `<span>${Number(effectiveItemPrice).toLocaleString()}</span><span>${getCurrencySymbol()}</span>`}
                                    </span>
                                    ${itemPriceInfo.isModified ? `
                                        <span class="bulk-user-pct-tag ${itemPriceInfo.discountPercent >= 0 ? 'is-pos' : 'is-neg'}" style="font-size: 0.60rem; padding: 1px 5px;" title="${escapeHtml(itemPriceInfo.userName || '')}">
                                            ${itemPriceInfo.discountPercent > 0 ? '+' : ''}${itemPriceInfo.discountPercent}% ${itemPriceInfo.roleLabel}
                                        </span>
                                    ` : ''}
                                </div>
                            ` : ''}
                        </div>
                        <div class="luxury-card-meta-row" style="display: flex; align-items: center; justify-content: space-between; gap: 6px; margin-top: 4px; flex-wrap: wrap;">
                            <span class="menu-card-category-name" style="font-size: 0.78rem; font-weight: 600; color: var(--text-muted);">
                                ${catName}
                            </span>
                            ${(() => {
                                const itemBrand = item.brand_id ? brands.find(b => String(b.id) === String(item.brand_id)) : null;
                                if (!itemBrand) return '';
                                const bName = isAr ? itemBrand.name_ar : (itemBrand.name_en || itemBrand.name_ar);
                                return `<span onclick="event.stopPropagation(); viewBrandMenuItems('${itemBrand.id}')" title="${isAr ? 'العلامة التجارية: ' + bName : 'Brand: ' + bName}" style="font-size: 0.68rem; font-weight: 800; color: var(--primary-gold); background: rgba(217, 119, 6, 0.12); border: 1px solid rgba(217, 119, 6, 0.28); padding: 2px 7px; border-radius: 6px; display: inline-flex; align-items: center; gap: 4px; cursor: pointer;"><i class="fas fa-copyright" style="font-size: 0.62rem;"></i><span>${bName}</span></span>`;
                            })()}
                        </div>
                        ${itemVariants.length > 0 ? `
                            <div class="luxury-variant-chip-list ${itemVariants.length > 3 ? 'has-scroll' : ''}" style="display: flex; flex-direction: row; flex-wrap: nowrap; gap: 4px; margin-top: 8px; width: 100%; ${itemVariants.length > 3 ? 'overflow-x: auto; overflow-y: hidden; padding-bottom: 5px; scrollbar-width: thin;' : 'overflow-x: hidden;'}">
                                ${itemVariants.map(v => {
                                    const vName = isAr ? (v.name_ar || v.name_en) : (v.name_en || v.name_ar);
                                    const hasImg = v.image_url && v.image_url.trim() !== '';
                                    const safeVarImg = (v.image_url || '').replace(/'/g, "\\'");
                                    const safeItemImg = (item.image_url || '').replace(/'/g, "\\'");
                                    const vPriceInfo = previewUserId && typeof window.calculateUserCustomPrice === 'function'
                                        ? window.calculateUserCustomPrice(v, previewUserId)
                                        : { finalPrice: v.price };
                                    const vEffectivePrice = (vPriceInfo && vPriceInfo.finalPrice !== undefined) ? vPriceInfo.finalPrice : v.price;
                                    const formattedPrice = (vEffectivePrice !== undefined && vEffectivePrice !== null && vEffectivePrice !== '') ? Number(vEffectivePrice).toLocaleString('en-US') : '';
                                    return `
                                        <span class="luxury-variant-chip ${itemVariants.length > 3 ? 'chip-scrollable' : ''}" title="${vName}${formattedPrice ? ' - ' + getCurrencySymbol() + ' ' + formattedPrice : ''}" onclick="window.switchCardVariantImage(this, '${safeVarImg}', '${safeItemImg}')" style="${itemVariants.length > 3 ? 'flex: 0 0 auto; min-width: max-content; padding: 4px 8px;' : 'flex: 1 1 0px; min-width: 0; padding: 3px 4px;'} display: inline-flex; align-items: center; justify-content: center; gap: 3px; background: rgba(255,255,255,0.06); border: 1px solid var(--border-subtle); border-radius: 6px; font-size: 0.65rem; font-weight: 700; cursor: pointer; text-align: center; white-space: nowrap; transition: all 0.2s ease;">
                                            ${hasImg ? `<i class="fas fa-image" style="color: var(--icon-purple); font-size: 0.56rem; flex-shrink: 0;" title="${isAr ? 'صورة مخصصة' : 'Custom Image'}"></i>` : ''}
                                            <span class="chip-name" style="color: var(--text-main); font-size: 0.65rem; white-space: nowrap;">${vName}</span>
                                            ${formattedPrice ? `<span class="chip-price" style="color: ${vPriceInfo && vPriceInfo.isModified ? 'var(--icon-purple)' : 'var(--primary-gold)'}; font-size: 0.65rem; font-weight: 800; white-space: nowrap; direction: ltr; flex-shrink: 0; display: inline-flex; align-items: center; gap: 2px;"><span style="font-size:0.56rem;">${getCurrencySymbol()}</span> <span>${formattedPrice}</span></span>` : ''}
                                        </span>
                                    `;
                                }).join('')}
                            </div>
                        ` : `
                            <div class="luxury-single-item-tag" style="margin-top: 8px;">
                                <span style="font-size: 0.72rem; color: var(--text-muted); opacity: 0.7; display: inline-flex; align-items: center; gap: 4px;">
                                    <i class="fas fa-cube" style="font-size: 0.68rem;"></i> ${isAr ? 'صنف مفرد' : 'Single Item'}
                                </span>
                            </div>
                        `}
                    </div>
                    <div class="menu-card-price-bar" style="padding-top: 10px; margin-top: 10px; border-top: 1px dashed var(--border-subtle); display: flex; align-items: center; justify-content: space-between; gap: 4px;">
                        <div class="menu-card-actions" style="display: flex; align-items: center; justify-content: space-between; width: 100%; gap: 4px; flex-wrap: nowrap !important;">
                            ${isTrashed ? `
                                <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 8px; width: 100%;">
                                    <button type="button" onclick="restoreMenuItem('${item.id}')" class="trash-action-btn restore" style="height: 34px !important; border-radius: 10px !important; background: rgba(16, 185, 129, 0.15) !important; color: #10b981 !important; border: 1.5px solid rgba(16, 185, 129, 0.4) !important; font-size: 0.78rem !important; font-weight: 700 !important; display: inline-flex !important; align-items: center !important; justify-content: center !important; gap: 6px !important; cursor: pointer; transition: all 0.25s ease;" title="${isAr ? 'استعادة المنتج إلى الكتالوج' : 'Restore Item'}">
                                        <i class="fas fa-undo" style="font-size: 0.75rem;"></i>
                                        <span style="white-space: nowrap;">${isAr ? 'استعادة' : 'Restore'}</span>
                                    </button>
                                    <button type="button" onclick="permanentlyDeleteMenuItem('${item.id}')" class="trash-action-btn delete" style="height: 34px !important; border-radius: 10px !important; background: rgba(239, 68, 68, 0.15) !important; color: #ef4444 !important; border: 1.5px solid rgba(239, 68, 68, 0.4) !important; font-size: 0.78rem !important; font-weight: 700 !important; display: inline-flex !important; align-items: center !important; justify-content: center !important; gap: 6px !important; cursor: pointer; transition: all 0.25s ease;" title="${isAr ? 'حذف نهائي من النظام' : 'Delete Permanently'}">
                                        <i class="fas fa-trash-alt" style="font-size: 0.75rem;"></i>
                                        <span style="white-space: nowrap;">${isAr ? 'حذف نهائي' : 'Delete'}</span>
                                    </button>
                                </div>
                            ` : `
                                <button type="button" onclick="toggleMenuItemAvailability('${item.id}')" class="category-status-toggle-btn ${isAvail ? 'active' : 'hidden'}" title="${isAr ? (isAvail ? 'الصنف متوفر (انقر للتعيين كـ غير متوفر)' : 'الصنف غير متوفر (انقر للتعيين كـ متوفر)') : (isAvail ? 'Item Available (Click to hide)' : 'Item Unavailable (Click to show)')}" style="padding: 0 6px !important; font-size: 0.68rem !important; height: 30px !important; min-height: 30px !important; gap: 4px !important; flex-shrink: 0; border-radius: 8px !important;">
                                    <span class="switch-track ${isAvail ? 'active' : ''}"><span class="switch-knob"></span></span>
                                    <span>${isAr ? (isAvail ? 'متوفر' : 'غير متوفر') : (isAvail ? 'Available' : 'Unavailable')}</span>
                                </button>
                                <div style="display: flex; gap: 4px; align-items: center; flex-wrap: nowrap !important;">
                                    <button type="button" onclick="duplicateMenuItem('${item.id}')" class="btn-action view" title="${isAr ? 'تكرار/نسخ الصنف' : 'Duplicate Item'}" style="width: auto !important; height: 30px !important; padding: 0 7px !important; border-radius: 8px !important; display: inline-flex !important; align-items: center !important; gap: 3px !important; font-weight: 700 !important; font-size: 0.70rem !important; white-space: nowrap !important; flex-shrink: 0;">
                                        <i class="fas fa-copy" style="font-size: 0.70rem;"></i>
                                        <span>${isAr ? 'تكرار' : 'Copy'}</span>
                                    </button>
                                    <button type="button" onclick="editMenuItem('${item.id}')" class="btn-action edit" title="${isAr ? 'تعديل' : 'Edit'}" style="width: auto !important; height: 30px !important; padding: 0 7px !important; border-radius: 8px !important; display: inline-flex !important; align-items: center !important; gap: 3px !important; font-weight: 700 !important; font-size: 0.70rem !important; white-space: nowrap !important; flex-shrink: 0;">
                                        <i class="fas fa-pen" style="font-size: 0.70rem;"></i>
                                        <span>${isAr ? 'تعديل' : 'Edit'}</span>
                                    </button>
                                    <button type="button" onclick="deleteMenuItem('${item.id}')" class="btn-action delete" title="${isAr ? 'حذف إلى السلة' : 'Delete'}" style="width: auto !important; height: 30px !important; padding: 0 7px !important; border-radius: 8px !important; display: inline-flex !important; align-items: center !important; gap: 3px !important; font-weight: 700 !important; font-size: 0.70rem !important; white-space: nowrap !important; flex-shrink: 0;">
                                        <i class="fas fa-trash-alt" style="font-size: 0.70rem;"></i>
                                        <span>${isAr ? 'حذف' : 'Delete'}</span>
                                    </button>
                                </div>
                            `}
                        </div>
                    </div>
                </div>
            </div>`;
        }).join('');
    }

    // Render Table View
    if (tableBody) {
        tableBody.innerHTML = paginatedItems.map(item => {
            const cat = categories.find(c => c.id === item.category_id);
            const catName = cat ? (isAr ? cat.name_ar : (cat.name_en || cat.name_ar)) : '---';
            const isAvail = item.is_available !== false;
            const isTrashed = trashedIds.includes(String(item.id));
            const rawVariantsTable = (window.allItemVariantsData || []).filter(v => String(v.item_id) === String(item.id));
            const seenKeysTable = new Set();
            const itemVariants = rawVariantsTable.filter(v => {
                const nameKey = (isAr ? (v.name_ar || v.name_en) : (v.name_en || v.name_ar) || '').trim().toLowerCase();
                const priceKey = String(v.price !== undefined && v.price !== null ? v.price : '');
                const key = `${nameKey}_${priceKey}`;
                if (!nameKey || seenKeysTable.has(key)) return false;
                seenKeysTable.add(key);
                return true;
            });
            const isSelected = window.selectedMenuItemIds ? window.selectedMenuItemIds.has(String(item.id)) : false;

            const itemPriceInfo = previewUserId && typeof window.calculateUserCustomPrice === 'function'
                ? window.calculateUserCustomPrice(item, previewUserId)
                : { finalPrice: item.price, isModified: false };
            const effectiveItemPrice = (itemPriceInfo && itemPriceInfo.finalPrice !== undefined) ? itemPriceInfo.finalPrice : item.price;

            return `
            <tr class="mastery-row ${isSelected ? 'selected-row' : ''}">
                <td class="col-select" style="text-align: center; vertical-align: middle; width: 45px;">
                    <label class="menu-card-checkbox-wrapper" style="position:static;" onclick="event.stopPropagation();">
                        <input type="checkbox" class="menu-item-checkbox" value="${item.id}" ${isSelected ? 'checked' : ''} onchange="toggleMenuItemSelection('${item.id}', this.checked)">
                        <span class="custom-card-checkbox"><i class="fas fa-check"></i></span>
                    </label>
                </td>
                <td style="text-align: center; vertical-align: middle; width: 75px;">
                    <div class="menu-thumb-box">
                        <img src="${escapeHtml(item.image_url || 'https://cdn.sahalacompany.com/placeholder.webp')}" onerror="this.src='https://cdn.sahalacompany.com/placeholder.webp'" alt="${escapeHtml(item.name_ar)}">
                    </div>
                </td>
                <td style="text-align: ${isAr ? 'right' : 'left'}; vertical-align: middle;">
                    <div class="menu-item-info">
                        <div style="display: inline-flex; align-items: center; gap: 6px; flex-wrap: nowrap;">
                            <strong class="menu-item-name-ar">${escapeHtml(isAr ? (item.name_ar || item.name_en) : (item.name_en || item.name_ar))}</strong>
                            ${item.is_special ? `
                                <span class="badge gold" style="font-size:0.68rem !important; padding:2px 8px !important; border-radius:12px !important; display:inline-flex !important; align-items:center !important; gap:4px !important; flex-shrink:0; font-weight:800 !important;" title="${isAr ? 'صنف مميز' : 'Special Item'}">
                                    <i class="fas fa-star" style="font-size:0.68rem !important;"></i>
                                    <span>${isAr ? 'مميز' : 'Featured'}</span>
                                </span>
                            ` : ''}
                        </div>
                    </div>
                </td>
                <td style="text-align: center; vertical-align: middle; min-width: 220px;">
                    ${itemVariants.length > 0 ? `
                        <div class="table-variant-chips-wrapper ${itemVariants.length > 3 ? 'has-scroll' : ''}" style="display: flex; flex-direction: column; gap: 6px; align-items: center; justify-content: flex-start; width: 100%; max-width: 205px; margin: 0 auto; ${itemVariants.length > 3 ? 'max-height: 122px; overflow-y: auto; overflow-x: hidden; padding: 4px 6px; scrollbar-width: thin;' : 'padding: 4px 0;'}">
                            ${itemVariants.map(v => {
                                const vName = isAr ? (v.name_ar || v.name_en) : (v.name_en || v.name_ar);
                                const vPriceInfo = previewUserId && typeof window.calculateUserCustomPrice === 'function'
                                    ? window.calculateUserCustomPrice(v, previewUserId)
                                    : { finalPrice: v.price, isModified: false };
                                const effectiveVPrice = (vPriceInfo && vPriceInfo.finalPrice !== undefined) ? vPriceInfo.finalPrice : v.price;
                                const formattedVPrice = (effectiveVPrice !== undefined && effectiveVPrice !== null && effectiveVPrice !== '') ? Number(effectiveVPrice).toLocaleString('en-US') : '';
                                return `
                                    <div class="table-variant-pill" title="${vName}" style="display: inline-flex; align-items: center; justify-content: space-between; gap: 8px; padding: 4px 10px; border-radius: 8px; background: rgba(255,255,255,0.05); border: 1px solid var(--border-subtle); width: 100%; flex-shrink: 0; box-sizing: border-box;">
                                        <span class="tv-name" style="font-size: 0.76rem; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${vName}</span>
                                        ${formattedVPrice ? `
                                            <span class="tv-price" style="font-size: 0.74rem; font-weight: 800; color: ${vPriceInfo.isModified ? 'var(--icon-purple)' : 'var(--primary-gold)'}; background: ${vPriceInfo.isModified ? 'rgba(217,119,6,0.15)' : 'rgba(212,175,55,0.12)'}; padding: 2px 6px; border-radius: 6px; flex-shrink: 0; display: inline-flex; align-items: center; gap: 3px; direction: ltr;">
                                                <span>${getCurrencySymbol()}</span> <span>${formattedVPrice}</span>
                                                ${vPriceInfo.isModified ? `<span style="font-size:0.60rem; opacity:0.85;">(${vPriceInfo.discountPercent > 0 ? '+' : ''}${vPriceInfo.discountPercent}%)</span>` : ''}
                                            </span>` : ''}
                                    </div>
                                `;
                            }).join('')}
                        </div>
                    ` : `
                        <div class="table-price-stack" style="display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; padding: 4px 0;">
                            <div style="display: flex; align-items: center; gap: 6px;">
                                <span class="price-gold-badge" style="font-size: 0.95rem; font-weight: 800; color: ${itemPriceInfo.isModified ? 'var(--icon-purple)' : 'var(--primary-gold)'}; background: ${itemPriceInfo.isModified ? 'rgba(217,119,6,0.16)' : 'rgba(212,175,55,0.14)'}; border: 1px solid ${itemPriceInfo.isModified ? 'rgba(217,119,6,0.38)' : 'rgba(212,175,55,0.32)'}; padding: 4px 12px; border-radius: 8px; box-shadow: 0 2px 8px rgba(212,175,55,0.15); display: inline-flex; align-items: center; gap: 4px; direction: ltr;" title="${isAr ? 'سعر الصنف' : 'Item Price'}">
                                    <span>${getCurrencySymbol()}</span> <span>${(effectiveItemPrice !== undefined && effectiveItemPrice !== null && effectiveItemPrice !== '') ? Number(effectiveItemPrice).toLocaleString('en-US') : '0'}</span>
                                </span>
                            </div>
                            ${itemPriceInfo.isModified ? `
                                <span class="bulk-user-pct-tag ${itemPriceInfo.discountPercent >= 0 ? 'is-pos' : 'is-neg'}" style="font-size: 0.65rem; padding: 1px 6px; border-radius: 4px; font-weight: 700;">
                                    ${itemPriceInfo.discountPercent > 0 ? '+' : ''}${itemPriceInfo.discountPercent}% ${itemPriceInfo.roleLabel}
                                </span>
                            ` : `
                                <span class="table-single-badge" style="font-size: 0.68rem; font-weight: 600; color: var(--text-muted); opacity: 0.7; margin-top: 1px;">
                                    <i class="fas fa-cube" style="font-size: 0.65rem;"></i> ${isAr ? 'صنف مفرد' : 'Single Item'}
                                </span>
                            `}
                        </div>
                    `}
                </td>
                <td style="text-align: center; vertical-align: middle; min-width: 150px;">
                    <div style="display: flex; flex-direction: column; align-items: center; gap: 4px;">
                        <span class="category-badge-pill" style="max-width: none !important; white-space: nowrap !important;">${catName}</span>
                        ${(() => {
                            const itemBrand = item.brand_id ? brands.find(b => String(b.id) === String(item.brand_id)) : null;
                            if (!itemBrand) return '';
                            const bName = isAr ? itemBrand.name_ar : (itemBrand.name_en || itemBrand.name_ar);
                            return `<span onclick="event.stopPropagation(); viewBrandMenuItems('${itemBrand.id}')" style="font-size: 0.68rem; font-weight: 800; color: var(--primary-gold); background: rgba(217, 119, 6, 0.12); border: 1px solid rgba(217, 119, 6, 0.28); padding: 2px 8px; border-radius: 6px; display: inline-flex; align-items: center; gap: 4px; cursor: pointer;"><i class="fas fa-copyright" style="font-size: 0.62rem;"></i><span>${bName}</span></span>`;
                        })()}
                    </div>
                </td>
                <td style="text-align: center; vertical-align: middle; width: 150px;">
                    <button type="button" onclick="toggleMenuItemAvailability('${item.id}')" class="category-status-toggle-btn ${isAvail ? 'active' : 'hidden'}" title="${isAr ? 'انقر لتغيير الحالة' : 'Click to toggle status'}">
                        <span class="switch-track ${isAvail ? 'active' : ''}"><span class="switch-knob"></span></span>
                        <span style="white-space: nowrap;">${isAr ? (isAvail ? 'متوفر' : 'غير متوفر') : (isAvail ? 'Available' : 'Unavailable')}</span>
                    </button>
                </td>
                <td style="text-align: center; vertical-align: middle; width: 150px;">
                    <div class="actions-group" style="justify-content: center;">
                        ${isTrashed ? `
                            <button onclick="restoreMenuItem('${item.id}')" class="btn-action edit" title="${isAr ? 'استعادة' : 'Restore'}"><i class="fas fa-undo"></i></button>
                            <button onclick="permanentlyDeleteMenuItem('${item.id}')" class="btn-action delete" title="${isAr ? 'حذف نهائي' : 'Delete permanently'}"><i class="fas fa-trash-alt"></i></button>
                        ` : `
                            <button onclick="duplicateMenuItem('${item.id}')" class="btn-action view" title="${isAr ? 'تكرار الصنف' : 'Duplicate'}"><i class="fas fa-copy"></i></button>
                            <button onclick="editMenuItem('${item.id}')" class="btn-action edit" title="${isAr ? 'تعديل' : 'Edit'}"><i class="fas fa-pen"></i></button>
                            <button onclick="deleteMenuItem('${item.id}')" class="btn-action delete" title="${isAr ? 'حذف للسلة' : 'Delete'}"><i class="fas fa-trash-alt"></i></button>
                        `}
                    </div>
                </td>
            </tr>`;
        }).join('');
    }

    // Update Bulk Actions Bar UI
    updateMenuBulkBarUI(isTrashMode, isAr);

    // Render Pagination Controls
    renderMenuPagination(totalItems, totalPages, window.menuCurrentPage, startIndex + 1, endIndex, isAr);
}

window.selectedMenuItemIds = window.selectedMenuItemIds || new Set();

window.handleMenuCardClick = (e, itemId) => {
    if (e.target.closest('.menu-card-actions, .btn-action, .category-items-link-btn, .category-status-toggle-btn, button, a, .menu-card-variants-box')) {
        return;
    }

    if (window.isMenuSelectionModeActive || (window.selectedMenuItemIds && window.selectedMenuItemIds.size > 0)) {
        const isSelected = window.selectedMenuItemIds.has(String(itemId));
        toggleMenuItemSelection(itemId, !isSelected);
    }
};

function toggleMenuItemSelection(itemId, isChecked) {
    const idStr = String(itemId);
    if (isChecked) {
        window.selectedMenuItemIds.add(idStr);
    } else {
        window.selectedMenuItemIds.delete(idStr);
    }
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const statusVal = document.getElementById('menuStatusFilter')?.value || 'all';
    updateMenuBulkBarUI(statusVal === 'trash', isAr);
    renderMenuItems();
}

function toggleSelectAllMenuItems(isChecked) {
    const pageIds = window.currentPaginatedMenuItemIds || [];
    pageIds.forEach(id => {
        if (isChecked) {
            window.selectedMenuItemIds.add(String(id));
        } else {
            window.selectedMenuItemIds.delete(String(id));
        }
    });
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const statusVal = document.getElementById('menuStatusFilter')?.value || 'all';
    updateMenuBulkBarUI(statusVal === 'trash', isAr);
    renderMenuItems();
}

function clearSelectedMenuItems() {
    window.selectedMenuItemIds.clear();
    window.isMenuSelectionModeActive = false;
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const statusVal = document.getElementById('menuStatusFilter')?.value || 'all';
    updateMenuBulkBarUI(statusVal === 'trash', isAr);
    renderMenuItems();
}

function updateMenuBulkBarUI(isTrashMode, isAr) {
    const bulkBar = document.getElementById('menu-bulk-actions-bar');
    const selectAllCheckbox = document.getElementById('menuSelectAllCheckbox');
    const tableSelectAll = document.getElementById('menuTableSelectAll');
    const selectAllText = document.getElementById('menuSelectAllText');
    const selectedCountText = document.getElementById('menuSelectedCountText');
    const deleteBtnText = document.getElementById('btnBulkDeleteMenuText');

    const btnAvail = document.getElementById('btnBulkAvailableMenu');
    const btnUnavail = document.getElementById('btnBulkUnavailableMenu');
    const btnTrash = document.getElementById('btnBulkTrashMenu');
    const btnRestore = document.getElementById('btnBulkRestoreMenu');
    const btnPermDel = document.getElementById('btnBulkPermDeleteMenu');

    if (isTrashMode) {
        if (btnAvail) btnAvail.style.display = 'none';
        if (btnUnavail) btnUnavail.style.display = 'none';
        if (btnTrash) btnTrash.style.display = 'none';
        if (btnRestore) btnRestore.style.display = 'inline-flex';
        if (btnPermDel) btnPermDel.style.display = 'inline-flex';
    } else {
        if (btnAvail) btnAvail.style.display = 'inline-flex';
        if (btnUnavail) btnUnavail.style.display = 'inline-flex';
        if (btnTrash) btnTrash.style.display = 'inline-flex';
        if (btnRestore) btnRestore.style.display = 'none';
        if (btnPermDel) btnPermDel.style.display = 'none';
    }

    const selectedCount = window.selectedMenuItemIds ? window.selectedMenuItemIds.size : 0;
    const pageIds = window.currentPaginatedMenuItemIds || [];
    const allPageSelected = pageIds.length > 0 && pageIds.every(id => window.selectedMenuItemIds.has(String(id)));

    if (selectAllCheckbox) selectAllCheckbox.checked = allPageSelected;
    if (tableSelectAll) tableSelectAll.checked = allPageSelected;

    if (selectAllText) {
        selectAllText.textContent = isAr ? `تحديد الكل (${pageIds.length})` : `Select All (${pageIds.length})`;
    }

    if (bulkBar) {
        if (isTrashMode) {
            bulkBar.classList.add('trash-mode-active');
        } else {
            bulkBar.classList.remove('trash-mode-active');
        }

        if (window.isMenuSelectionModeActive || selectedCount > 0) {
            bulkBar.style.display = 'flex';
        } else {
            bulkBar.style.display = 'none';
        }
    }

    if (selectedCountText) {
        selectedCountText.textContent = isAr ? `تم تحديد ${selectedCount} صنف` : `${selectedCount} selected`;
    }

    if (deleteBtnText) {
        if (isTrashMode) {
            deleteBtnText.textContent = isAr ? 'حذف نهائي للمحددة' : 'Delete Permanently';
        } else {
            deleteBtnText.textContent = isAr ? 'نقل إلى المهملات' : 'Move to Trash';
        }
    }

    const toggleBtn = document.getElementById('btn-toggle-menu-select');
    const toggleLabel = document.getElementById('btnSelectAllLabel');
    if (toggleBtn && toggleLabel) {
        if (window.isMenuSelectionModeActive) {
            toggleBtn.classList.add('active-selected');
            toggleLabel.textContent = isAr ? 'إلغاء التحديد' : 'Deselect';
        } else {
            toggleBtn.classList.remove('active-selected');
            toggleLabel.textContent = isAr ? 'تحديد' : 'Select';
        }
    }
}

function updateSectionsBulkBarUI(isTrashMode, isAr) {
    const bulkBar = document.getElementById('sections-bulk-actions-bar');
    const selectAllCheckbox = document.getElementById('sectionsSelectAllCheckbox');
    const selectedCountText = document.getElementById('sectionsSelectedCountText');

    const selectedCount = window.selectedSectionIds ? window.selectedSectionIds.size : 0;
    const pageCats = window.currentPaginatedSections || [];
    const allPageSelected = pageCats.length > 0 && pageCats.every(cat => window.selectedSectionIds.has(String(cat.id)));

    if (selectAllCheckbox) selectAllCheckbox.checked = allPageSelected;

    if (bulkBar) {
        if (isTrashMode) {
            bulkBar.classList.add('trash-mode-active');
        } else {
            bulkBar.classList.remove('trash-mode-active');
        }

        bulkBar.style.display = (window.isSectionsSelectionModeActive || selectedCount > 0) ? 'flex' : 'none';
    }

    if (selectedCountText) {
        selectedCountText.textContent = isAr ? `تم تحديد ${selectedCount} قسم` : `${selectedCount} selected`;
    }

    const btnActive = document.getElementById('btnBulkActiveSections');
    const btnHidden = document.getElementById('btnBulkHiddenSections');
    const btnTrash = document.getElementById('btnBulkTrashSections');
    const btnRestore = document.getElementById('btnBulkRestoreSections');
    const btnPermDel = document.getElementById('btnBulkPermDelSections');

    if (isTrashMode) {
        if (btnActive) btnActive.style.display = 'none';
        if (btnHidden) btnHidden.style.display = 'none';
        if (btnTrash) btnTrash.style.display = 'none';
        if (btnRestore) btnRestore.style.display = 'inline-flex';
        if (btnPermDel) btnPermDel.style.display = 'inline-flex';
    } else {
        if (btnActive) btnActive.style.display = 'inline-flex';
        if (btnHidden) btnHidden.style.display = 'inline-flex';
        if (btnTrash) btnTrash.style.display = 'inline-flex';
        if (btnRestore) btnRestore.style.display = 'none';
        if (btnPermDel) btnPermDel.style.display = 'none';
    }

    const toggleBtn = document.getElementById('btn-toggle-sections-select');
    const toggleLabel = document.getElementById('btnSelectSectionsAllLabel');
    if (toggleBtn && toggleLabel) {
        if (window.isSectionsSelectionModeActive) {
            toggleBtn.classList.add('active-selected');
            toggleLabel.textContent = isAr ? 'إلغاء التحديد' : 'Deselect';
        } else {
            toggleBtn.classList.remove('active-selected');
            toggleLabel.textContent = isAr ? 'تحديد' : 'Select';
        }
    }
}

window.toggleMenuSelectionMode = () => {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const btn = document.getElementById('btn-toggle-menu-select');
    const label = document.getElementById('btnSelectAllLabel');

    const pageIds = window.currentPaginatedMenuItemIds || [];
    if (pageIds.length === 0) {
        showToast(isAr ? 'لا توجد أصناف قابلة للتحديد في هذه الصفحة' : 'No items to select on this page', 'warning');
        return;
    }

    if (window.isMenuSelectionModeActive) {
        // Exiting selection mode -> deselect all and hide checkboxes
        window.isMenuSelectionModeActive = false;
        if (window.selectedMenuItemIds) window.selectedMenuItemIds.clear();
        if (btn) btn.classList.remove('active-selected');
        if (label) label.textContent = isAr ? 'تحديد' : 'Select';
    } else {
        // Entering selection mode -> show checkboxes without auto-selecting items
        window.isMenuSelectionModeActive = true;
        if (btn) btn.classList.add('active-selected');
        if (label) label.textContent = isAr ? 'إلغاء التحديد' : 'Deselect';
    }

    const statusVal = document.getElementById('menuStatusFilter')?.value || 'all';
    updateMenuBulkBarUI(statusVal === 'trash', isAr);
    renderMenuItems();
};

if (!window.selectedSectionIds) window.selectedSectionIds = new Set();

window.handleSectionCardClick = (event, catId) => {
    if (!window.isSectionsSelectionModeActive) return;
    if (event.target.closest('button, a, input, select, label')) return;

    const isSelected = window.selectedSectionIds ? window.selectedSectionIds.has(String(catId)) : false;
    toggleSectionSelection(catId, !isSelected);
};

window.toggleSectionSelection = (id, isChecked) => {
    if (!window.selectedSectionIds) window.selectedSectionIds = new Set();
    if (isChecked) {
        window.selectedSectionIds.add(String(id));
    } else {
        window.selectedSectionIds.delete(String(id));
    }
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const statusVal = document.getElementById('sectionsStatusFilter')?.value || 'all';
    if (typeof updateSectionsBulkBarUI === 'function') {
        updateSectionsBulkBarUI(statusVal === 'trash', isAr);
    }
    filterSectionsTable(false);
};

window.toggleSelectAllSections = (isChecked) => {
    if (!window.selectedSectionIds) window.selectedSectionIds = new Set();
    const pageCats = window.currentPaginatedSections || [];
    pageCats.forEach(cat => {
        if (isChecked) {
            window.selectedSectionIds.add(String(cat.id));
        } else {
            window.selectedSectionIds.delete(String(cat.id));
        }
    });
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const statusVal = document.getElementById('sectionsStatusFilter')?.value || 'all';
    if (typeof updateSectionsBulkBarUI === 'function') {
        updateSectionsBulkBarUI(statusVal === 'trash', isAr);
    }
    filterSectionsTable(false);
};

window.clearSelectedSections = () => {
    if (window.selectedSectionIds) window.selectedSectionIds.clear();
    window.isSectionsSelectionModeActive = false;
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const statusVal = document.getElementById('sectionsStatusFilter')?.value || 'all';
    if (typeof updateSectionsBulkBarUI === 'function') {
        updateSectionsBulkBarUI(statusVal === 'trash', isAr);
    }
    filterSectionsTable(false);
};

window.bulkUpdateSectionsStatus = async (isActive) => {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const selectedIds = Array.from(window.selectedSectionIds || []);
    if (selectedIds.length === 0) {
        showToast(isAr ? 'يرجى تحديد قسم واحد على الأقل لتنفيذ هذا الإجراء' : 'Please select at least one section first', 'warning');
        return;
    }

    const selectedCats = (window.allCategoriesData || []).filter(c => selectedIds.includes(String(c.id)));
    const allAlreadyMatching = selectedCats.length > 0 && selectedCats.every(c => (c.is_active !== false) === isActive);

    if (allAlreadyMatching) {
        const stateWord = isActive ? (isAr ? 'مفعلة' : 'active') : (isAr ? 'مخفية' : 'hidden');
        showToast(isAr ? `ℹ️ جميع الأقسام المحددة (${selectedIds.length} قسم) ${stateWord} بالفعل!` : `All selected sections are already ${stateWord}!`, 'info');
        if (window.selectedSectionIds) window.selectedSectionIds.clear();
        window.isSectionsSelectionModeActive = true;
        const statusVal = document.getElementById('sectionsStatusFilter')?.value || 'all';
        if (typeof updateSectionsBulkBarUI === 'function') updateSectionsBulkBarUI(statusVal === 'trash', isAr);
        filterSectionsTable(false);
        return;
    }

    const statusText = isActive ? (isAr ? 'تفعيل' : 'Activate') : (isAr ? 'إخفاء' : 'Hide');
    showToast(isAr ? `جاري ${statusText} ${selectedIds.length} قسم...` : `Updating status for ${selectedIds.length} sections...`, 'info');

    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    let trashedIds = getTrashedCategoryIds();
    trashedIds = trashedIds.filter(id => !selectedIds.includes(String(id)));
    setTrashedCategoryIds(trashedIds);

    (window.allCategoriesData || []).forEach(cat => {
        if (selectedIds.includes(String(cat.id))) {
            cat.is_active = isActive;
            saveLocalCategoryOverride(tenantId, cat);
        }
    });

    try {
        await supabaseClient.from('categories').update({ is_active: isActive }).in('id', selectedIds).eq('tenant_id', tenantId);
    } catch (e) {
        console.warn('Supabase bulk sections status note:', e);
    }

    if (window.selectedSectionIds) window.selectedSectionIds.clear();
    window.isSectionsSelectionModeActive = true;
    updateSectionsKPIStats(window.allCategoriesData || []);
    filterSectionsTable(false);
    showToast(isAr ? `✨ تم ${statusText} ${selectedIds.length} قسم بنجاح` : `Updated ${selectedIds.length} sections`, 'success');
};

window.bulkDeleteSections = async (isPermanent = false) => {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const selectedIds = Array.from(window.selectedSectionIds || []);
    if (selectedIds.length === 0) {
        showToast(isAr ? 'يرجى تحديد قسم واحد على الأقل لتنفيذ هذا الإجراء' : 'Please select at least one section first', 'warning');
        return;
    }

    const statusVal = document.getElementById('sectionsStatusFilter')?.value || 'all';
    const isTrashMode = statusVal === 'trash' || isPermanent === true;

    if (isTrashMode) {
        const confirmMsg = isAr ?
            `هل أنت متأكد من حذف ${selectedIds.length} قسم بشكل نهائي من قاعدة البيانات؟` :
            `Are you sure you want to permanently delete ${selectedIds.length} sections?`;

        openConfirm(confirmMsg);
        document.getElementById('confirmDeleteBtn').onclick = async () => {
            closeConfirmModal();
            showToast(isAr ? `جاري الحذف النهائي لـ ${selectedIds.length} قسم...` : `Permanently deleting ${selectedIds.length} sections...`, 'info');

            try {
                const catsToDelete = (window.allCategoriesData || []).filter(cat => selectedIds.includes(String(cat.id)));
                for (const c of catsToDelete) {
                    if (c.image_url && typeof window.deleteSectionImageSmart === 'function') {
                        await window.deleteSectionImageSmart(c.image_url, c.image_source, c.r2_key, c.id);
                    }
                    removeLocalCategoryOverride(tenantId, c.id);
                }
                await supabaseClient.from('categories').delete().in('id', selectedIds).eq('tenant_id', tenantId);
            } catch (e) {
                console.warn('Supabase bulk permanent delete sections note:', e);
            }

            selectedIds.forEach(id => removeLocalCategoryOverride(tenantId, id));
            window.allCategoriesData = (window.allCategoriesData || []).filter(cat => !selectedIds.includes(String(cat.id)));
            if (window.selectedSectionIds) window.selectedSectionIds.clear();
            window.isSectionsSelectionModeActive = true;
            updateSectionsKPIStats(window.allCategoriesData || []);
            filterSectionsTable(false);
            showToast(isAr ? `🗑️ تم الحذف النهائي لـ ${selectedIds.length} قسم` : `Permanently deleted ${selectedIds.length} sections`, 'success');
        };
        return;
    } else {
        showToast(isAr ? `جاري نقل ${selectedIds.length} قسم إلى سلة المهملات...` : `Moving ${selectedIds.length} sections to trash...`, 'warning');

        let trashedIds = getTrashedCategoryIds();
        selectedIds.forEach(id => {
            if (!trashedIds.includes(String(id))) trashedIds.push(String(id));
        });
        setTrashedCategoryIds(trashedIds);

        try {
            await supabaseClient.from('categories').update({ is_active: false }).in('id', selectedIds).eq('tenant_id', tenantId);
        } catch (e) {
            console.warn('Supabase bulk trash sections note:', e);
        }

        (window.allCategoriesData || []).forEach(cat => {
            if (selectedIds.includes(String(cat.id))) {
                cat.is_active = false;
            }
        });

        if (window.selectedSectionIds) window.selectedSectionIds.clear();
        window.isSectionsSelectionModeActive = true;
        updateSectionsKPIStats(window.allCategoriesData || []);
        filterSectionsTable(false);
        showToast(isAr ? `🗑️ تم نقل ${selectedIds.length} قسم إلى سلة المهملات` : `Moved ${selectedIds.length} sections to trash`, 'warning');
    }
};

