function changeMenuPage(page) {
    if (window.menuCurrentPage === page) return;

    const gridWrapper = document.getElementById('menu-grid-wrapper');
    const tableWrapper = document.getElementById('menu-table-wrapper');
    const targetContainers = [gridWrapper, tableWrapper].filter(Boolean);

    targetContainers.forEach(el => el.classList.add('page-fade-transition'));

    setTimeout(() => {
        window.menuCurrentPage = page;
        renderMenuItems();

        const menuSection = document.getElementById('menu-section');
        if (menuSection) {
            menuSection.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }

        setTimeout(() => {
            targetContainers.forEach(el => el.classList.remove('page-fade-transition'));
        }, 30);
    }, 120);
}

function renderMenuPagination(totalItems, totalPages, currentPage, startNum, endNum, isAr) {
    const paginationWrapper = document.getElementById('menu-pagination-wrapper');
    if (!paginationWrapper) return;

    if (totalItems === 0) {
        paginationWrapper.innerHTML = '';
        return;
    }

    const prevLabel = isAr ? 'السابق' : 'Prev';
    const nextLabel = isAr ? 'التالي' : 'Next';
    const showingText = isAr ?
        `عرض <strong>${startNum} - ${endNum}</strong> من أصل <strong>${totalItems}</strong> صنف` :
        `Showing <strong>${startNum} - ${endNum}</strong> of <strong>${totalItems}</strong> items`;

    let pageNumbers = [];
    if (totalPages <= 7) {
        for (let i = 1; i <= totalPages; i++) pageNumbers.push(i);
    } else {
        if (currentPage <= 4) {
            pageNumbers = [1, 2, 3, 4, 5, '...', totalPages];
        } else if (currentPage >= totalPages - 3) {
            pageNumbers = [1, '...', totalPages - 4, totalPages - 3, totalPages - 2, totalPages - 1, totalPages];
        } else {
            pageNumbers = [1, '...', currentPage - 1, currentPage, currentPage + 1, '...', totalPages];
        }
    }

    const pagesHtml = pageNumbers.map(p => {
        if (p === '...') {
            return `<span class="pagination-dots">...</span>`;
        }
        const isActive = p === currentPage ? 'active' : '';
        return `<button type="button" class="pagination-btn ${isActive}" onclick="changeMenuPage(${p})">${p}</button>`;
    }).join('');

    paginationWrapper.innerHTML = `
        <div class="menu-pagination-container">
            <div class="pagination-info">
                <i class="fas fa-list-ol" style="color:var(--primary-gold);"></i> ${showingText}
            </div>
            <div class="pagination-controls">
                <button type="button" class="pagination-btn" ${currentPage === 1 ? 'disabled' : ''} onclick="changeMenuPage(${currentPage - 1})">
                    <i class="fas ${isAr ? 'fa-chevron-right' : 'fa-chevron-left'}"></i> ${prevLabel}
                </button>
                ${pagesHtml}
                <button type="button" class="pagination-btn" ${currentPage === totalPages ? 'disabled' : ''} onclick="changeMenuPage(${currentPage + 1})">
                    ${nextLabel} <i class="fas ${isAr ? 'fa-chevron-left' : 'fa-chevron-right'}"></i>
                </button>
            </div>
        </div>
    `;
}

function filterMenuTable() {
    window.menuCurrentPage = 1;
    renderMenuItems();
}

function setMenuViewMode(mode) {
    window.menuViewMode = mode;
    const btnGrid = document.getElementById('btn-menu-view-grid');
    const btnTable = document.getElementById('btn-menu-view-table');
    const gridWrapper = document.getElementById('menu-grid-wrapper');
    const tableWrapper = document.getElementById('menu-table-wrapper');
    const scrollWrapper = document.getElementById('menu-top-scrollbar-wrapper');

    if (mode === 'grid') {
        if (btnGrid) btnGrid.classList.add('active');
        if (btnTable) btnTable.classList.remove('active');
        if (gridWrapper) gridWrapper.style.display = 'grid';
        if (tableWrapper) tableWrapper.style.display = 'none';
        if (scrollWrapper) scrollWrapper.style.display = 'none';
    } else {
        if (btnTable) btnTable.classList.add('active');
        if (btnGrid) btnGrid.classList.remove('active');
        if (tableWrapper) tableWrapper.style.display = 'block';
        if (gridWrapper) gridWrapper.style.display = 'none';
        if (scrollWrapper) scrollWrapper.style.display = 'block';
        setTimeout(() => syncScrollbars('menu-top-scrollbar-wrapper', 'menu-table-wrapper', 'menu-top-scrollbar-fake-content'), 200);
    }
}

function quickFilterMenuItems(status, cat, cardEl) {
    if (cardEl) {
        document.querySelectorAll('#menu-kpi-container .stats-card').forEach(c => c.classList.remove('active-tap'));
        cardEl.classList.add('active-tap');
        setTimeout(() => cardEl.classList.remove('active-tap'), 600);
    }

    const statusSelect = document.getElementById('menuStatusFilter');
    if (statusSelect) {
        statusSelect.value = status;
        statusSelect.dispatchEvent(new Event('change'));

        const wrapper = statusSelect.nextElementSibling;
        if (wrapper && wrapper.classList.contains('custom-select-wrapper')) {
            const selectedOption = statusSelect.options[statusSelect.selectedIndex];
            const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
            const optText = selectedOption ? (selectedOption.getAttribute(`data-${isAr ? 'ar' : 'en'}`) || selectedOption.text) : '';
            const span = wrapper.querySelector('.custom-select-trigger span');
            if (span) span.innerHTML = optText;
            wrapper.querySelectorAll('.custom-select-item').forEach(i => {
                if (i.dataset.value === status) i.classList.add('selected');
                else i.classList.remove('selected');
            });
        }
    }

    renderMenuItems();

    setTimeout(() => {
        const targetEl = document.getElementById('menuSearchInput') ||
                         document.getElementById('menu-grid-wrapper') ||
                         document.getElementById('menu-table-wrapper');

        if (targetEl) {
            targetEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
    }, 100);
}

window.toggleMenuItemAvailability = async (itemId) => {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const item = (window.allMenuItemsData || []).find(i => String(i.id) === String(itemId));
    if (!item) return;

    const newStatus = !(item.is_available !== false);
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    try {
        const res = await window.supabaseWriteRow('menu_items', 'update', { is_available: newStatus }, itemId, tenantId);
        item.is_available = newStatus;
        if (res && res.data && res.data[0]) {
            clearLocalMenuItemOverride(tenantId, itemId);
        } else {
            saveLocalMenuItemOverride(tenantId, item);
        }
        updateMenuKPIStats();
        renderMenuItems();
        showToast(isAr ? (newStatus ? '✨ تم تعيين الصنف كـ متوفر' : '👁️ تم تعيين الصنف كـ غير متوفر') : 'Item availability updated', 'success');
    } catch (e) {
        console.error(e);
        showToast(e.message, 'error');
    }
};

window.duplicateMenuItem = async (itemId) => {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    let item = (window.allMenuItemsData || []).find(i => String(i.id) === String(itemId));

    if (!item) {
        try {
            const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
            const { data: dbItem, error: dbErr } = await supabaseClient.from('menu_items').select('*').eq('id', itemId).eq('tenant_id', tenantId).single();
            if (dbErr || !dbItem) {
                showToast(isAr ? 'لم يتم العثور على الصنف المراد تكراره' : 'Item to duplicate not found', 'error');
                return;
            }
            item = dbItem;
        } catch (err) {
            showToast(isAr ? 'خطأ في جلب بيانات الصنف' : 'Error fetching item data', 'error');
            return;
        }
    }

    try {
        showToast(isAr ? 'جاري نسخ وتكرار الصنف بجميع الخيارات...' : 'Duplicating item & options...', 'info');

        const tenantId = (typeof window.getActiveTenantId === 'function')
            ? window.getActiveTenantId()
            : (item.tenant_id || 'altaqwa_for_tranding_01');

        const rawAr = item.name_ar || '';
        const rawEn = item.name_en || '';
        const cleanAr = rawAr.replace(/\s*\((?:نسخة|Copy)(?:\s*\d+)?\)\s*$/gi, '').trim();
        const cleanEn = rawEn.replace(/\s*\((?:نسخة|Copy)(?:\s*\d+)?\)\s*$/gi, '').trim();

        const allItems = window.allMenuItemsData || [];
        let maxCopyNum = 0;
        let totalCopiesFound = 0;

        const escapeRegExp = (str) => str.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        const regexAr = cleanAr ? new RegExp('^' + escapeRegExp(cleanAr) + '(?:\\s*\\((?:نسخة|Copy)(?:\\s*(\\d+))?\\))?$', 'i') : null;
        const regexEn = cleanEn ? new RegExp('^' + escapeRegExp(cleanEn) + '(?:\\s*\\((?:نسخة|Copy)(?:\\s*(\\d+))?\\))?$', 'i') : null;

        allItems.forEach(i => {
            const iAr = (i.name_ar || '').trim();
            const iEn = (i.name_en || '').trim();

            let matched = false;
            let copyNum = 0;

            if (regexAr && regexAr.test(iAr)) {
                matched = true;
                const m = iAr.match(regexAr);
                if (m) {
                    if (m[1]) copyNum = parseInt(m[1], 10);
                    else if (iAr !== cleanAr) copyNum = 1;
                }
            } else if (regexEn && regexEn.test(iEn)) {
                matched = true;
                const m = iEn.match(regexEn);
                if (m) {
                    if (m[1]) copyNum = parseInt(m[1], 10);
                    else if (iEn !== cleanEn) copyNum = 1;
                }
            }

            if (matched) {
                totalCopiesFound++;
                if (copyNum > maxCopyNum) {
                    maxCopyNum = copyNum;
                }
            }
        });

        const nextNum = Math.max(maxCopyNum + 1, totalCopiesFound > 1 ? totalCopiesFound : 1);
        const nextAr = `${cleanAr || rawAr} (نسخة ${nextNum})`;
        const nextEn = `${cleanEn || rawEn} (Copy ${nextNum})`;

        const finalSlug = await ensureUniqueMenuItemSlug('', null, nextEn, nextAr);

        const newItemData = {
            tenant_id: tenantId,
            name_ar: nextAr,
            name_en: nextEn,
            slug: finalSlug,
            price: item.price || 0,
            sale_price: item.sale_price || null,
            cost_price: item.cost_price || null,
            wholesale_price: item.wholesale_price || null,
            rep_price: item.rep_price || null,
            hide_price_override: false,
            hide_retail_price: item.hide_retail_price === true || item.hide_price_override === true,
            hide_wholesale_price: item.hide_wholesale_price === true || item.hide_price_override === true,
            hide_rep_price: item.hide_rep_price === true || item.hide_price_override === true,
            category_id: item.category_id || null,
            brand_id: item.brand_id || null,
            badge_ar: item.badge_ar || null,
            badge_en: item.badge_en || null,
            image_url: item.image_url || 'https://cdn.sahalacompany.com/placeholder.webp',
            description_ar: item.description_ar || '',
            description_en: item.description_en || '',
            is_special: item.is_special || false,
            is_available: true
        };

        let currentPayload = { ...newItemData };
        let newItem = null;
        let newItemId = null;

        let tryCount = 0;
        while (tryCount < 10) {
            tryCount++;
            const insertRes = await window.supabaseWriteRow('menu_items', 'insert', currentPayload, null, tenantId);
            if (!insertRes.error) {
                if (insertRes.data && insertRes.data[0]) {
                    newItem = insertRes.data[0];
                    newItemId = newItem.id;
                }
                break;
            }

            const errCode = insertRes.error.code || '';
            const errMsg = insertRes.error.message || '';
            const isColumnErr = errCode === '42703' || errCode === 'PGRST204' || errMsg.includes('column') || errMsg.includes('schema cache');

            if (isColumnErr) {
                const colMatch = errMsg.match(/Could not find the ['"]([^'"]+)['"] column|column ['"]([^'"]+)['"]/i);
                const missingCol = colMatch ? (colMatch[1] || colMatch[2]) : null;

                if (missingCol && (missingCol in currentPayload)) {
                    console.warn(`Supabase duplicate menu_items schema note: removing '${missingCol}' and retrying.`);
                    delete currentPayload[missingCol];
                    continue;
                }

                const optionalCols = ['hide_rep_price', 'hide_wholesale_price', 'hide_retail_price', 'hide_price_override', 'rep_price', 'wholesale_price', 'cost_price', 'r2_key', 'image_source', 'image_hash', 'client_domain', 'keywords'];
                let stripped = false;
                for (const col of optionalCols) {
                    if (col in currentPayload) {
                        delete currentPayload[col];
                        stripped = true;
                        break;
                    }
                }
                if (stripped) continue;
            }

            console.warn('Supabase duplicate menu_item note (persisting item locally):', errMsg);
            newItemId = generateFallbackUUID();
            newItem = {
                ...newItemData,
                id: newItemId,
                created_at: new Date().toISOString()
            };
            break;
        }

        if (newItem) {
            saveLocalMenuItemOverride(tenantId, newItem);
        }

        // Fetch original variants from Supabase directly to ensure exact full copy
        const { data: dbVariants } = await supabaseClient.from('item_variants').select('*').eq('item_id', itemId).eq('tenant_id', tenantId);
        const localVars = JSON.parse(localStorage.getItem('local_item_variants_data_' + tenantId) || '[]');
        const matchingLocalVars = localVars.filter(v => String(v.item_id) === String(itemId));
        const matchingMemVars = (window.allItemVariantsData || []).filter(v => String(v.item_id) === String(itemId));

        const sourceVarMap = new Map();
        (dbVariants || []).forEach(v => {
            const k = (v.name_ar || v.name_en || '').trim();
            if (k) sourceVarMap.set(k, { ...v });
        });
        [...matchingLocalVars, ...matchingMemVars].forEach(v => {
            const k = (v.name_ar || v.name_en || '').trim();
            if (k) {
                if (sourceVarMap.has(k)) {
                    const existing = sourceVarMap.get(k);
                    sourceVarMap.set(k, {
                        ...existing,
                        ...v,
                        image_url: v.image_url || existing.image_url || null
                    });
                } else {
                    sourceVarMap.set(k, { ...v });
                }
            }
        });

        const combinedVariants = Array.from(sourceVarMap.values());

        if (combinedVariants && combinedVariants.length > 0) {
            const vToInsert = combinedVariants.map((v, idx) => ({
                tenant_id: tenantId,
                item_id: newItemId,
                name_ar: v.name_ar || '',
                name_en: v.name_en || '',
                unit_ar: v.unit_ar || v.name_ar || '',
                unit_en: v.unit_en || v.name_en || '',
                price: parseFloat(v.price) || 0,
                sale_price: v.sale_price ? parseFloat(v.sale_price) : null,
                wholesale_price: v.wholesale_price ? parseFloat(v.wholesale_price) : null,
                rep_price: v.rep_price ? parseFloat(v.rep_price) : null,
                cost_price: v.cost_price ? parseFloat(v.cost_price) : null,
                conversion_factor: parseFloat(v.conversion_factor) || 1,
                barcode: v.barcode || null,
                sku: v.sku || 'unit',
                image_url: v.image_url || null,
                r2_key: v.r2_key || null,
                image_hash: v.image_hash || null
            })).filter(v => (v.name_ar || v.name_en) && !isNaN(v.price));

            if (vToInsert.length > 0) {
                const { error: varInsertErr } = await supabaseClient.from('item_variants').insert(vToInsert);
                if (varInsertErr) {
                    console.warn('Variants duplicate insert retry with safe payload:', varInsertErr.message || varInsertErr);
                    const safePayload = vToInsert.map(({ sku, image_url, r2_key, image_hash, ...rest }) => rest);
                    await supabaseClient.from('item_variants').insert(safePayload);
                }

                // Save duplicated variants into localStorage & window.allItemVariantsData
                let allLocalVars = JSON.parse(localStorage.getItem('local_item_variants_data_' + tenantId) || '[]');
                vToInsert.forEach((v, idx) => {
                    const copyVar = {
                        ...v,
                        id: 'local_var_' + Date.now() + '_' + idx
                    };
                    allLocalVars.push(copyVar);
                    if (window.allItemVariantsData) {
                        window.allItemVariantsData.push(copyVar);
                    }
                });
                localStorage.setItem('local_item_variants_data_' + tenantId, JSON.stringify(allLocalVars));
            }
        }

        // Duplicate gallery images if present
        try {
            const { data: dbGallery } = await supabaseClient.from('item_gallery').select('*').eq('item_id', itemId).eq('tenant_id', tenantId);
            const localGal = JSON.parse(localStorage.getItem('local_item_gallery_data_' + tenantId) || '[]');
            const matchingLocalGal = localGal.filter(g => String(g.item_id) === String(itemId));

            const sourceGallery = (dbGallery && dbGallery.length > 0) ? dbGallery : matchingLocalGal;
            if (sourceGallery && sourceGallery.length > 0) {
                const gToInsert = sourceGallery.map((g, idx) => ({
                    tenant_id: tenantId,
                    item_id: newItemId,
                    image_url: g.image_url || g.url,
                    r2_key: g.r2_key || null,
                    image_hash: g.image_hash || null,
                    image_source: g.image_source || 'custom',
                    display_order: g.display_order !== undefined ? g.display_order : idx
                }));

                try {
                    let galRes = await supabaseClient.from('item_gallery').insert(gToInsert);
                    if (galRes.error) {
                        const safeG = gToInsert.map(({ tenant_id, item_id, image_url }) => ({ tenant_id, item_id, image_url }));
                        await supabaseClient.from('item_gallery').insert(safeG);
                    }
                } catch (_) {}

                let allLocalGal = JSON.parse(localStorage.getItem('local_item_gallery_data_' + tenantId) || '[]');
                gToInsert.forEach(g => allLocalGal.push(g));
                localStorage.setItem('local_item_gallery_data_' + tenantId, JSON.stringify(allLocalGal));
            }
        } catch (gErr) {
            console.warn('Gallery duplication note:', gErr);
        }

        showToast(isAr ? '✨ تم تكرار الصنف بجميع خياراته طبق الأصل بنجاح!' : '✨ Item & all options duplicated successfully!', 'success');
        if (typeof loadMenuData === 'function') {
            await loadMenuData();
        }
    } catch (e) {
        console.error('Duplicate Item Error:', e);
        showToast(e.message || (isAr ? 'حدث خطأ أثناء تكرار الصنف' : 'Error duplicating item'), 'error');
    }
};

window.restoreMenuItem = async (itemId) => {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    let trashedIds = getTrashedMenuItemIds();
    trashedIds = trashedIds.filter(id => id !== String(itemId));
    setTrashedMenuItemIds(trashedIds);

    const item = (window.allMenuItemsData || []).find(i => String(i.id) === String(itemId));
    if (item) item.is_available = true;

    try {
        await supabaseClient.from('menu_items').update({ is_available: true }).eq('id', itemId).eq('tenant_id', tenantId);
    } catch (e) {
        console.warn('Supabase restore note:', e);
    }

    updateMenuKPIStats();
    renderMenuItems();
    showToast(isAr ? '✨ تم استعادة الصنف من السلة' : 'Item restored from trash', 'success');
};

window.permanentlyDeleteMenuItem = (itemId) => {
    deleteTargetId = itemId;
    deleteTargetType = 'menu_item';
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    openConfirm(isAr ? 'هل أنت متأكد من حذف الصنف نهائياً من قاعدة البيانات؟' : 'Are you sure you want to permanently delete this item?');
};

window.deleteMenuItem = async (itemId) => {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    let trashedIds = getTrashedMenuItemIds();
    if (!trashedIds.includes(String(itemId))) {
        trashedIds.push(String(itemId));
        setTrashedMenuItemIds(trashedIds);
    }

    const item = (window.allMenuItemsData || []).find(i => String(i.id) === String(itemId));
    if (item) item.is_available = false;

    try {
        await supabaseClient.from('menu_items').update({ is_available: false }).eq('id', itemId).eq('tenant_id', tenantId);
    } catch (e) {
        console.warn('Supabase trash note:', e);
    }

    updateMenuKPIStats();
    renderMenuItems();
    showToast(isAr ? '🗑️ تم نقل الصنف إلى سلة المهملات' : 'Item moved to trash', 'warning');
};

function syncScrollbars(topId, bottomId, fakeId) {
    const top = document.getElementById(topId);
    const bottom = document.getElementById(bottomId);
    const fake = document.getElementById(fakeId);
    const table = bottom?.querySelector('table');
    if (!top || !bottom || !fake || !table) return;
    fake.style.width = table.scrollWidth + 'px';
    top.onscroll = () => bottom.scrollLeft = top.scrollLeft;
    bottom.onscroll = () => top.scrollLeft = bottom.scrollLeft;
}

/**
 * Dropdowns & Trees
 */
function buildCategoryTree(categories, parentId = null, level = 0, currentId = null, isForMenu = false) {
    let html = '';
    const isAr = document.documentElement.getAttribute('lang') === 'ar';
    const children = categories.filter(cat => isNullOrEmpty(parentId) ? isNullOrEmpty(cat.parent_id) : cat.parent_id === parentId);
    const editingSubtreeHeight = (!isForMenu && currentId) ? getCategorySubtreeHeight(currentId, categories) : 0;

    children.forEach(cat => {
        if (currentId && cat.id === currentId) return;
        const name = isAr ? (cat.name_ar || cat.name_en) : (cat.name_en || cat.name_ar);
        const safeName = (name || '').replace(/'/g, "\\'");
        const dots = level > 0 ? "• ".repeat(level * 2) : "";

        let clickHandler = isForMenu ? `selectMenuItemCat('${cat.id}', '${safeName}')` : `selectParent('${cat.id}', '${safeName}')`;
        let extraStyle = isForMenu ? `padding-right: ${15 + (level * 25)}px` : `padding-right: ${15 + (level * 25)}px !important; color: ${level > 0 ? 'var(--primary-gold)' : 'var(--text-main)'}; text-align: right;`;

        if (!isForMenu) {
            const resultingLevel = (level + 1) + editingSubtreeHeight;
            if (resultingLevel > MAX_CATEGORY_LEVEL) {
                const warnMsg = isAr ? 'عذراً، لا يمكن اختيار هذا القسم كأب لأنه يتجاوز أقصى عمق مسموح لعمق الأقسام (5 مستويات)' : 'Cannot select this parent: exceeds maximum 5 levels depth';
                const escapedWarnMsg = warnMsg.replace(/'/g, "\\'");
                clickHandler = `showToast('${escapedWarnMsg}', 'warning')`;
                extraStyle += ` opacity: 0.45; cursor: not-allowed; text-decoration: line-through;`;
            }
        }

        html += `<div class="custom-option" onclick="${clickHandler}" style="${extraStyle}">${dots}${name}</div>`;
        html += buildCategoryTree(categories, cat.id, level + 1, currentId, isForMenu);
    });
    return html;
}

