window.renderParentCategoryDropdownItems = function(query = '') {
    const itemsContainer = document.getElementById('parent-category-options-items');
    if (!itemsContainer) return;
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const currentId = document.getElementById('section-id')?.value || null;
    const selectedId = document.getElementById('parent_id')?.value || '';
    const q = (query || '').trim().toLowerCase();
    const categories = window.allCategoriesData || [];

    const noneText = isAr ? 'بدون (تعيين كقسم رئيسي)' : 'None (Set as Primary)';
    let html = `
        <div class="custom-option" onclick="selectParent('', '${noneText}')" style="display:flex; align-items:center; justify-content:space-between; gap:6px; padding:7px 10px; font-weight:700; font-size:0.79rem; white-space:nowrap; border-bottom:1px solid var(--border-subtle); background:${!selectedId ? 'rgba(217, 119, 6, 0.12)' : 'transparent'};">
            <span style="display:inline-flex; align-items:center; gap:6px; font-size:0.79rem; white-space:nowrap;">
                <i class="fas fa-home" style="color:var(--primary-gold); font-size:0.8rem; flex-shrink:0;"></i>
                <span style="font-size:0.79rem; white-space:nowrap; line-height:1.2;">${noneText}</span>
            </span>
            ${!selectedId ? '<i class="fas fa-check" style="color:var(--primary-gold); font-size:0.75rem; flex-shrink:0;"></i>' : ''}
        </div>
    `;

    if (q) {
        const matched = categories.filter(c => {
            if (currentId && String(c.id) === String(currentId)) return false;
            const nAr = (c.name_ar || '').toLowerCase();
            const nEn = (c.name_en || '').toLowerCase();
            return nAr.includes(q) || nEn.includes(q);
        });
        if (matched.length === 0) {
            html += `<div style="padding:14px; text-align:center; color:var(--text-muted); font-size:0.82rem;">${isAr ? 'لا توجد أقسام مطابقة للبحث' : 'No matching categories found'}</div>`;
        } else {
            matched.forEach(cat => {
                const name = isAr ? (cat.name_ar || cat.name_en) : (cat.name_en || cat.name_ar);
                const safeName = (name || '').replace(/'/g, "\\'");
                const isSel = String(selectedId) === String(cat.id);
                html += `
                    <div class="custom-option" onclick="selectParent('${cat.id}', '${safeName}')" style="display:flex; align-items:center; justify-content:space-between; padding:8px 12px; background:${isSel ? 'rgba(217, 119, 6, 0.14)' : 'transparent'};">
                        <span style="display:inline-flex; align-items:center; gap:8px;">
                            <i class="fas fa-folder" style="color:var(--primary-gold); font-size:0.85rem;"></i>
                            <span style="font-weight:700; color:var(--text-main);">${name}</span>
                        </span>
                        ${isSel ? '<i class="fas fa-check" style="color:var(--primary-gold); font-size:0.8rem;"></i>' : ''}
                    </div>
                `;
            });
        }
    } else {
        html += buildCategoryTree(categories, null, 0, currentId, false);
    }
    itemsContainer.innerHTML = html;
};

