window.addSection = (parentId = null) => openSectionModal(null, parentId);
window.openSectionModal = async (data = null, parentId = null) => {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';

    const targetParentId = data ? (data.parent_id || '') : (parentId || '');

    if (targetParentId && !data) {
        const parentLevel = getCategoryLevel(targetParentId, window.allCategoriesData);
        if (parentLevel >= MAX_CATEGORY_LEVEL) {
            showToast(
                isAr
                    ? 'عذراً، لا يمكن إضافة قسم فرعي جديد. لقد وصلت للحد الأقصى المسموح به لعمق الأقسام وهو 5 مستويات.'
                    : 'Sorry, cannot add new subcategory. Maximum allowed category depth of 5 levels reached.',
                'warning'
            );
            return;
        }
    }

    const form = document.getElementById('sectionForm');
    if (form) form.reset();
    removePreview();

    const titleEl = document.getElementById('modalTitle');
    if (titleEl) {
        if (data) {
            titleEl.textContent = isAr ? `تعديل قسم: ${data.name_ar || data.name_en}` : `Edit Category: ${data.name_en || data.name_ar}`;
        } else if (parentId) {
            titleEl.textContent = isAr ? 'إضافة قسم فرعي جديد' : 'Add New Subcategory';
        } else {
            titleEl.textContent = isAr ? 'إضافة قسم جديد' : 'Add New Section';
        }
    }

    document.getElementById('section-id').value = data ? data.id : '';
    document.getElementById('name_ar').value = data ? data.name_ar : '';
    document.getElementById('name_en').value = data ? data.name_en : '';
    document.getElementById('slug').value = data ? data.slug : '';
    document.getElementById('parent_id').value = targetParentId;
    document.getElementById('selected-parent-text').textContent = isAr ? 'بدون (تعيين كقسم رئيسي)' : 'None (Set as Primary)';

    const isHideAllSec = data ? (data.hide_price_override === true) : false;
    const isHideRetailSec = data ? (data.hide_retail_price === true || isHideAllSec) : false;
    const isHideWholesaleSec = data ? (data.hide_wholesale_price === true || isHideAllSec) : false;
    const isHideRepSec = data ? (data.hide_rep_price === true || isHideAllSec) : false;

    if (document.getElementById('section_hide_price_override')) {
        document.getElementById('section_hide_price_override').checked = isHideAllSec || (isHideRetailSec && isHideWholesaleSec && isHideRepSec);
    }
    if (document.getElementById('section_hide_retail_price')) {
        document.getElementById('section_hide_retail_price').checked = isHideRetailSec;
    }
    if (document.getElementById('section_hide_wholesale_price')) {
        document.getElementById('section_hide_wholesale_price').checked = isHideWholesaleSec;
    }
    if (document.getElementById('section_hide_rep_price')) {
        document.getElementById('section_hide_rep_price').checked = isHideRepSec;
    }

    if (targetParentId) {
        const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
        const { data: p } = await supabaseClient.from('categories').select('name_ar, name_en').eq('id', targetParentId).eq('tenant_id', tenantId).single();
        if (p) document.getElementById('selected-parent-text').textContent = isAr ? p.name_ar : p.name_en;
    }

    document.getElementById('is_active').checked = data ? data.is_active !== false : true;
    const isDefaultPlaceholderCat = data?.image_url && /placeholder\.webp$/i.test(String(data.image_url).trim());
    if (data?.image_url && !isDefaultPlaceholderCat) {
        const detectedSource = data.image_source || (window.isSharedBankImageUrl && window.isSharedBankImageUrl(data.image_url, data.id) ? 'bank' : 'custom');
        document.getElementById('image_url').value = data.image_url;
        if (document.getElementById('image_source')) document.getElementById('image_source').value = detectedSource;
        if (document.getElementById('image_hash')) document.getElementById('image_hash').value = data.image_hash || '';
        if (document.getElementById('image_r2_key')) document.getElementById('image_r2_key').value = data.r2_key || '';
        showPreview(data.image_url, detectedSource);
    }
    await refreshParentDropdown();
    if (!data && form) restoreFormDraft(form);
    document.getElementById('sectionModal').classList.add('show');
};
window.closeSectionModal = () => document.getElementById('sectionModal').classList.remove('show');

window.currentVariantImageMap = {};

window.renderVariantImagesSection = function() {
    const section = document.getElementById('variant-images-section');
    const grid = document.getElementById('variant-images-grid');
    if (!section || !grid) return;

    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';

    const sizeRows = Array.from(document.querySelectorAll('#sizes-container .size-row-compact, #sizes-container .variant-row-compact'));
    const unitRows = Array.from(document.querySelectorAll('#units-container .unit-row-compact, #units-container .variant-row-compact'));
    const legacyRows = Array.from(document.querySelectorAll('#variants-container .variant-row-compact, #variants-container .variant-row'));

    const allVariants = [];

    sizeRows.forEach(r => {
        const nameAr = r.querySelector('.variant-name-ar')?.value?.trim() || '';
        const nameEn = r.querySelector('.variant-name-en')?.value?.trim() || '';
        const price = r.querySelector('.variant-price')?.value?.trim() || '';
        if (nameAr || nameEn) {
            allVariants.push({ nameAr, nameEn, price, type: 'size', typeLabel: isAr ? 'مقاس/لون' : 'Size/Color' });
        }
    });

    unitRows.forEach(r => {
        const nameAr = r.querySelector('.variant-name-ar')?.value?.trim() || '';
        const nameEn = r.querySelector('.variant-name-en')?.value?.trim() || '';
        const price = r.querySelector('.variant-price')?.value?.trim() || '';
        if (nameAr || nameEn) {
            allVariants.push({ nameAr, nameEn, price, type: 'unit', typeLabel: isAr ? 'وحدة بيع' : 'Unit' });
        }
    });

    legacyRows.forEach(r => {
        const nameAr = r.querySelector('.variant-name-ar')?.value?.trim() || '';
        const nameEn = r.querySelector('.variant-name-en')?.value?.trim() || '';
        const price = r.querySelector('.variant-price')?.value?.trim() || '';
        if (nameAr || nameEn) {
            allVariants.push({ nameAr, nameEn, price, type: 'unit', typeLabel: isAr ? 'وحدة بيع' : 'Unit' });
        }
    });

    if (allVariants.length === 0) {
        section.style.display = 'none';
        grid.innerHTML = '';
        return;
    }

    section.style.display = 'block';
    let html = '';

    allVariants.forEach((v, idx) => {
        const vKey = (v.nameAr || v.nameEn).trim();
        const existingUrl = window.currentVariantImageMap[vKey] || '';
        const displayTitle = (isAr ? v.nameAr : (v.nameEn || v.nameAr)) || vKey;
        const priceDisplay = v.price ? ` (${v.price} ${isAr ? 'ر.س' : 'SAR'})` : '';

        const safeKeySingle = vKey.replace(/'/g, "\\'");
        const safeKeyDouble = vKey.replace(/"/g, '&quot;');

        html += `
            <div class="variant-img-card" style="padding: 12px; border-radius: 14px; background: rgba(255,255,255,0.03); border: 1px solid var(--border-subtle); display: flex; flex-direction: column; gap: 8px;">
                <div style="display: flex; align-items: center; justify-content: space-between;">
                    <span style="font-weight: 700; font-size: 0.85rem; color: var(--text-main); display: flex; align-items: center; gap: 6px;">
                        <i class="${v.type === 'unit' ? 'fas fa-box-open' : 'fas fa-palette'}" style="color: var(--icon-purple);"></i>
                        <span>${displayTitle}${priceDisplay}</span>
                    </span>
                    <span style="font-size: 0.70rem; padding: 2px 8px; border-radius: 10px; background: rgba(217,119,6,0.12); color: var(--icon-purple); font-weight: 700;">${v.typeLabel}</span>
                </div>
                <div style="position: relative; width: 100%; height: 100px; border-radius: 10px; background: rgba(0,0,0,0.2); border: 1px dashed var(--border-subtle); display: flex; align-items: center; justify-content: center; overflow: hidden; cursor: pointer;" onclick="document.getElementById('file_var_img_${idx}').click()">
                    <input type="file" id="file_var_img_${idx}" accept="image/*" style="display:none;" onchange="handleVariantImageUpload(this, '${safeKeySingle}', ${idx})">
                    <input type="hidden" id="var_img_url_${idx}" class="variant-img-url-input" data-vkey="${safeKeyDouble}" value="${existingUrl}">
                    <div id="var_img_preview_${idx}" style="width:100%; height:100%; display:${existingUrl ? 'flex' : 'none'}; align-items:center; justify-content:center; position:relative;">
                        <img src="${existingUrl}" style="max-height:100%; max-width:100%; object-fit:contain;">
                        <button type="button" onclick="event.stopPropagation(); clearVariantImage('${safeKeySingle}', ${idx})" style="position:absolute; top:4px; left:4px; width:26px; height:26px; border-radius:50%; background:rgba(239,68,68,0.85); color:#fff; border:none; cursor:pointer; display:flex; align-items:center; justify-content:center; font-size:0.75rem;" title="${isAr ? 'حذف صورة الخيار' : 'Remove image'}"><i class="fas fa-times"></i></button>
                    </div>
                    <div id="var_img_placeholder_${idx}" style="display:${existingUrl ? 'none' : 'flex'}; flex-direction:column; align-items:center; gap:4px; color:var(--text-muted); font-size:0.78rem;">
                        <i class="fas fa-cloud-upload-alt" style="font-size:1.3rem; color:var(--icon-purple);"></i>
                        <span>${isAr ? 'انقر لرفع صورة الخيار' : 'Click to upload'}</span>
                    </div>
                </div>
            </div>
        `;
    });

    grid.innerHTML = html;
};

window.handleVariantImageUpload = async function(inputEl, vKey, idx) {
    const file = inputEl.files && inputEl.files[0];
    if (!file) return;

    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const clientDomain = (typeof window.getActiveClientDomain === 'function') ? window.getActiveClientDomain() : tenantId;

    showToast(isAr ? 'جاري رفع صورة الخيار...' : 'Uploading variant image...', 'info');

    try {
        const webpBlob = typeof convertToWebP === 'function' ? await convertToWebP(file, 0.5) : file;
        const randomCode = Math.random().toString(36).substr(2, 6);
        const fileName = `variant-${tenantId}-${Date.now()}-${randomCode}.webp`;

        let publicUrl = '';
        let r2Key = '';

        try {
            const base64Data = typeof blobToBase64 === 'function' ? await blobToBase64(webpBlob) : '';
            if (base64Data) {
                const r2Res = await fetch('/api/r2/upload', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        base64Data,
                        fileName,
                        tenantId,
                        clientDomain,
                        target: 'variant',
                        contentType: 'image/webp'
                    })
                });
                const r2Data = await r2Res.json();
                if (r2Res.ok && r2Data && r2Data.success && r2Data.publicUrl) {
                    publicUrl = r2Data.publicUrl;
                    r2Key = r2Data.r2Key || fileName;
                }
            }
        } catch (e) {
            console.warn('Variant image upload note:', e);
        }

        if (!publicUrl) {
            const { error: upErr } = await supabaseClient.storage.from('images').upload(fileName, webpBlob, { contentType: 'image/webp' });
            if (upErr) throw upErr;
            const { data: { publicUrl: sUrl } } = supabaseClient.storage.from('images').getPublicUrl(fileName);
            publicUrl = sUrl;
            r2Key = fileName;
        }

        window.currentVariantImageMap[vKey] = publicUrl;
        const inputUrl = document.getElementById(`var_img_url_${idx}`);
        if (inputUrl) inputUrl.value = publicUrl;

        const previewBox = document.getElementById(`var_img_preview_${idx}`);
        const placeholderBox = document.getElementById(`var_img_placeholder_${idx}`);
        if (previewBox) {
            previewBox.style.display = 'flex';
            const img = previewBox.querySelector('img');
            if (img) img.src = publicUrl;
        }
        if (placeholderBox) placeholderBox.style.display = 'none';

        showToast(isAr ? '✨ تم رفع صورة الخيار بنجاح' : 'Variant image uploaded successfully', 'success');
    } catch (err) {
        console.error('Error uploading variant image:', err);
        showToast(err.message || 'Upload failed', 'error');
    }
};

window.clearVariantImage = function(vKey, idx) {
    delete window.currentVariantImageMap[vKey];
    const inputUrl = document.getElementById(`var_img_url_${idx}`);
    if (inputUrl) inputUrl.value = '';

    const previewBox = document.getElementById(`var_img_preview_${idx}`);
    const placeholderBox = document.getElementById(`var_img_placeholder_${idx}`);
    if (previewBox) {
        previewBox.style.display = 'none';
        const img = previewBox.querySelector('img');
        if (img) img.src = '';
    }
    if (placeholderBox) placeholderBox.style.display = 'flex';
};

window.switchMenuModalTab = (tabName) => {
    const tabs = ['basic', 'variants', 'media'];
    tabs.forEach(t => {
        const pane = document.getElementById(`menu-tab-pane-${t}`);
        const btn = document.getElementById(`menu-tab-btn-${t}`);
        if (pane) {
            if (t === tabName) {
                pane.classList.add('active');
                pane.style.display = 'block';
            } else {
                pane.classList.remove('active');
                pane.style.display = 'none';
            }
        }
        if (btn) {
            if (t === tabName) {
                btn.classList.add('active');
            } else {
                btn.classList.remove('active');
            }
        }
    });

    const prevBtn = document.getElementById('menu-btn-prev-step');
    const nextBtn = document.getElementById('menu-btn-next-step');
    if (prevBtn && nextBtn) {
        if (tabName === 'basic') {
            prevBtn.style.display = 'none';
            nextBtn.style.display = 'inline-flex';
        } else if (tabName === 'variants') {
            prevBtn.style.display = 'inline-flex';
            nextBtn.style.display = 'inline-flex';
        } else if (tabName === 'media') {
            prevBtn.style.display = 'inline-flex';
            nextBtn.style.display = 'none';
        }
    }
    if (tabName === 'media') {
        if (typeof window.renderVariantImagesSection === 'function') {
            window.renderVariantImagesSection();
        }
    }
    if (typeof window.updateMenuVariantsCountBadge === 'function') {
        window.updateMenuVariantsCountBadge();
    }
};

window.navigateMenuModalStep = (delta) => {
    const tabs = ['basic', 'variants', 'media'];
    let currentIdx = tabs.findIndex(t => {
        const pane = document.getElementById(`menu-tab-pane-${t}`);
        return pane && pane.classList.contains('active');
    });
    if (currentIdx === -1) currentIdx = 0;
    const nextIdx = Math.max(0, Math.min(tabs.length - 1, currentIdx + delta));
    window.switchMenuModalTab(tabs[nextIdx]);
};

window.updateMenuVariantsCountBadge = () => {
    const sizeCount = document.querySelectorAll('#sizes-container .size-row-compact, #sizes-container .variant-row-compact').length;
    const unitCount = document.querySelectorAll('#units-container .unit-row-compact, #units-container .variant-row-compact').length;
    const total = sizeCount + unitCount;
    const badge = document.getElementById('modal-variants-badge');
    if (badge) {
        if (total > 0) {
            badge.textContent = total;
            badge.style.setProperty('display', 'inline-flex', 'important');
        } else {
            badge.textContent = '0';
            badge.style.setProperty('display', 'none', 'important');
        }
    }
};

