window.openMenuModal = async (data = null) => {
    const isAr = document.documentElement.getAttribute('lang') === 'ar';
    const form = document.getElementById('menuForm');
    if (form) form.reset();
    if (typeof removeItemPreview === 'function') removeItemPreview(false);
    itemGalleryUrls = [];
    itemGalleryItems = [];
    if (document.getElementById('item_image_source')) document.getElementById('item_image_source').value = '';
    if (document.getElementById('item_image_hash')) document.getElementById('item_image_hash').value = '';
    if (document.getElementById('item_r2_key')) document.getElementById('item_r2_key').value = '';
    if (document.getElementById('item-gallery-preview')) document.getElementById('item-gallery-preview').innerHTML = '';
    if (document.getElementById('variants-container')) document.getElementById('variants-container').innerHTML = '';
    if (document.getElementById('sizes-container')) document.getElementById('sizes-container').innerHTML = '';
    if (document.getElementById('units-container')) document.getElementById('units-container').innerHTML = '';
    window.updateMenuVariantsCountBadge();

    const titleEl = document.getElementById('menuModalTitle');
    if (titleEl) {
        if (data) {
            titleEl.textContent = isAr ? `تعديل منتج: ${data.name_ar || data.name_en || ''}` : `Edit Product: ${data.name_en || data.name_ar || ''}`;
        } else {
            titleEl.textContent = isAr ? 'إضافة منتج جديد' : 'Add New Product';
        }
    }

    document.getElementById('item-id').value = data ? data.id : '';
    if (document.getElementById('item_keywords')) document.getElementById('item_keywords').value = data ? (data.keywords || '') : '';
    document.getElementById('item_name_ar').value = data ? data.name_ar : '';
    document.getElementById('item_name_en').value = data ? data.name_en : '';
    document.getElementById('item_slug').value = data ? (data.slug || '') : '';
    document.getElementById('item_cost_price').value = (data && data.cost_price !== undefined && data.cost_price !== null) ? toEnglishDigits(data.cost_price) : '';
    document.getElementById('item_price').value = data ? toEnglishDigits(data.price) : '';
    document.getElementById('item_sale_price').value = data ? toEnglishDigits(data.sale_price || '') : '';
    document.getElementById('item_wholesale_price').value = (data && data.wholesale_price !== undefined && data.wholesale_price !== null) ? toEnglishDigits(data.wholesale_price) : '';
    document.getElementById('item_rep_price').value = (data && data.rep_price !== undefined && data.rep_price !== null) ? toEnglishDigits(data.rep_price) : '';

    const preselectedCatId = data ? data.category_id : (window.selectedMenuCategoryId || '');
    const catEffectiveHide = (preselectedCatId && typeof window.getCategoryEffectivePriceHide === 'function')
        ? window.getCategoryEffectivePriceHide(preselectedCatId)
        : { hide_price_override: false, hide_retail_price: false, hide_wholesale_price: false, hide_rep_price: false };

    const isHideAll = (data ? (data.hide_price_override === true) : false) || catEffectiveHide.hide_price_override;
    const isHideRetail = (data ? (data.hide_retail_price === true || isHideAll) : false) || catEffectiveHide.hide_retail_price || isHideAll;
    const isHideWholesale = (data ? (data.hide_wholesale_price === true || isHideAll) : false) || catEffectiveHide.hide_wholesale_price || isHideAll;
    const isHideRep = (data ? (data.hide_rep_price === true || isHideAll) : false) || catEffectiveHide.hide_rep_price || isHideAll;

    if (document.getElementById('item_hide_price_override')) {
        document.getElementById('item_hide_price_override').checked = isHideAll || (isHideRetail && isHideWholesale && isHideRep);
    }
    if (document.getElementById('item_hide_retail_price')) {
        document.getElementById('item_hide_retail_price').checked = isHideRetail;
    }
    if (document.getElementById('item_hide_wholesale_price')) {
        document.getElementById('item_hide_wholesale_price').checked = isHideWholesale;
    }
    if (document.getElementById('item_hide_rep_price')) {
        document.getElementById('item_hide_rep_price').checked = isHideRep;
    }

    // Load default markups from store settings or calculate them
    const defaultRep = window.currentSiteSettingsData?.default_markup_rep !== undefined ? window.currentSiteSettingsData.default_markup_rep : 5;
    const defaultWholesale = window.currentSiteSettingsData?.default_markup_wholesale !== undefined ? window.currentSiteSettingsData.default_markup_wholesale : 10;
    const defaultRetail = window.currentSiteSettingsData?.default_markup_retail !== undefined ? window.currentSiteSettingsData.default_markup_retail : 15;

    if (data && data.cost_price && data.cost_price > 0) {
        if (data.rep_price) {
            document.getElementById('item_markup_rep').value = Math.round(((data.rep_price - data.cost_price) / data.cost_price) * 100 * 10) / 10;
        } else {
            document.getElementById('item_markup_rep').value = defaultRep;
        }
        if (data.wholesale_price) {
            document.getElementById('item_markup_wholesale').value = Math.round(((data.wholesale_price - data.cost_price) / data.cost_price) * 100 * 10) / 10;
        } else {
            document.getElementById('item_markup_wholesale').value = defaultWholesale;
        }
        if (data.price) {
            document.getElementById('item_markup_retail').value = Math.round(((data.price - data.cost_price) / data.cost_price) * 100 * 10) / 10;
        } else {
            document.getElementById('item_markup_retail').value = defaultRetail;
        }
    } else {
        document.getElementById('item_markup_rep').value = defaultRep;
        document.getElementById('item_markup_wholesale').value = defaultWholesale;
        document.getElementById('item_markup_retail').value = defaultRetail;
    }

    document.getElementById('item_category_id').value = preselectedCatId || '';
    document.getElementById('selected-item-cat-text').textContent = isAr ? 'اختر القسم...' : 'Select Category';
    if (preselectedCatId) {
        const categoriesList = window.allCategoriesData || [];
        const foundCat = categoriesList.find(c => String(c.id) === String(preselectedCatId));
        if (foundCat) {
            document.getElementById('selected-item-cat-text').textContent = isAr ? foundCat.name_ar : (foundCat.name_en || foundCat.name_ar);
        } else {
            const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
            const { data: c } = await supabaseClient.from('categories').select('*').eq('id', preselectedCatId).eq('tenant_id', tenantId).maybeSingle();
            if (c) document.getElementById('selected-item-cat-text').textContent = isAr ? c.name_ar : (c.name_en || c.name_ar);
        }
    }

    const preselectedBrandId = data ? (data.brand_id || '') : ((window.selectedMenuBrandId && window.selectedMenuBrandId !== 'none') ? window.selectedMenuBrandId : '');
    if (document.getElementById('item_brand_id')) {
        document.getElementById('item_brand_id').value = preselectedBrandId || '';
    }
    if (document.getElementById('selected-item-brand-text')) {
        document.getElementById('selected-item-brand-text').textContent = isAr ? 'بدون علامة تجارية (اختر العلامة...)' : 'No Brand (Select Brand...)';
        if (preselectedBrandId) {
            const brandsList = window.allBrandsData || [];
            const foundBrand = brandsList.find(b => String(b.id) === String(preselectedBrandId));
            if (foundBrand) {
                document.getElementById('selected-item-brand-text').textContent = isAr ? foundBrand.name_ar : (foundBrand.name_en || foundBrand.name_ar);
            } else {
                const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
                const { data: b } = await supabaseClient.from('brands').select('*').eq('id', preselectedBrandId).eq('tenant_id', tenantId).maybeSingle();
                if (b) document.getElementById('selected-item-brand-text').textContent = isAr ? b.name_ar : (b.name_en || b.name_ar);
            }
        }
    }

    document.getElementById('item_desc_ar').value = data ? data.description_ar : '';
    document.getElementById('item_desc_en').value = data ? data.description_en : '';
    document.getElementById('item_is_available').checked = data ? data.is_available !== false : true;
    document.getElementById('item_is_special').checked = data ? data.is_special === true : false;
    const isDefaultPlaceholderItem = data?.image_url && /placeholder\.webp$/i.test(String(data.image_url).trim());
    if (data?.image_url && !isDefaultPlaceholderItem) {
        document.getElementById('item_image_url').value = data.image_url;
        if (document.getElementById('item_image_source')) document.getElementById('item_image_source').value = data.image_source || 'custom';
        if (document.getElementById('item_image_hash')) document.getElementById('item_image_hash').value = data.image_hash || '';
        if (document.getElementById('item_r2_key')) document.getElementById('item_r2_key').value = data.r2_key || '';
        showItemPreview(data.image_url);
    } else {
        if (typeof removeItemPreview === 'function') removeItemPreview(false);
    }

    window.currentVariantImageMap = {};

    if (data) {
        const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
        const [vars, gal] = await Promise.all([
            supabaseClient.from('item_variants').select('*').eq('item_id', data.id).eq('tenant_id', tenantId).order('created_at', { ascending: true }),
            supabaseClient.from('item_gallery').select('*').eq('item_id', data.id).eq('tenant_id', tenantId).order('created_at', { ascending: true })
        ]);

        if (document.getElementById('sizes-container')) document.getElementById('sizes-container').innerHTML = '';
        if (document.getElementById('units-container')) document.getElementById('units-container').innerHTML = '';

        let cloudVarsList = (vars.data && vars.data.length > 0) ? vars.data : [];
        let localVarsList = [];
        try {
            const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
            const localVars = JSON.parse(localStorage.getItem('local_item_variants_data_' + tenantId) || '[]');
            localVarsList = localVars.filter(v => String(v.item_id) === String(data.id));
        } catch (e) {}

        const varModalMap = new Map();
        cloudVarsList.forEach(v => {
            const k = (v.name_ar || v.name_en || '').trim();
            if (k) varModalMap.set(k, { ...v });
        });
        localVarsList.forEach(v => {
            const k = (v.name_ar || v.name_en || '').trim();
            if (k) {
                if (varModalMap.has(k)) {
                    const existing = varModalMap.get(k);
                    varModalMap.set(k, {
                        ...existing,
                        ...v,
                        image_url: v.image_url || existing.image_url || null
                    });
                } else {
                    varModalMap.set(k, { ...v });
                }
            }
        });
        let itemVariantsList = Array.from(varModalMap.values());

        if (itemVariantsList && itemVariantsList.length > 0) {
            itemVariantsList.forEach(v => {
                const vKey = (v.name_ar || v.name_en || '').trim();
                if (vKey && v.image_url) {
                    window.currentVariantImageMap[vKey] = v.image_url;
                }
                if (v.sku === 'size') {
                    addSizeRow(v);
                } else if (v.sku === 'unit' || (v.conversion_factor && v.conversion_factor > 1) || v.wholesale_price || v.barcode || v.cost_price || v.rep_price || v.variant_type === 'unit') {
                    addUnitRow(v);
                } else {
                    addSizeRow(v);
                }
            });
        }

        if (typeof window.renderVariantImagesSection === 'function') {
            window.renderVariantImagesSection();
        }

        let itemGalleryList = (gal.data && gal.data.length > 0) ? gal.data : [];
        try {
            const localGal = JSON.parse(localStorage.getItem('local_item_gallery_data_' + tenantId) || '[]');
            const matchingLocalGal = localGal.filter(g => String(g.item_id) === String(data.id));
            if (matchingLocalGal.length > 0) {
                itemGalleryList = matchingLocalGal;
            }
        } catch (e) {}

        if (itemGalleryList && itemGalleryList.length > 0) {
            itemGalleryItems = itemGalleryList.map((g, idx) => ({
                id: g.id,
                image_url: g.image_url,
                r2_key: g.r2_key || '',
                image_hash: g.image_hash || '',
                image_source: g.image_source || 'custom',
                client_domain: g.client_domain || '',
                display_order: g.display_order ?? idx
            }));
            itemGalleryUrls = itemGalleryItems.map(g => g.image_url);
            renderItemGallery();
        } else {
            itemGalleryItems = [];
            itemGalleryUrls = [];
            renderItemGallery();
        }
    } else {
        itemGalleryItems = [];
        itemGalleryUrls = [];
        renderItemGallery();
        renderVariantsEmptyState();
    }
    updateBasePricesVisibility();
    window.switchMenuModalTab('basic');
    window.updateMenuVariantsCountBadge();
    if (!data && form) restoreFormDraft(form);
    document.getElementById('menuModal').classList.add('show');
    // Refresh dropdowns non-blockingly so user selection isn't overwritten
    Promise.all([refreshMenuCatDropdown(), refreshMenuBrandDropdown()]).catch(() => {});
};

window.closeMenuModal = () => {
    const modal = document.getElementById('menuModal');
    if (modal) modal.classList.remove('show');
    if (document.getElementById('sizes-container')) document.getElementById('sizes-container').innerHTML = '';
    if (document.getElementById('units-container')) document.getElementById('units-container').innerHTML = '';
    window.updateMenuVariantsCountBadge();
};

