window.addSizeRow = (data = null, prepend = (data === null)) => {
    const container = document.getElementById('sizes-container');
    if (!container) return;
    if (container.querySelector('.variants-empty-hint')) container.innerHTML = '';
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const row = document.createElement('div');
    row.className = 'size-row-compact variant-row-compact';
    row.style.cssText = 'background: rgba(255,255,255,0.03); border: 1px solid var(--border-subtle); border-radius: 12px; padding: 12px; margin-bottom: 10px; animation: fadeInModalTab 0.22s ease-in-out;';

    row.innerHTML = `
        <div class="variant-row-header" style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;">
            <span class="variant-card-title" style="font-weight: 800; color: #38bdf8; white-space: nowrap;"><i class="fas fa-ruler-combined"></i> ${isAr ? 'المقاس / الحجم' : 'Size / Variant'}</span>
            <div class="variant-card-actions" style="display: flex; gap: 6px; align-items: center; flex-shrink: 0;">
                <button type="button" onclick="autoTranslateVariantRow(this)" class="btn-variant-ai" title="${isAr ? 'ترجمة' : 'Translate'}"><i class="fas fa-magic"></i> <span>${isAr ? 'ترجمة' : 'Translate'}</span></button>
                <button type="button" onclick="removeVariantRow(this)" class="btn-variant-delete" title="${isAr ? 'حذف' : 'Delete'}"><i class="fas fa-trash-alt"></i></button>
            </div>
        </div>
        <div class="size-inputs-grid variant-inputs-grid" style="display: grid; grid-template-columns: 1.2fr 1.2fr 1fr; gap: 8px; align-items: end;">
            <div>
                <label style="font-size: 0.68rem; font-weight: 700; display: block; margin-bottom: 3px; white-space: nowrap;">${isAr ? 'اسم المقاس/الحجم (عربي)' : 'Name (AR)'}</label>
                <input type="text" class="glass-input variant-name-ar" dir="rtl" style="text-align: right; height: 34px; font-size: 0.82rem;" placeholder="${isAr ? 'مثال: صغير / وسط / كبير' : 'e.g. Small / Medium / Large'}" value="${data ? (data.name_ar || '') : ''}">
            </div>
            <div>
                <label style="font-size: 0.68rem; font-weight: 700; display: block; margin-bottom: 3px; white-space: nowrap;">${isAr ? 'اسم المقاس/الحجم (إنجليزي)' : 'Name (EN)'}</label>
                <input type="text" class="glass-input variant-name-en" dir="ltr" style="text-align: left; height: 34px; font-size: 0.82rem;" placeholder="e.g. Small / Medium / Large" value="${data ? (data.name_en || '') : ''}">
            </div>
            <div>
                <label style="font-size: 0.68rem; font-weight: 700; display: block; margin-bottom: 3px; color: var(--primary-gold); white-space: nowrap;">${isAr ? 'السعر' : 'Price'}</label>
                <input type="number" class="glass-input variant-price" step="any" lang="en" dir="ltr" style="height: 34px; font-size: 0.82rem; font-weight: 800; font-family: 'Inter', -apple-system, sans-serif !important; direction: ltr !important; text-align: right !important;" placeholder="0.00" value="${data ? toEnglishDigits(data.price || '') : ''}" oninput="this.value = toEnglishDigits(this.value)">
            </div>
            <input type="hidden" class="variant-type" value="size">
        </div>
    `;

    if (prepend) {
        container.prepend(row);
    } else {
        container.appendChild(row);
    }
    updateBasePricesVisibility();
    if (typeof window.updateMenuVariantsCountBadge === 'function') {
        window.updateMenuVariantsCountBadge();
    }
    if (!data) {
        setTimeout(() => {
            const firstInp = row.querySelector('.variant-name-ar');
            if (firstInp) firstInp.focus();
            row.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
        }, 50);
    }
};

