function renderItemGallery() {
    const preview = document.getElementById('item-gallery-preview');
    if (!preview) return;
    preview.innerHTML = itemGalleryItems.map((item, index) => {
        const url = typeof item === 'string' ? item : item.image_url;
        return `
        <div class="gallery-thumb" style="position:relative; width:80px; height:80px; border-radius:10px; overflow:hidden; border:1px solid var(--glass-border); box-shadow: 0 2px 8px rgba(0,0,0,0.15);">
            <img src="${url}" alt="Gallery" style="width:100%; height:100%; object-fit:cover;">
            <button type="button" onclick="removeGalleryImage(${index})" style="position:absolute; top:2px; right:2px; background:var(--accent-red); color:white; border:none; border-radius:4px; width:22px; height:22px; display:flex; align-items:center; justify-content:center; cursor:pointer; font-size:14px; line-height:1;" title="حذف">&times;</button>
        </div>
    `;
    }).join('');
}

window.removeGalleryImage = async (index) => {
    if (index < 0 || index >= itemGalleryItems.length) return;
    const item = itemGalleryItems[index];
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';

    if (item && typeof item === 'object' && item.image_url) {
        if (typeof window.deleteSectionImageSmart === 'function') {
            await window.deleteSectionImageSmart(item.image_url, item.image_source || 'custom', item.r2_key || '', null);
        }
    } else if (typeof item === 'string') {
        if (typeof window.deleteSectionImageSmart === 'function') {
            await window.deleteSectionImageSmart(item, 'custom', '', null);
        }
    }

    itemGalleryItems.splice(index, 1);
    itemGalleryUrls.splice(index, 1);
    renderItemGallery();
    showToast(isAr ? '🗑️ تم حذف الصورة من المعرض' : '🗑️ Gallery image removed', 'info');
};

/**
 * Form Submission
 */
async function handleSectionFormSubmit(e) {
    if (e) e.preventDefault();
    const btn = (e && e.submitter) || (e && e.target && e.target.querySelector('button[type="submit"]')) || document.querySelector('#sectionModal button[type="submit"]');
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const id = document.getElementById('section-id')?.value || '';

    const nameAr = document.getElementById('name_ar')?.value.trim() || '';
    const nameEn = document.getElementById('name_en')?.value.trim() || '';

    if (!nameAr && !nameEn) {
        showToast(isAr ? 'يرجى كتابة اسم القسم باللغة العربية أو الإنجليزية' : 'Please enter category name in Arabic or English', 'warning');
        return;
    }

    const targetParentId = document.getElementById('parent_id')?.value || null;

    if (isCategoryNameSameAsParent(nameAr, nameEn, targetParentId, window.allCategoriesData)) {
        showToast(
            isAr
                ? 'عذراً، لا يمكن إنشاء قسم فرعي بنفس اسم القسم الأب المباشر!'
                : 'Sorry, a subcategory cannot have the exact same name as its parent category!',
            'warning'
        );
        return;
    }

    if (!id && isCategoryNameDuplicateUnderParent(nameAr, nameEn, targetParentId, id, window.allCategoriesData)) {
        showToast(
            isAr
                ? 'عذراً، يوجد قسم آخر بنفس هذا الاسم مسبقاً داخل هذا القسم المباشر!'
                : 'Sorry, a category with this name already exists under the same parent!',
            'warning'
        );
        return;
    }

    const parentLevel = targetParentId ? (getCategoryLevel(targetParentId, window.allCategoriesData) + 1) : 0;
    const subtreeHeight = id ? getCategorySubtreeHeight(id, window.allCategoriesData) : 0;

    if (parentLevel + subtreeHeight > MAX_CATEGORY_LEVEL) {
        showToast(
            isAr
                ? 'عذراً، لا يمكن حفظ القسم. تسلسل الأقسام سيتجاوز الحد الأقصى المسموح به لعمق الأقسام وهو 5 مستويات.'
                : 'Sorry, cannot save category. Category hierarchy exceeds maximum allowed 5 levels depth.',
            'warning'
        );
        return;
    }

    if (btn) btn.disabled = true;

    try {
        const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
        const clientDomain = (typeof window.getActiveClientDomain === 'function') ? window.getActiveClientDomain() : tenantId;
        const rawSlugInput = document.getElementById('slug')?.value.trim() || '';
        const finalSlug = await ensureUniqueCategorySlug(rawSlugInput, id, nameEn, nameAr);

        const currentImgUrl = document.getElementById('image_url')?.value || '';
        const currentImgSource = document.getElementById('image_source')?.value || (currentImgUrl ? (window.isSharedBankImageUrl && window.isSharedBankImageUrl(currentImgUrl, id) ? 'bank' : 'custom') : '');
        const currentImgHash = document.getElementById('image_hash')?.value || '';
        const currentR2Key = document.getElementById('image_r2_key')?.value || '';
        const finalCatImgUrl = currentImgUrl || 'https://cdn.sahalacompany.com/placeholder.webp';
        const finalCatImgSource = currentImgUrl ? currentImgSource : 'bank';

        // If editing an existing category and the image was changed or cleared, clean up old custom R2 image if it was not from the bank
        if (id) {
            const oldCat = (window.allCategoriesData || []).find(c => String(c.id) === String(id));
            if (oldCat && oldCat.image_url && oldCat.image_url !== finalCatImgUrl) {
                if (typeof window.deleteSectionImageSmart === 'function') {
                    await window.deleteSectionImageSmart(oldCat.image_url, oldCat.image_source, oldCat.r2_key, id);
                }
            }
        }

        const secHideRetail = document.getElementById('section_hide_retail_price')?.checked === true;
        const secHideWholesale = document.getElementById('section_hide_wholesale_price')?.checked === true;
        const secHideRep = document.getElementById('section_hide_rep_price')?.checked === true;
        const secHideAll = (document.getElementById('section_hide_price_override')?.checked === true) || (secHideRetail && secHideWholesale && secHideRep);
        const finalSecHideRetail = secHideRetail || secHideAll;
        const finalSecHideWholesale = secHideWholesale || secHideAll;
        const finalSecHideRep = secHideRep || secHideAll;

        const baseFormData = {
            tenant_id: tenantId,
            name_ar: nameAr,
            name_en: nameEn,
            slug: finalSlug,
            parent_id: targetParentId,
            image_url: finalCatImgUrl,
            hide_price_override: false,
            hide_retail_price: finalSecHideRetail,
            hide_wholesale_price: finalSecHideWholesale,
            hide_rep_price: finalSecHideRep,
            is_active: document.getElementById('is_active')?.checked !== false
        };

        const extendedFormData = {
            ...baseFormData,
            client_domain: clientDomain,
            image_source: finalCatImgSource,
            image_hash: currentImgHash,
            r2_key: currentR2Key
        };

        let currentPayload = { ...extendedFormData };
        let syncedCategory = null;

        let tryCount = 0;
        const maxTries = 10;

        while (tryCount < maxTries) {
            tryCount++;
            let res = id
                ? await window.supabaseWriteRow('categories', 'update', currentPayload, id, tenantId)
                : await window.supabaseWriteRow('categories', 'insert', currentPayload, null, tenantId);

            if (!res.error && res.data && res.data[0]) {
                syncedCategory = res.data[0];
                break;
            }

            if (!res.error) {
                break;
            }

            const errCode = res.error.code || '';
            const errMsg = res.error.message || '';
            const isColumnErr = errCode === '42703' || errCode === 'PGRST204' || errMsg.includes('column') || errMsg.includes('schema cache');

            if (isColumnErr) {
                const colMatch = errMsg.match(/Could not find the ['"]([^'"]+)['"] column|column ['"]([^'"]+)['"]/i);
                const missingCol = colMatch ? (colMatch[1] || colMatch[2]) : null;

                if (missingCol && (missingCol in currentPayload)) {
                    console.warn(`Supabase categories schema note: removing '${missingCol}' and retrying.`);
                    delete currentPayload[missingCol];
                    continue;
                }

                const optionalCols = ['hide_rep_price', 'hide_wholesale_price', 'hide_retail_price', 'hide_price_override', 'r2_key', 'image_source', 'image_hash', 'client_domain'];
                let stripped = false;
                for (const col of optionalCols) {
                    if (col in currentPayload) {
                        delete currentPayload[col];
                        stripped = true;
                        break;
                    }
                }
                if (stripped) continue;
            }

            console.warn('Supabase categories sync note (persisting category locally):', errMsg);
            break;
        }

        const catId = (syncedCategory && syncedCategory.id) || id || generateFallbackUUID();
        const existingCat = id ? ((window.allCategoriesData || []).find(c => String(c.id) === String(id)) || {}) : {};
        const localSavedCat = {
            ...existingCat,
            ...(syncedCategory || {}),
            ...extendedFormData,
            id: catId,
            created_at: (syncedCategory && syncedCategory.created_at) || existingCat.created_at || new Date().toISOString()
        };

        if (syncedCategory && syncedCategory.id) {
            clearLocalCategoryOverride(tenantId, syncedCategory.id);
        } else {
            saveLocalCategoryOverride(tenantId, localSavedCat);
        }

        // Immediately update in-memory categories array
        if (Array.isArray(window.allCategoriesData)) {
            const idx = window.allCategoriesData.findIndex(c => String(c.id) === String(catId));
            if (idx !== -1) {
                window.allCategoriesData[idx] = localSavedCat;
            } else {
                window.allCategoriesData.unshift(localSavedCat);
            }
        }

        // Propagate price-hiding settings to all products (and subcategories) in this category strictly for the active SaaS tenant
        const priceHidePropagationPayload = {
            hide_price_override: false,
            hide_retail_price: finalSecHideRetail,
            hide_wholesale_price: finalSecHideWholesale,
            hide_rep_price: finalSecHideRep
        };

        const tenantCategories = (window.allCategoriesData || []).filter(c => !c.tenant_id || String(c.tenant_id) === String(tenantId));
        const targetCatIdsSet = (typeof window.getAllChildCategoryIds === 'function')
            ? window.getAllChildCategoryIds(catId, tenantCategories)
            : new Set([String(catId)]);
        targetCatIdsSet.add(String(catId));
        const targetCatIds = Array.from(targetCatIdsSet);

        // Update any child subcategories in memory & DB for this tenant
        const childCatIds = targetCatIds.filter(cid => String(cid) !== String(catId));
        if (childCatIds.length > 0) {
            childCatIds.forEach(cid => {
                const childCat = tenantCategories.find(c => String(c.id) === String(cid));
                if (childCat) {
                    Object.assign(childCat, priceHidePropagationPayload);
                }
            });
            try {
                await window.supabaseWriteBatch('categories', priceHidePropagationPayload, 'id', childCatIds, tenantId);
            } catch (_) {}
        }

        // Update all products (menu_items) in this category tree in Supabase strictly isolated by tenant_id
        if (targetCatIds.length > 0) {
            let itemSyncPayload = { ...priceHidePropagationPayload };
            for (let attempt = 0; attempt < 5; attempt++) {
                const itemRes = await window.supabaseWriteBatch('menu_items', itemSyncPayload, 'category_id', targetCatIds, tenantId);
                if (!itemRes.error) break;
                const iErrMsg = itemRes.error.message || '';
                const iColMatch = iErrMsg.match(/Could not find the ['"]([^'"]+)['"] column|column ['"]([^'"]+)['"]/i);
                const iMissingCol = iColMatch ? (iColMatch[1] || iColMatch[2]) : null;
                if (iMissingCol && (iMissingCol in itemSyncPayload)) {
                    delete itemSyncPayload[iMissingCol];
                    if (Object.keys(itemSyncPayload).length === 0) break;
                    continue;
                }
                break;
            }
        }

        // Update all matching products in memory
        if (Array.isArray(window.allMenuItemsData) && window.allMenuItemsData.length > 0) {
            window.allMenuItemsData = window.allMenuItemsData.map(item => {
                const belongsToTenant = !item.tenant_id || String(item.tenant_id) === String(tenantId);
                if (belongsToTenant && item.category_id && targetCatIdsSet.has(String(item.category_id))) {
                    return { ...item, ...priceHidePropagationPayload };
                }
                return item;
            });
        }

        if (typeof renderMenuItems === 'function' && Array.isArray(window.allMenuItemsData) && window.allMenuItemsData.length > 0) {
            renderMenuItems();
        }

        showToast(isAr ? "✨ تم حفظ القسم وتطبيق التغييرات في قاعدة البيانات بنجاح" : "✨ Category saved to database successfully", "success");
        closeSectionModal();
        loadSectionsData(true);
    } catch (err) {
        console.warn('Save category note:', err);
        if (err.message && err.message.includes('categories_slug_key')) {
            showToast(isAr ? 'عذراً، الرابط المختصر مستخدم مسبقاً، يرجى تغييره قليلاً' : 'Category slug already exists, please modify it slightly', 'warning');
        } else {
            showToast(err.message || 'Error occurred while saving', 'error');
        }
    } finally {
        if (btn) btn.disabled = false;
    }
}

async function handleMenuFormSubmit(e) {
    if (e) e.preventDefault();
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const id = document.getElementById('item-id')?.value || '';
    const nameAr = document.getElementById('item_name_ar')?.value.trim() || '';
    const nameEn = document.getElementById('item_name_en')?.value.trim() || '';
    const categoryId = document.getElementById('item_category_id')?.value || null;

    const submitBtns = Array.from(document.querySelectorAll('button[form="menuForm"][type="submit"], #menuHeaderSaveBtn, #menuModal button[type="submit"]'));
    const originalHTMLs = new Map();

    submitBtns.forEach(b => {
        if (b) {
            originalHTMLs.set(b, b.innerHTML);
            b.disabled = true;
            b.innerHTML = `<i class="fas fa-spinner fa-spin"></i> ${isAr ? 'جاري الحفظ...' : 'Saving...'}`;
        }
    });

    const resetSubmitBtns = () => {
        submitBtns.forEach(b => {
            if (b) {
                b.disabled = false;
                if (originalHTMLs.has(b)) b.innerHTML = originalHTMLs.get(b);
            }
        });
    };

    if (!nameAr && !nameEn) {
        showToast(isAr ? "يرجى إدخال اسم الصنف باللغة العربية أو الإنجليزية" : "Item name required", "warning");
        resetSubmitBtns();
        if (typeof window.switchMenuModalTab === 'function') window.switchMenuModalTab('basic');
        const inp = document.getElementById('item_name_ar') || document.getElementById('item_name_en');
        if (inp) inp.focus();
        return;
    }

    if (!categoryId) {
        showToast(isAr ? "يرجى اختيار القسم الخاص بالصنف" : "Category required", "warning");
        resetSubmitBtns();
        if (typeof window.switchMenuModalTab === 'function') window.switchMenuModalTab('basic');
        return;
    }

    try {
        // Only check duplicate name when adding a brand new item (!id), so editing existing products (e.g. assigning a brand) is never blocked!
        if (!id && isMenuItemNameDuplicateUnderCategory(nameAr, nameEn, categoryId, id, window.allMenuItemsData)) {
            showToast(
                isAr
                    ? 'عذراً، يوجد صنف آخر بنفس هذا الاسم مسبقاً داخل هذا القسم المباشر!'
                    : 'Sorry, an item with this name already exists under the same category!',
                'warning'
            );
            resetSubmitBtns();
            return;
        }

        const rawSlugInput = document.getElementById('item_slug')?.value.trim() || '';
        const finalSlug = await ensureUniqueMenuItemSlug(rawSlugInput, id, nameEn, nameAr);

        const clientDomain = (typeof window.getActiveClientDomain === 'function') ? window.getActiveClientDomain() : tenantId;
        const currentImgUrl = document.getElementById('item_image_url')?.value || '';
        const currentImgSource = document.getElementById('item_image_source')?.value || (currentImgUrl ? 'custom' : '');
        const currentImgHash = document.getElementById('item_image_hash')?.value || '';
        const currentR2Key = document.getElementById('item_r2_key')?.value || '';
        const finalItemImgUrl = currentImgUrl || 'https://cdn.sahalacompany.com/placeholder.webp';
        const finalItemImgSource = currentImgUrl ? currentImgSource : 'bank';

        // If editing an existing item and the image was changed or cleared, clean up old custom R2 image
        if (id) {
            const oldItem = (window.allMenuItemsData || []).find(i => String(i.id) === String(id));
            if (oldItem && oldItem.image_url && oldItem.image_url !== finalItemImgUrl) {
                if (typeof window.deleteSectionImageSmart === 'function') {
                    await window.deleteSectionImageSmart(oldItem.image_url, oldItem.image_source || 'custom', oldItem.r2_key || '', id);
                }
            }
        }

        const rawBrandInputVal = document.getElementById('item_brand_id')?.value?.trim() || '';
        const brandIdVal = rawBrandInputVal ? rawBrandInputVal : null;
        const brandObj = brandIdVal ? (window.allBrandsData || []).find(b => String(b.id) === String(brandIdVal)) : null;
        const badgeArVal = brandObj ? (brandObj.name_ar || null) : null;
        const badgeEnVal = brandObj ? (brandObj.name_en || brandObj.name_ar || null) : null;

        const baseFormData = {
            tenant_id: tenantId,
            name_ar: nameAr,
            name_en: nameEn,
            slug: finalSlug,
            price: parseFloat(document.getElementById('item_price')?.value) || 0,
            sale_price: parseFloat(document.getElementById('item_sale_price')?.value) || null,
            cost_price: parseFloat(document.getElementById('item_cost_price')?.value) || null,
            wholesale_price: parseFloat(document.getElementById('item_wholesale_price')?.value) || null,
            rep_price: parseFloat(document.getElementById('item_rep_price')?.value) || null,
            hide_price_override: false,
            hide_retail_price: (document.getElementById('item_hide_retail_price')?.checked === true) || (document.getElementById('item_hide_price_override')?.checked === true),
            hide_wholesale_price: (document.getElementById('item_hide_wholesale_price')?.checked === true) || (document.getElementById('item_hide_price_override')?.checked === true),
            hide_rep_price: (document.getElementById('item_hide_rep_price')?.checked === true) || (document.getElementById('item_hide_price_override')?.checked === true),
            category_id: categoryId,
            brand_id: brandIdVal,
            badge_ar: badgeArVal,
            badge_en: badgeEnVal,
            keywords: document.getElementById('item_keywords')?.value.trim() || '',
            description_ar: document.getElementById('item_desc_ar')?.value.trim() || '',
            description_en: document.getElementById('item_desc_en')?.value.trim() || '',
            image_url: finalItemImgUrl,
            is_available: document.getElementById('item_is_available')?.checked !== false,
            is_special: document.getElementById('item_is_special')?.checked === true
        };

        const extendedFormData = {
            ...baseFormData,
            client_domain: clientDomain,
            image_source: finalItemImgSource,
            image_hash: currentImgHash,
            r2_key: currentR2Key
        };

        let itemId = id || generateFallbackUUID();
        let syncedItem = null;
        let currentPayload = { ...extendedFormData };

        let tryCount = 0;
        const maxTries = 10;

        while (tryCount < maxTries) {
            tryCount++;
            let res = id
                ? await window.supabaseWriteRow('menu_items', 'update', currentPayload, id, tenantId)
                : await window.supabaseWriteRow('menu_items', 'insert', currentPayload, null, tenantId);

            if (!res.error && res.data && res.data[0]) {
                syncedItem = res.data[0];
                if (!id && syncedItem.id) itemId = syncedItem.id;
                break;
            }

            if (!res.error) {
                break;
            }

            const errCode = res.error.code || '';
            const errMsg = res.error.message || '';
            const isColumnErr = errCode === '42703' || errCode === 'PGRST204' || errMsg.includes('column') || errMsg.includes('schema cache');

            if (isColumnErr) {
                const colMatch = errMsg.match(/Could not find the ['"]([^'"]+)['"] column|column ['"]([^'"]+)['"]/i);
                const missingCol = colMatch ? (colMatch[1] || colMatch[2]) : null;

                if (missingCol && (missingCol in currentPayload)) {
                    console.warn(`Supabase menu_items schema note: column '${missingCol}' does not exist in database. Stripping and retrying.`);
                    delete currentPayload[missingCol];
                    continue;
                }

                // Never strip brand_id unless explicitly named as missing column above
                const optionalCols = ['hide_rep_price', 'hide_wholesale_price', 'hide_retail_price', 'hide_price_override', 'rep_price', 'wholesale_price', 'cost_price', 'r2_key', 'image_source', 'image_hash', 'client_domain', 'keywords'];
                let stripped = false;
                for (const col of optionalCols) {
                    if (col in currentPayload) {
                        delete currentPayload[col];
                        stripped = true;
                        break;
                    }
                }
                if (stripped) continue;
            }

            console.warn('Supabase menu_items sync note (persisting item locally):', errMsg);
            break;
        }

        // Explicitly guarantee brand_id, badge_ar, and badge_en are persisted in Supabase if editing an item
        if (id) {
            try {
                const brandPatchRes = await window.supabaseWriteRow('menu_items', 'update', {
                    brand_id: brandIdVal,
                    badge_ar: badgeArVal,
                    badge_en: badgeEnVal
                }, id, tenantId);
                if (brandPatchRes && brandPatchRes.data && brandPatchRes.data[0]) {
                    syncedItem = { ...syncedItem, ...brandPatchRes.data[0] };
                }
            } catch (_) {}
        }

        const existingItem = id ? ((window.allMenuItemsData || []).find(i => String(i.id) === String(id)) || {}) : {};
        const localSavedItem = {
            ...existingItem,
            ...(syncedItem || {}),
            ...extendedFormData,
            brand_id: brandIdVal,
            badge_ar: badgeArVal,
            badge_en: badgeEnVal,
            id: itemId,
            created_at: (syncedItem && syncedItem.created_at) || existingItem.created_at || new Date().toISOString()
        };

        if (syncedItem && syncedItem.id) {
            clearLocalMenuItemOverride(tenantId, syncedItem.id);
        } else {
            saveLocalMenuItemOverride(tenantId, localSavedItem);
        }

        // Update in-memory menu items array immediately
        if (Array.isArray(window.allMenuItemsData)) {
            const idx = window.allMenuItemsData.findIndex(i => String(i.id) === String(itemId));
            if (idx !== -1) {
                window.allMenuItemsData[idx] = localSavedItem;
            } else {
                window.allMenuItemsData.unshift(localSavedItem);
            }
        }

        // Variations & Sizes & Units
        try {
            await window.supabaseDirectRestCall('item_variants', 'DELETE', `item_id=eq.${encodeURIComponent(itemId)}&tenant_id=eq.${encodeURIComponent(tenantId)}`, null);
        } catch (_) {}

        const sizeRows = Array.from(document.querySelectorAll('#sizes-container .size-row-compact, #sizes-container .variant-row-compact'));
        const unitRows = Array.from(document.querySelectorAll('#units-container .unit-row-compact, #units-container .variant-row-compact'));
        const legacyRows = Array.from(document.querySelectorAll('#variants-container .variant-row-compact, #variants-container .variant-row'));

        const vToInsert = [];

        // 1. Process Sizes (الأحجام والمقاسات)
        sizeRows.forEach(r => {
            const nameAr = r.querySelector('.variant-name-ar')?.value?.trim() || '';
            const nameEn = r.querySelector('.variant-name-en')?.value?.trim() || '';
            if (!nameAr && !nameEn) return;

            const pVal = parseFloat(r.querySelector('.variant-price')?.value);
            const price = !isNaN(pVal) ? pVal : (baseFormData.price || 0);

            const vKey = (nameAr || nameEn).trim();
            const varImgUrl = (window.currentVariantImageMap && window.currentVariantImageMap[vKey])
                ? window.currentVariantImageMap[vKey]
                : (document.querySelector(`.variant-img-url-input[data-vkey="${vKey.replace(/"/g, '&quot;')}"]`)?.value || null);

            vToInsert.push({
                tenant_id: tenantId,
                item_id: itemId,
                name_ar: nameAr,
                name_en: nameEn || nameAr,
                unit_ar: nameAr,
                unit_en: nameEn || nameAr,
                price: price,
                sale_price: null,
                wholesale_price: null,
                rep_price: null,
                cost_price: null,
                conversion_factor: 1,
                barcode: null,
                sku: 'size',
                image_url: varImgUrl || null
            });
        });

        // 2. Process Selling Units (وحدات البيع والتعبئة)
        unitRows.forEach(r => {
            const nameAr = r.querySelector('.variant-name-ar')?.value?.trim() || '';
            const nameEn = r.querySelector('.variant-name-en')?.value?.trim() || '';
            if (!nameAr && !nameEn) return;

            const pVal = parseFloat(r.querySelector('.variant-price')?.value);
            const price = !isNaN(pVal) ? pVal : (baseFormData.price || 0);

            const vKey = (nameAr || nameEn).trim();
            const varImgUrl = (window.currentVariantImageMap && window.currentVariantImageMap[vKey])
                ? window.currentVariantImageMap[vKey]
                : (document.querySelector(`.variant-img-url-input[data-vkey="${vKey.replace(/"/g, '&quot;')}"]`)?.value || null);

            vToInsert.push({
                tenant_id: tenantId,
                item_id: itemId,
                name_ar: nameAr,
                name_en: nameEn || nameAr,
                unit_ar: nameAr,
                unit_en: nameEn || nameAr,
                price: price,
                sale_price: null,
                wholesale_price: parseFloat(r.querySelector('.variant-wholesale-price')?.value) || null,
                rep_price: parseFloat(r.querySelector('.variant-rep-price')?.value) || null,
                cost_price: parseFloat(r.querySelector('.variant-cost-price')?.value) || null,
                conversion_factor: parseFloat(r.querySelector('.variant-conversion-factor')?.value) || 1,
                barcode: r.querySelector('.variant-barcode')?.value?.trim() || null,
                sku: 'unit',
                image_url: varImgUrl || null
            });
        });

        // 3. Process Legacy Rows (if any)
        legacyRows.forEach(r => {
            const nameAr = r.querySelector('.variant-name-ar')?.value?.trim() || '';
            const nameEn = r.querySelector('.variant-name-en')?.value?.trim() || '';
            if (!nameAr && !nameEn) return;

            const pVal = parseFloat(r.querySelector('.variant-price')?.value);
            const price = !isNaN(pVal) ? pVal : (baseFormData.price || 0);
            const isSize = r.querySelector('.variant-type')?.value === 'size';

            const vKey = (nameAr || nameEn).trim();
            const varImgUrl = (window.currentVariantImageMap && window.currentVariantImageMap[vKey])
                ? window.currentVariantImageMap[vKey]
                : (document.querySelector(`.variant-img-url-input[data-vkey="${vKey.replace(/"/g, '&quot;')}"]`)?.value || null);

            vToInsert.push({
                tenant_id: tenantId,
                item_id: itemId,
                name_ar: nameAr,
                name_en: nameEn || nameAr,
                unit_ar: r.querySelector('.variant-unit-ar')?.value?.trim() || nameAr,
                unit_en: r.querySelector('.variant-unit-en')?.value?.trim() || nameEn || nameAr,
                price: price,
                sale_price: parseFloat(r.querySelector('.variant-sale-price')?.value) || null,
                wholesale_price: parseFloat(r.querySelector('.variant-wholesale-price')?.value) || null,
                rep_price: parseFloat(r.querySelector('.variant-rep-price')?.value) || null,
                cost_price: parseFloat(r.querySelector('.variant-cost-price')?.value) || null,
                conversion_factor: parseFloat(r.querySelector('.variant-conversion-factor')?.value) || 1,
                barcode: r.querySelector('.variant-barcode')?.value?.trim() || null,
                sku: isSize ? 'size' : 'unit',
                image_url: varImgUrl || null
            });
        });

        // Deduplicate vToInsert before saving to prevent duplicate rows
        const uniqueVToInsert = [];
        const seenVKeys = new Set();
        vToInsert.forEach(v => {
            const nameAr = (v.name_ar || '').trim().toLowerCase();
            const nameEn = (v.name_en || '').trim().toLowerCase();
            const price = String(v.price || '');
            const key = `${nameAr}_${nameEn}_${price}`;
            if (key && !seenVKeys.has(key)) {
                seenVKeys.add(key);
                uniqueVToInsert.push(v);
            }
        });
        const finalVToInsert = uniqueVToInsert;

        if (finalVToInsert.length > 0) {
            try {
                let insertRes = await window.supabaseDirectRestCall('item_variants', 'POST', 'select=*', finalVToInsert);
                if (insertRes.error) {
                    const safePayload = finalVToInsert.map(({ sku, image_url, r2_key, image_hash, ...rest }) => rest);
                    await window.supabaseDirectRestCall('item_variants', 'POST', 'select=*', safePayload);
                }
            } catch (vErr) {
                console.warn('Variants cloud insert exception note:', vErr);
            }

            try {
                let localVars = JSON.parse(localStorage.getItem('local_item_variants_data_' + tenantId) || '[]');
                localVars = localVars.filter(v => String(v.item_id) !== String(itemId));
                finalVToInsert.forEach((v, idx) => {
                    localVars.push({
                        ...v,
                        id: v.id || ('local_var_' + Date.now() + '_' + idx)
                    });
                });
                localStorage.setItem('local_item_variants_data_' + tenantId, JSON.stringify(localVars));

                if (window.allItemVariantsData) {
                    window.allItemVariantsData = window.allItemVariantsData.filter(v => String(v.item_id) !== String(itemId));
                    finalVToInsert.forEach((v, idx) => {
                        window.allItemVariantsData.push({
                            ...v,
                            id: v.id || ('local_var_' + Date.now() + '_' + idx)
                        });
                    });
                }
            } catch (e) {
                console.warn('Local variants storage note:', e);
            }

            if ((!baseFormData.price || baseFormData.price === 0) && vToInsert[0].price) {
                await window.supabaseWriteRow('menu_items', 'update', { price: vToInsert[0].price }, itemId, tenantId);
            }
        } else {
            try {
                let localVars = JSON.parse(localStorage.getItem('local_item_variants_data_' + tenantId) || '[]');
                localVars = localVars.filter(v => String(v.item_id) !== String(itemId));
                localStorage.setItem('local_item_variants_data_' + tenantId, JSON.stringify(localVars));
                if (window.allItemVariantsData) {
                    window.allItemVariantsData = window.allItemVariantsData.filter(v => String(v.item_id) !== String(itemId));
                }
            } catch (e) {}
        }

        // Gallery
        try {
            await window.supabaseDirectRestCall('item_gallery', 'DELETE', `item_id=eq.${encodeURIComponent(itemId)}&tenant_id=eq.${encodeURIComponent(tenantId)}`, null);
        } catch (_) {}

        if (itemGalleryItems.length > 0) {
            const gExtendedToInsert = itemGalleryItems.map((g, idx) => ({
                tenant_id: tenantId,
                item_id: itemId,
                image_url: typeof g === 'string' ? g : (g.image_url || g.url),
                r2_key: (typeof g === 'object' && g.r2_key) ? g.r2_key : null,
                image_hash: (typeof g === 'object' && g.image_hash) ? g.image_hash : null,
                image_source: (typeof g === 'object' && g.image_source) ? g.image_source : 'custom',
                client_domain: (typeof g === 'object' && g.client_domain) ? g.client_domain : clientDomain,
                display_order: idx
            }));

            const gBaseToInsert = gExtendedToInsert.map(g => ({
                tenant_id: tenantId,
                item_id: g.item_id,
                image_url: g.image_url
            }));

            try {
                let galRes = await window.supabaseDirectRestCall('item_gallery', 'POST', 'select=*', gExtendedToInsert);
                if (galRes.error) {
                    await window.supabaseDirectRestCall('item_gallery', 'POST', 'select=*', gBaseToInsert);
                }
            } catch (gErr) {
                console.warn('Gallery cloud save note:', gErr);
            }

            try {
                let localGal = JSON.parse(localStorage.getItem('local_item_gallery_data_' + tenantId) || '[]');
                localGal = localGal.filter(g => String(g.item_id) !== String(itemId));
                gExtendedToInsert.forEach((g, idx) => {
                    localGal.push({
                        ...g,
                        id: g.id || ('local_gal_' + Date.now() + '_' + idx)
                    });
                });
                localStorage.setItem('local_item_gallery_data_' + tenantId, JSON.stringify(localGal));
            } catch (_) {}
        } else {
            try {
                let localGal = JSON.parse(localStorage.getItem('local_item_gallery_data_' + tenantId) || '[]');
                localGal = localGal.filter(g => String(g.item_id) !== String(itemId));
                localStorage.setItem('local_item_gallery_data_' + tenantId, JSON.stringify(localGal));
            } catch (_) {}
        }

        showToast(isAr ? "✨ تم حفظ الصنف في قاعدة البيانات بنجاح" : "✨ Item saved to database successfully", "success");
        closeMenuModal();
        loadMenuData(true);
        if (typeof filterBrandsTable === 'function' && Array.isArray(window.allBrandsData) && window.allBrandsData.length > 0) {
            filterBrandsTable();
        }
    } catch (err) {
        console.error(err);
        if (err.message && err.message.includes('menu_items_slug_key')) {
            showToast(isAr ? 'عذراً، الرابط المختصر مستخدم مسبقاً، يرجى تغييره قليلاً' : 'Item slug already exists, please modify it slightly', 'warning');
        } else {
            showToast(err.code === '42501' ? (isAr ? "خطأ RLS: تأكد من تفعيل الصلاحيات" : "RLS Error") : (err.message || 'Error occurred while saving'), "error");
        }
    } finally {
        resetSubmitBtns();
    }
}

/**
 * Image Upload
 */
/**
 * Smart Image Bank + 50% Compression + Cloudflare R2 Upload & Delete System
 */
window.getActiveClientDomain = function() {
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const settings = window.currentSiteSettingsData || {};
    const fromSettings = settings.custom_domain || settings.subdomain || settings.client_domain || settings.domain || '';
    if (fromSettings && fromSettings.trim()) {
        return fromSettings.trim().replace(/^https?:\/\//i, '').replace(/\/.*$/, '');
    }
    const storedUrl = localStorage.getItem('client_website_url_' + tenantId) || localStorage.getItem('client_website_url') || '';
    if (storedUrl && storedUrl.startsWith('http')) {
        try {
            return new URL(storedUrl).hostname;
        } catch (_) {}
    }
    if (window.location.hostname && !window.location.hostname.includes('run.app') && window.location.hostname !== 'localhost') {
        return window.location.hostname;
    }
    return `${tenantId}.sahala.store`;
};

window.isSharedBankImageUrl = function(url, currentCategoryId = null) {
    if (!url) return false;
    const clean = String(url).trim();
    // Root numeric WebP images on CDN (e.g., https://cdn.altaqwafortrading.com/1210.webp), placeholder.webp, sahala.webp, sahaladark.webp, or /bank/ or /shared/ are Image Bank assets
    if (/\/(\d+\.webp|placeholder\.webp|sahala\.webp|sahaladark\.webp|sahalalight\.webp|bank\/|shared\/)/i.test(clean)) return true;
    // Also check if another category in memory or another tenant shares this exact URL
    const allCats = window.allCategoriesData || [];
    const sharedCount = allCats.filter(c => c.image_url === clean && (!currentCategoryId || String(c.id) !== String(currentCategoryId))).length;
    if (sharedCount > 0) return true;
    return false;
};

async function computeBlobSHA256(blob) {
    try {
        const arrayBuffer = await blob.arrayBuffer();
        const hashBuffer = await crypto.subtle.digest('SHA-256', arrayBuffer);
        const hashArray = Array.from(new Uint8Array(hashBuffer));
        return hashArray.map(b => b.toString(16).padStart(2, '0')).join('');
    } catch (e) {
        return '';
    }
}

function blobToBase64(blob) {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve(reader.result);
        reader.onerror = reject;
        reader.readAsDataURL(blob);
    });
}

async function searchImageBankForCategory({ fileHash, originalFileHash, fileName, nameAr, nameEn }) {
    const cleanAr = (nameAr || '').trim().toLowerCase();
    const cleanEn = (nameEn || '').trim().toLowerCase();
    const baseFileName = String(fileName || '').replace(/\.[^.]+$/, '').trim().toLowerCase();

    // 1. Check dedicated `image_bank` table in Supabase (if created)
    try {
        const { data: bankRows, error } = await supabaseClient.from('image_bank').select('*').limit(500);
        if (!error && Array.isArray(bankRows) && bankRows.length > 0) {
            const match = bankRows.find(row => {
                if (fileHash && row.image_hash && (row.image_hash === fileHash || row.image_hash === originalFileHash)) return true;
                const rAr = (row.name_ar || '').trim().toLowerCase();
                const rEn = (row.name_en || '').trim().toLowerCase();
                const rKey = (row.r2_key || '').replace(/\.[^.]+$/, '').trim().toLowerCase();
                if (cleanAr && rAr && cleanAr === rAr) return true;
                if (cleanEn && rEn && cleanEn === rEn) return true;
                if (baseFileName && rKey && baseFileName === rKey) return true;
                return false;
            });
            if (match && match.image_url) {
                return { found: true, imageUrl: match.image_url, imageHash: match.image_hash || fileHash, source: 'bank' };
            }
        }
    } catch (_) {}

    // 2. Check existing categories in Supabase for this tenant by hash, filename, or exact category name
    try {
        const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
        const { data: existingCats } = await supabaseClient
            .from('categories')
            .select('id, name_ar, name_en, image_url')
            .eq('tenant_id', tenantId)
            .not('image_url', 'is', null)
            .neq('image_url', '')
            .limit(500);

        if (Array.isArray(existingCats) && existingCats.length > 0) {
            const matchedCat = existingCats.find(cat => {
                if (!cat.image_url) return false;
                const cAr = (cat.name_ar || '').trim().toLowerCase();
                const cEn = (cat.name_en || '').trim().toLowerCase();
                const urlFile = cat.image_url.split('/').pop().replace(/\.[^.]+$/, '').toLowerCase();
                if (baseFileName && urlFile && baseFileName === urlFile) return true;
                if (cleanAr && cAr && cleanAr === cAr) return true;
                if (cleanEn && cEn && cleanEn === cEn) return true;
                return false;
            });
            if (matchedCat && matchedCat.image_url) {
                return { found: true, imageUrl: matchedCat.image_url, imageHash: fileHash, source: 'bank' };
            }
        }
    } catch (_) {}

    // 3. Check local hash registry in localStorage for previously indexed bank images
    try {
        const localBankMap = JSON.parse(localStorage.getItem('sahala_image_bank_hashes') || '{}');
        if (fileHash && localBankMap[fileHash]) {
            return { found: true, imageUrl: localBankMap[fileHash], imageHash: fileHash, source: 'bank' };
        }
        if (originalFileHash && localBankMap[originalFileHash]) {
            return { found: true, imageUrl: localBankMap[originalFileHash], imageHash: originalFileHash, source: 'bank' };
        }
    } catch (_) {}

    return { found: false };
}

window.deleteSectionImageSmart = async function(imageUrl, imageSource = '', r2Key = '', categoryId = null) {
    if (!imageUrl) return { deletedFromR2: false, source: 'none' };

    const isBank = (imageSource === 'bank') || window.isSharedBankImageUrl(imageUrl, categoryId);
    if (isBank) {
        // Image belongs to the Image Bank -> ONLY remove link from client's column in Supabase, NEVER delete from R2!
        return { deletedFromR2: false, source: 'bank' };
    }

    // Custom image uploaded from client's device -> Delete from Cloudflare R2 (and fallback storage)
    try {
        const deleteTenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : '';
        await fetch('/api/r2/delete', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                imageUrl,
                r2Key,
                tenantId: deleteTenantId,
                imageSource: 'custom'
            })
        });
    } catch (e) {
        console.warn('R2 delete request note:', e);
    }

    // Also clean up from Supabase storage bucket if it was stored there as fallback
    try {
        if (imageUrl.includes('/storage/v1/object/public/images/')) {
            const storageFile = imageUrl.split('/storage/v1/object/public/images/')[1];
            if (storageFile) {
                await supabaseClient.storage.from('images').remove([decodeURIComponent(storageFile)]);
            }
        }
    } catch (_) {}

    return { deletedFromR2: true, source: 'custom' };
};

async function handleUniversalUpload(e, prefix) {
    const file = e.target.files[0];
    if (!file) return;
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const clientDomain = window.getActiveClientDomain();

    showToast(
        isAr ? "جاري رفع الصورة..." : "Uploading image...",
        "info"
    );

    try {
        // 1. Compute original file hash & compress image by 50% (0.5 quality WebP)
        const originalFileHash = await computeBlobSHA256(file);
        const webpBlob = await convertToWebP(file, 0.5);
        const compressedHash = await computeBlobSHA256(webpBlob);

        // 2. If uploading a category image, silently search the Image Bank FIRST in the background
        if (prefix === 'category') {
            const nameAr = document.getElementById('name_ar')?.value || '';
            const nameEn = document.getElementById('name_en')?.value || '';
            const bankResult = await searchImageBankForCategory({
                fileHash: compressedHash,
                originalFileHash,
                fileName: file.name,
                nameAr,
                nameEn
            });

            if (bankResult && bankResult.found && bankResult.imageUrl) {
                // Silently discard client's uploaded file (reset file input without uploading to R2) and link Image Bank URL
                e.target.value = '';
                document.getElementById('image_url').value = bankResult.imageUrl;
                if (document.getElementById('image_source')) document.getElementById('image_source').value = 'bank';
                if (document.getElementById('image_hash')) document.getElementById('image_hash').value = bankResult.imageHash || compressedHash;
                if (document.getElementById('image_r2_key')) document.getElementById('image_r2_key').value = '';
                showPreview(bankResult.imageUrl, 'bank');
                showToast(
                    isAr ? "تم رفع الصورة بنجاح" : "Image uploaded successfully",
                    "success"
                );
                return;
            }
        }

        // 3. Not in Image Bank -> Upload 50% compressed WebP to Cloudflare R2 with Client Domain
        const fileName = `${prefix}-${tenantId}-${Date.now()}.webp`;
        let finalPublicUrl = '';
        let finalR2Key = '';

        try {
            const base64Data = await blobToBase64(webpBlob);
            const r2Res = await fetch('/api/r2/upload', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    base64Data,
                    fileName,
                    tenantId,
                    clientDomain,
                    contentType: 'image/webp'
                })
            });
            const r2Data = await r2Res.json();
            if (r2Res.ok && r2Data && r2Data.success && r2Data.publicUrl) {
                finalPublicUrl = r2Data.publicUrl;
                finalR2Key = r2Data.r2Key || '';
            } else {
                finalR2Key = (r2Data && r2Data.r2Key) || `tenants/${clientDomain}/categories/${fileName}`;
            }
        } catch (r2Err) {
            console.warn('Cloudflare R2 endpoint note, using fallback storage:', r2Err);
        }

        // Fallback to Supabase Storage if R2 env keys are not yet configured in .env
        if (!finalPublicUrl) {
            const { error } = await supabaseClient.storage.from('images').upload(fileName, webpBlob, { contentType: 'image/webp' });
            if (error) throw error;
            const { data: { publicUrl } } = supabaseClient.storage.from('images').getPublicUrl(fileName);
            finalPublicUrl = publicUrl;
            if (!finalR2Key) finalR2Key = fileName;
        }

        if (prefix === 'category') {
            document.getElementById('image_url').value = finalPublicUrl;
            if (document.getElementById('image_source')) document.getElementById('image_source').value = 'custom';
            if (document.getElementById('image_hash')) document.getElementById('image_hash').value = compressedHash;
            if (document.getElementById('image_r2_key')) document.getElementById('image_r2_key').value = finalR2Key;
            showPreview(finalPublicUrl, 'custom');
        } else {
            document.getElementById('item_image_url').value = finalPublicUrl;
            if (document.getElementById('item_image_source')) document.getElementById('item_image_source').value = 'custom';
            if (document.getElementById('item_image_hash')) document.getElementById('item_image_hash').value = compressedHash;
            if (document.getElementById('item_r2_key')) document.getElementById('item_r2_key').value = finalR2Key;
            showItemPreview(finalPublicUrl);
        }

        showToast(
            isAr ? "تم رفع الصورة بنجاح" : "Image uploaded successfully",
            "success"
        );
    } catch (err) {
        showToast(err.message, "error");
    }
}

async function handleItemGalleryUpload(e) {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const clientDomain = (typeof window.getActiveClientDomain === 'function') ? window.getActiveClientDomain() : tenantId;

    showToast(isAr ? "جاري رفع الصور..." : "Uploading images...", "info");

    try {
        for (let file of files) {
            // 1. Compress 50% WebP
            const webpBlob = await convertToWebP(file, 0.5);
            // 2. Compute SHA-256 hash
            const compressedHash = await computeBlobSHA256(webpBlob);
            // 3. Unique filename
            const randomCode = Math.random().toString(36).substr(2, 6);
            const fileName = `gallery-${tenantId}-${Date.now()}-${randomCode}.webp`;

            let publicUrl = '';
            let r2Key = '';

            try {
                const base64Data = await blobToBase64(webpBlob);
                const r2Res = await fetch('/api/r2/upload', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        base64Data,
                        fileName,
                        tenantId,
                        clientDomain,
                        contentType: 'image/webp'
                    })
                });
                const r2Data = await r2Res.json();
                if (r2Res.ok && r2Data && r2Data.success && r2Data.publicUrl) {
                    publicUrl = r2Data.publicUrl;
                    r2Key = r2Data.r2Key || fileName;
                }
            } catch (r2Err) {
                console.warn('Storage gallery upload note:', r2Err);
            }

            // Fallback to Supabase Storage if R2 is not reachable
            if (!publicUrl) {
                const { error: upErr } = await supabaseClient.storage.from('images').upload(fileName, webpBlob, { contentType: 'image/webp' });
                if (upErr) throw upErr;
                const { data: { publicUrl: sUrl } } = supabaseClient.storage.from('images').getPublicUrl(fileName);
                publicUrl = sUrl;
                r2Key = fileName;
            }

            const galleryItem = {
                image_url: publicUrl,
                r2_key: r2Key,
                image_hash: compressedHash,
                image_source: 'custom',
                client_domain: clientDomain,
                tenant_id: tenantId
            };

            itemGalleryItems.push(galleryItem);
            itemGalleryUrls.push(publicUrl);
        }

        renderItemGallery();
        e.target.value = '';
        showToast(isAr ? "✨ تم رفع الصور بنجاح" : "✨ Images uploaded successfully", "success");
    } catch (err) {
        console.error('Gallery upload error:', err);
        showToast(isAr ? "فشل رفع الصور: " + (err.message || '') : "Upload failed", "error");
    }
}

function convertToWebP(file, quality = 0.5) {
    return new Promise((resolve) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            const img = new Image();
            img.onload = () => {
                const canvas = document.createElement('canvas');
                // Scale dimensions proportionally if ultra-large while compressing quality by 50% (0.5)
                const maxDim = 1200;
                let w = img.width;
                let h = img.height;
                if (w > maxDim || h > maxDim) {
                    if (w > h) {
                        h = Math.round((h * maxDim) / w);
                        w = maxDim;
                    } else {
                        w = Math.round((w * maxDim) / h);
                        h = maxDim;
                    }
                }
                canvas.width = w;
                canvas.height = h;
                canvas.getContext('2d').drawImage(img, 0, 0, w, h);
                canvas.toBlob(resolve, 'image/webp', quality);
            };
            img.src = e.target.result;
        };
        reader.readAsDataURL(file);
    });
}

