/**
 * Events & Clock
 */
function setupEventListeners() {
    document.getElementById('sectionForm')?.addEventListener('submit', handleSectionFormSubmit);
    document.getElementById('menuForm')?.addEventListener('submit', handleMenuFormSubmit);
    document.getElementById('image_file')?.addEventListener('change', (e) => handleUniversalUpload(e, 'category'));
    document.getElementById('item_image_file')?.addEventListener('change', (e) => handleUniversalUpload(e, 'item'));
    document.getElementById('item_gallery_file')?.addEventListener('change', handleItemGalleryUpload);

    document.getElementById('name_en')?.addEventListener('input', (e) => {
        document.getElementById('slug').value = e.target.value.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-');
    });
    document.getElementById('name_ar')?.addEventListener('input', (e) => {
        if (!document.getElementById('name_en').value.trim()) {
            const val = e.target.value.trim();
            const dictMatch = lookupArabicInDictionary(val);
            if (dictMatch) {
                document.getElementById('slug').value = dictMatch.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-');
            } else {
                document.getElementById('slug').value = transliterateArabic(val);
            }
        }
    });

    document.getElementById('item_name_en')?.addEventListener('input', (e) => {
        const slugEl = document.getElementById('item_slug');
        if (slugEl) {
            slugEl.value = e.target.value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
        }
    });
    document.getElementById('item_name_ar')?.addEventListener('input', (e) => {
        const slugEl = document.getElementById('item_slug');
        const enVal = document.getElementById('item_name_en')?.value.trim();
        if (slugEl && !enVal) {
            const val = e.target.value.trim();
            const dictMatch = lookupArabicInDictionary(val);
            if (dictMatch) {
                slugEl.value = dictMatch.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
            } else if (val) {
                slugEl.value = transliterateArabic(val);
            }
        }
    });

    document.getElementById('confirmDeleteBtn').onclick = async () => {
        if (!deleteTargetId) return;
        const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
        const btn = document.getElementById('confirmDeleteBtn');
        btn.disabled = true;
        try {
            const table = deleteTargetType === 'category' ? 'categories' : 'menu_items';
            if (deleteTargetType === 'category') {
                const targetCat = (window.allCategoriesData || []).find(c => String(c.id) === String(deleteTargetId));
                if (targetCat && targetCat.image_url && typeof window.deleteSectionImageSmart === 'function') {
                    await window.deleteSectionImageSmart(targetCat.image_url, targetCat.image_source, targetCat.r2_key, targetCat.id);
                }
            } else {
                const targetItem = (window.allMenuItemsData || []).find(i => String(i.id) === String(deleteTargetId));
                if (targetItem && targetItem.image_url && typeof window.deleteSectionImageSmart === 'function') {
                    await window.deleteSectionImageSmart(targetItem.image_url, targetItem.image_source || 'custom', targetItem.r2_key || '', targetItem.id);
                }
                try {
                    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
                    const { data: itemGals } = await supabaseClient.from('item_gallery').select('*').eq('item_id', deleteTargetId).eq('tenant_id', tenantId);
                    if (Array.isArray(itemGals) && itemGals.length > 0) {
                        for (const galImg of itemGals) {
                            if (galImg.image_url && typeof window.deleteSectionImageSmart === 'function') {
                                await window.deleteSectionImageSmart(galImg.image_url, galImg.image_source || 'custom', galImg.r2_key || '', deleteTargetId);
                            }
                        }
                    }
                } catch (_) {}
            }
            try {
                const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
                await supabaseClient.from(table).delete().eq('id', deleteTargetId).eq('tenant_id', tenantId);
            } catch (delErr) {
                console.warn('Supabase delete table note (RLS):', delErr);
            }

            const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
            if (deleteTargetType === 'category') {
                removeLocalCategoryOverride(tenantId, deleteTargetId);
                let trashedIds = getTrashedCategoryIds();
                trashedIds = trashedIds.filter(id => id !== String(deleteTargetId));
                setTrashedCategoryIds(trashedIds);
                loadSectionsData();
            } else {
                removeLocalMenuItemOverride(tenantId, deleteTargetId);
                let trashedIds = getTrashedMenuItemIds();
                trashedIds = trashedIds.filter(id => id !== String(deleteTargetId));
                setTrashedMenuItemIds(trashedIds);
                window.allMenuItemsData = (window.allMenuItemsData || []).filter(i => String(i.id) !== String(deleteTargetId));
                updateMenuKPIStats();
                renderMenuItems();
            }
            showToast(isAr ? '✨ تم الحذف النهائي بنجاح' : 'Permanently deleted', "success");
        } catch (e) { showToast(e.message, "error"); } finally { btn.disabled = false; closeConfirmModal(); }
    };

    document.getElementById('sidebarOpen').onclick = () => { document.getElementById('sidebar').classList.add('open'); document.getElementById('sidebarOverlay').classList.add('show'); };
    document.getElementById('sidebarClose').onclick = () => { document.getElementById('sidebar').classList.remove('open'); document.getElementById('sidebarOverlay').classList.remove('show'); };
    document.getElementById('sidebarOverlay').onclick = () => { document.getElementById('sidebar').classList.remove('open'); document.getElementById('sidebarOverlay').classList.remove('show'); };

    window.addEventListener('click', (e) => {
        if (!e.target.closest('.custom-select-wrapper')) {
            document.getElementById('custom-options-list')?.classList.remove('show');
            document.getElementById('menu-cat-options-list')?.classList.remove('show');
            document.getElementById('menu-brand-options-list')?.classList.remove('show');
        }
    });
}

window.toggleLanguage = function() {
    const current = localStorage.getItem('adminLang') || 'ar';
    const next = current === 'ar' ? 'en' : 'ar';
    applyLanguage(next);

    // Refresh current active section data so dynamic tables & cards render in selected language
    const currentSection = window.location.hash.replace('#', '') || 'dashboard';
    switchToSection(currentSection);
};

function applyLanguage(lang) {
    document.documentElement.setAttribute('lang', lang);
    document.documentElement.setAttribute('dir', lang === 'ar' ? 'rtl' : 'ltr');
    document.body.setAttribute('dir', lang === 'ar' ? 'rtl' : 'ltr');
    localStorage.setItem('adminLang', lang);


    // Update language toggle button text and title
    const langBtn = document.getElementById('adminLangBtn');
    if (langBtn) {
        const textSpan = langBtn.querySelector('#adminLangText') || langBtn.querySelector('span');
        if (textSpan) textSpan.textContent = lang === 'ar' ? 'EN' : 'عربي';
        const titleAr = langBtn.getAttribute('data-ar-title') || 'Switch to English';
        const titleEn = langBtn.getAttribute('data-en-title') || 'التبديل إلى العربية';
        langBtn.setAttribute('title', lang === 'ar' ? titleAr : titleEn);
    }

    // Update all text nodes with data-ar and data-en
    document.querySelectorAll('[data-ar]').forEach(el => {
        const val = lang === 'ar' ? el.getAttribute('data-ar') : el.getAttribute('data-en');
        if (!val) return;
        if (el.tagName === 'INPUT' || el.tagName === 'TEXTAREA') {
            if (el.hasAttribute('data-ar-placeholder')) {
                el.placeholder = lang === 'ar' ? el.getAttribute('data-ar-placeholder') : el.getAttribute('data-en-placeholder');
            } else if (!el.value) {
                el.placeholder = val;
            }
        } else if (val.includes('<') || val.includes('>')) {
            el.innerHTML = val;
        } else {
            el.textContent = val;
        }
    });

    // Update placeholders
    document.querySelectorAll('input[data-ar-placeholder], textarea[data-ar-placeholder]').forEach(el => {
        const ph = lang === 'ar' ? el.getAttribute('data-ar-placeholder') : el.getAttribute('data-en-placeholder');
        if (ph) el.placeholder = ph;
    });

    // Update titles
    document.querySelectorAll('[data-ar-title]').forEach(el => {
        const t = lang === 'ar' ? el.getAttribute('data-ar-title') : el.getAttribute('data-en-title');
        if (t) el.setAttribute('title', t);
    });

    // Update aria-labels
    document.querySelectorAll('[data-ar-aria-label]').forEach(el => {
        const a = lang === 'ar' ? el.getAttribute('data-ar-aria-label') : el.getAttribute('data-en-aria-label');
        if (a) el.setAttribute('aria-label', a);
    });

    // Update active section title
    const currentSection = window.location.hash.replace('#', '') || 'dashboard';
    const activeNavItem = document.querySelector(`.nav-item[data-section="${currentSection}"]`);
    const secTitleEl = document.getElementById('section-title');
    if (activeNavItem && secTitleEl) {
        const span = activeNavItem.querySelector('span');
        if (span) {
            const ar = span.getAttribute('data-ar') || span.textContent;
            const en = span.getAttribute('data-en') || span.textContent;
            secTitleEl.setAttribute('data-ar', ar);
            secTitleEl.setAttribute('data-en', en);
            secTitleEl.textContent = lang === 'ar' ? ar : en;
        }
    }

    // Update live status badge
    updateOnlineStatus();

    // Update custom dropdowns
    updateCustomDropdownsLang(lang);

    // Refresh active product and order views to update currency symbols dynamically
    if (typeof renderMenuItems === 'function' && document.getElementById('menu-grid-wrapper')) {
        try { renderMenuItems(); } catch (_) {}
    }
    if (typeof filterOrdersTable === 'function' && document.getElementById('orders-section')) {
        try { filterOrdersTable(false); } catch (_) {}
    }
    if (typeof window.closeHeaderDropdowns === 'function') {
        try { window.closeHeaderDropdowns(); } catch (_) {}
    }
}
window.applyLanguage = applyLanguage;

function formatOptionStars(text) {
    if (!text) return '';
    return String(text).replace(/([★☆]+)/g, '<span class="custom-select-option-star" style="color:#f59e0b !important; font-size:1.05rem !important; letter-spacing:1px !important; margin-inline-start:4px !important; display:inline-block !important;">$1</span>');
}
window.formatOptionStars = formatOptionStars;

function initCustomDropdowns() {
    [
        'sectionsStatusFilter', 'sectionsTypeFilter', 'sectionsSortFilter',
        'menuCategorySelectFilter', 'menuStatusFilter', 'menuSortFilter',
        'brandsStatusFilter', 'brandsSortFilter',
        'reviewsStatusFilter', 'reviewsRatingFilter', 'reviewsSortFilter',
        'genReviewsStatusFilter', 'genReviewsRatingFilter', 'genReviewsSortFilter',
        'ordersStatusFilter', 'ordersSortFilter',
        'reservationsStatusFilter',
        'couponsStatusFilter',
        'careersStatusFilter', 'careersPositionFilter',
        'messagesStatusFilter',
        'newsletterStatusFilter',
        'coupon_discount_type',
        'setting_country_select',
        'setting_currency_select',
        'setting_admin_lang',
        'setting_theme',
        'app_user_approval_status'
    ].forEach(id => makeCustomDropdown(id));
}

function makeCustomDropdown(selectId, rebuild = false) {
    const select = document.getElementById(selectId);
    if (!select) return;

    if (select.dataset.customized === 'true' && !rebuild) return;

    // Remove old wrapper if rebuilding
    if (select.nextElementSibling && select.nextElementSibling.classList.contains('custom-select-wrapper')) {
        select.nextElementSibling.remove();
    }

    select.dataset.customized = 'true';
    select.style.display = 'none';

    const wrapper = document.createElement('div');
    wrapper.className = 'custom-select-wrapper';
    wrapper.id = selectId + '-wrapper';
    if (selectId === 'setting_admin_lang' || selectId === 'setting_country_select' || selectId === 'setting_currency_select' || selectId === 'setting_theme') {
        wrapper.classList.add('drop-up');
    } else if (selectId === 'faq_category' || selectId === 'faq_icon_class' || selectId === 'privacy_icon_class' || selectId === 'app_user_approval_status' || selectId === 'customersCityFilter' || selectId === 'representativesCityFilter' || selectId === 'customersStatusFilter' || selectId === 'representativesStatusFilter' || select.closest('#faqModal') || select.closest('#privacySectionModal') || select.closest('#addUserModal')) {
        wrapper.classList.add('drop-down');
    } else if (select.classList.contains('card-status-select')) {
        wrapper.classList.add('drop-up', 'msg-status-dropdown-wrapper', 'card-status-dropdown-wrapper');
    } else if (select.classList.contains('table-status-select')) {
        wrapper.classList.add('msg-status-dropdown-wrapper', 'table-status-dropdown-wrapper');
    }

    const trigger = document.createElement('div');
    trigger.className = 'custom-select-trigger';
    if (select.classList.contains('warning') || select.value === 'unread') {
        trigger.classList.add('warning');
    } else if (select.classList.contains('blue') || select.value === 'read') {
        trigger.classList.add('blue');
    } else if (select.classList.contains('success') || select.value === 'replied') {
        trigger.classList.add('success');
    }

    const selectedOption = select.options[select.selectedIndex];
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const initialText = selectedOption ? (selectedOption.getAttribute(`data-${isAr ? 'ar' : 'en'}`) || selectedOption.text) : '';

    trigger.innerHTML = `<span>${formatOptionStars(initialText)}</span><i class="fas fa-chevron-down arrow"></i>`;

    const menu = document.createElement('div');
    menu.className = 'custom-select-menu glass';

    Array.from(select.options).forEach((opt, idx) => {
        const item = document.createElement('div');
        item.className = `custom-select-item ${select.selectedIndex === idx ? 'selected' : ''}`;
        const optText = opt.getAttribute(`data-${isAr ? 'ar' : 'en'}`) || opt.text;
        item.innerHTML = formatOptionStars(optText);
        item.dataset.value = opt.value;

        item.addEventListener('click', (e) => {
            e.stopPropagation();
            select.value = opt.value;
            trigger.querySelector('span').innerHTML = formatOptionStars(optText);
            menu.querySelectorAll('.custom-select-item').forEach(i => i.classList.remove('selected'));
            item.classList.add('selected');
            menu.classList.remove('open');
            trigger.classList.remove('active');
            wrapper.classList.remove('open');

            trigger.classList.remove('warning', 'blue', 'success');
            if (opt.value === 'unread') trigger.classList.add('warning');
            else if (opt.value === 'read') trigger.classList.add('blue');
            else if (opt.value === 'replied') trigger.classList.add('success');

            select.dispatchEvent(new Event('change'));
        });

        menu.appendChild(item);
    });

    trigger.addEventListener('click', (e) => {
        e.stopPropagation();
        document.querySelectorAll('.custom-select-menu.open').forEach(m => {
            if (m !== menu) m.classList.remove('open');
        });
        document.querySelectorAll('.custom-select-trigger.active').forEach(t => {
            if (t !== trigger) t.classList.remove('active');
        });
        document.querySelectorAll('.custom-select-wrapper.open').forEach(w => {
            if (w !== wrapper) w.classList.remove('open');
        });

        const isOpen = menu.classList.toggle('open');
        trigger.classList.toggle('active', isOpen);
        wrapper.classList.toggle('open', isOpen);
    });

    wrapper.appendChild(trigger);
    wrapper.appendChild(menu);
    select.parentNode.insertBefore(wrapper, select.nextSibling);
}

function updateCustomDropdownsLang(lang) {
    document.querySelectorAll('.custom-select-wrapper').forEach(wrapper => {
        const select = wrapper.previousElementSibling;
        if (!select || select.tagName !== 'SELECT') return;

        const isAr = lang === 'ar';
        const items = wrapper.querySelectorAll('.custom-select-item');
        const triggerSpan = wrapper.querySelector('.custom-select-trigger span');

        Array.from(select.options).forEach((opt, idx) => {
            const text = opt.getAttribute(`data-${isAr ? 'ar' : 'en'}`) || opt.text;
            if (items[idx]) items[idx].textContent = text;
            if (select.selectedIndex === idx && triggerSpan) {
                triggerSpan.textContent = text;
            }
        });
    });
}

document.addEventListener('click', () => {
    document.querySelectorAll('.custom-select-menu.open').forEach(m => m.classList.remove('open'));
    document.querySelectorAll('.custom-select-trigger.active').forEach(t => t.classList.remove('active'));
    document.querySelectorAll('.custom-select-wrapper.open').forEach(w => w.classList.remove('open'));
});

function updateOnlineStatus() {
    const badgeSpan = document.getElementById('system-status-text') || document.querySelector('.hero-badge span');
    const isAr = (document.documentElement.getAttribute('lang') || 'ar') === 'ar';
    if (!badgeSpan) return;

    if (navigator.onLine) {
        badgeSpan.textContent = isAr ? 'زيارة المتجر' : 'Visit Store';
    } else {
        badgeSpan.textContent = isAr ? 'غير متصل بالإنترنت' : 'Offline Mode';
    }
}

window.addEventListener('online', updateOnlineStatus);
window.addEventListener('offline', updateOnlineStatus);

function updateGreetingAndClock() {
    const now = new Date();
    const lang = localStorage.getItem('adminLang') || document.documentElement.getAttribute('lang') || 'ar';
    const el = document.getElementById('live-clock');
    if (el) el.textContent = now.toLocaleTimeString(lang === 'ar' ? 'ar-EG' : 'en-US');
    const hr = now.getHours();

    const nameEl = document.getElementById('admin-display-name');
    let userName = nameEl ? (nameEl.textContent || nameEl.innerText || '').trim() : '';
    if (userName === 'صاحب الحساب' || userName === 'Account Owner' || userName === 'Loading...') {
        userName = '';
    }

    let greet = '';
    if (lang === 'ar') {
        const timeStr = hr < 12 ? "صباح الخير" : "مساء الخير";
        greet = userName ? `${timeStr} يا ${userName} 👋` : timeStr;
    } else {
        const timeStr = hr < 12 ? "Good Morning" : "Good Evening";
        greet = userName ? `${timeStr}, ${userName} 👋` : timeStr;
    }

    const gEl = document.getElementById('dynamic-greeting');
    if (gEl) gEl.textContent = greet;
}

function startLiveClock() {
    updateOnlineStatus();
    updateGreetingAndClock();
    setInterval(updateGreetingAndClock, 1000);
}

async function loadDashboardOverview() {
    const isAr = document.documentElement.getAttribute('lang') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';

    const activityList = document.getElementById('recent-activity-list');
    if (activityList) {
        activityList.innerHTML = `
            <div style="display:flex; flex-direction:column; gap:10px; width:100%; padding:4px 0;">
                <div class="shimmer-skeleton" style="height:54px; width:100%; border-radius:12px;"></div>
                <div class="shimmer-skeleton" style="height:54px; width:100%; border-radius:12px;"></div>
                <div class="shimmer-skeleton" style="height:54px; width:100%; border-radius:12px;"></div>
                <div class="shimmer-skeleton" style="height:54px; width:100%; border-radius:12px;"></div>
            </div>`;
    }

    ['stat-items', 'stat-categories', 'stat-messages', 'stat-comments'].forEach(id => {
        const el = document.getElementById(id);
        if (el) {
            el.innerHTML = `<div class="shimmer-skeleton" style="width:46px; height:28px; border-radius:8px; display:inline-block;"></div>`;
        }
    });

    const greetingEl = document.getElementById('dynamic-greeting');
    if (greetingEl && (greetingEl.textContent === 'Loading...' || !greetingEl.textContent.trim())) {
        greetingEl.innerHTML = `<div class="shimmer-skeleton" style="width:230px; height:32px; border-radius:10px; display:inline-block;"></div>`;
    }

    try {
        let localRes = [];
        try {
            const allLocalRes = JSON.parse(localStorage.getItem('local_reservations_data_' + tenantId) || '[]');
            localRes = Array.isArray(allLocalRes) ? allLocalRes.filter(x => !x.tenant_id || x.tenant_id === tenantId) : [];
        } catch (_) {}

        let [{ count: itemsCount }, { count: catCount }, { count: msgCount }, { count: commentCount }] = await Promise.all([
            supabaseClient.from('menu_items').select('*', { count: 'exact', head: true }).eq('tenant_id', tenantId),
            supabaseClient.from('categories').select('*', { count: 'exact', head: true }).eq('tenant_id', tenantId),
            (async () => {
                let res = await supabaseClient.from('store_contact_messages').select('*').eq('tenant_id', tenantId);
                if (res.error && (res.error.code === '42P01' || res.error.message?.includes('does not exist'))) {
                    res = await supabaseClient.from('contact_messages').select('*').eq('tenant_id', tenantId);
                }
                const unreadList = (res.data || []).filter(m => (!m.is_read && m.status !== 'read' && m.status !== 'replied') || m.status === 'unread');
                return { count: unreadList.length };
            })(),
            (async () => {
                let res = await supabaseClient.from('product_reviews').select('*').eq('tenant_id', tenantId);
                const unreadComm = (res.data || []).filter(r => r.is_approved !== true && r.is_approved !== 'approved' && r.status !== 'approved');
                return { count: unreadComm.length };
            })()
        ]);

        try {
            const { data: tProfile } = await supabaseClient
                .from('tenants')
                .select('owner_name')
                .eq('tenant_id', tenantId)
                .maybeSingle();
            if (tProfile && tProfile.owner_name) {
                const adminNameEl = document.getElementById('admin-display-name');
                if (adminNameEl) adminNameEl.textContent = tProfile.owner_name;
            }
        } catch (_) {}

        if (document.getElementById('stat-items')) animateValue('stat-items', 0, itemsCount || 0, 1000);
        if (document.getElementById('stat-categories')) animateValue('stat-categories', 0, catCount || 0, 1000);
        if (document.getElementById('stat-messages')) animateValue('stat-messages', 0, msgCount || 0, 1000);
        if (document.getElementById('stat-comments')) animateValue('stat-comments', 0, commentCount || 0, 1000);

        const activityList = document.getElementById('recent-activity-list');
        const [msgRes, commRes, userRes] = await Promise.all([
            (async () => {
                let res = await supabaseClient.from('store_contact_messages').select('*').eq('tenant_id', tenantId).order('created_at', { ascending: false }).limit(3);
                if (res.error && (res.error.code === '42P01' || res.error.message?.includes('does not exist'))) {
                    res = await supabaseClient.from('contact_messages').select('*').eq('tenant_id', tenantId).order('created_at', { ascending: false }).limit(3);
                }
                return res;
            })(),
            supabaseClient.from('product_reviews').select('*').eq('tenant_id', tenantId).order('created_at', { ascending: false }).limit(3),
            supabaseClient.from('app_users').select('*').eq('tenant_id', tenantId).order('created_at', { ascending: false }).limit(3)
        ]);
        // 'orders' table was removed by supabase_saas_security_rules.sql; no longer queried here.
        const orderRes = { data: null };

        let all = [];
        if (Array.isArray(localRes)) {
            localRes.slice(0, 2).forEach(x => all.push({ name: x.customer_name || 'Guest', type: isAr ? 'حجز جديد' : 'New Booking', icon: 'fa-calendar-check', date: x.created_at || new Date().toISOString(), section: 'reservations' }));
        }
        if (msgRes.data) msgRes.data.forEach(x => all.push({ name: x.sender_name || x.name || x.customer_name || 'Customer', type: isAr ? 'رسالة جديدة' : 'New Message', icon: 'fa-envelope', date: x.created_at, section: 'messages' }));
        if (commRes.data) commRes.data.forEach(x => all.push({ name: x.user_name || x.customer_name || x.reviewer_name || x.name || 'Customer', type: isAr ? 'تعليق جديد' : 'New Review', icon: 'fa-star', date: x.created_at, section: 'product_reviews' }));

        if (userRes.data) userRes.data.forEach(x => {
            const isRep = (x.account_type === 'representative' || x.role === 'representative' || x.account_type === 'driver' || x.role === 'driver');
            const typeLabel = isAr ? (isRep ? 'طلب تسجيل مندوب' : 'طلب تسجيل عميل') : (isRep ? 'New Representative Registration' : 'New Customer Registration');
            const iconName = isRep ? 'fa-user-tie' : 'fa-user-plus';
            all.push({
                name: x.full_name || x.business_name || x.phone || (isRep ? (isAr ? 'مندوب جديد' : 'New Representative') : (isAr ? 'عميل جديد' : 'New Customer')),
                type: typeLabel,
                icon: iconName,
                date: x.created_at,
                section: isRep ? 'representatives' : 'customers'
            });
        });

        if (orderRes.data) orderRes.data.forEach(x => {
            all.push({
                name: x.customer_name || x.phone || (isAr ? 'عميل' : 'Customer'),
                type: isAr ? `طلب شراء جديد` : `New Order`,
                icon: 'fa-shopping-cart',
                date: x.created_at,
                section: 'orders'
            });
        });

        all.sort((a, b) => new Date(b.date) - new Date(a.date));

        if (all.length > 0 && activityList) {
            activityList.innerHTML = all.slice(0, 4).map(act => {
                // Security: names come from public visitor input (messages/reviews) -> must be escaped (stored XSS)
                const safeSection = String(act.section || '').replace(/[^a-zA-Z0-9_-]/g, '');
                const safeIcon = String(act.icon || '').replace(/[^a-zA-Z0-9_-]/g, '');
                const actDate = new Date(act.date);
                const safeDate = isNaN(actDate.getTime()) ? '' : actDate.toLocaleDateString(isAr ? 'ar-EG' : 'en-US');
                return `
                <div onclick="if(typeof navigateToSection==='function') navigateToSection('${safeSection}')" onmouseenter="this.style.background='rgba(212,175,55,0.08)'" onmouseleave="this.style.background='rgba(255,255,255,0.02)'" style="background:rgba(255,255,255,0.02); padding:10px; border-radius:10px; border:1px solid var(--glass-border); display:flex; justify-content:space-between; align-items:center; margin-bottom:8px; cursor:pointer; transition:all 0.2s ease;" title="${isAr ? 'اضغط للانتقال إلى التفاصيل' : 'Click to go to section'}">
                    <div style="display:flex; align-items:center; gap:10px;">
                        <div style="width:30px; height:30px; background:rgba(197,160,89,0.1); border-radius:50%; display:flex; align-items:center; justify-content:center; color:var(--primary-gold);"><i class="fas ${safeIcon}" style="font-size:0.8rem;"></i></div>
                        <div style="display:flex; flex-direction:column;"><span style="font-size:0.85rem; font-weight:600;">${escapeHtml(act.name)}</span><small style="font-size:0.7rem; opacity:0.6;">${escapeHtml(act.type)}</small></div>
                    </div>
                    <small style="font-size:0.65rem; color:var(--primary-gold);">${safeDate}</small>
                </div>`;
            }).join('');
        } else if (activityList) {
            activityList.innerHTML = `<div style="text-align:center; padding:20px; color:var(--text-dim); font-size:0.88rem;"><i class="fas fa-info-circle"></i> ${isAr ? 'لا توجد نشاطات حالية لهذا المتجر' : 'No recent activities for this store'}</div>`;
        }
    } catch (e) { console.error(e); }
}

