window.normalizeBulkPercentValue = function(rawVal) {
    let s = String(rawVal ?? '');
    // Convert Eastern Arabic and Persian digits to English 0-9
    s = s.replace(/[٠-٩]/g, d => '٠١٢٣٤٥٦٧٨٩'.indexOf(d));
    s = s.replace(/[۰-۹]/g, d => '۰۱۲۳۴۵۶۷۸۹'.indexOf(d));
    // Normalize any unicode minus/dash to standard '-'
    s = s.replace(/[−–—﹣－]/g, '-');
    // Normalize Arabic decimal separator to '.'
    s = s.replace(/[٫,]/g, '.');
    // Remove any invalid characters except digits, '.', '-', '+'
    s = s.replace(/[^0-9.\-+]/g, '');

    // Handle typing '-' when default '0' was still in the input ('0-' or '-0' -> '-')
    if (s === '0-' || s === '-0') return '-';
    if (s === '0+' || s === '+0' || s === '+') return '';

    // Handle '0-5' -> '-5'
    if (/^0-\d/.test(s)) {
        s = '-' + s.slice(2);
    }

    // Handle trailing minus typed after digits (e.g. '5-' -> '-5', or '-5-' -> '5')
    if (s.length > 1 && s.endsWith('-')) {
        const body = s.slice(0, -1).replace(/^[+-]/, '');
        const wasNeg = s.startsWith('-');
        s = (wasNeg ? '' : '-') + body;
    }

    // Strip leading zero before digits (e.g. '05' -> '5', '-05' -> '-5')
    s = s.replace(/^(-?)0+(\d)/, '$1$2');

    return s;
};

window.parseBulkPercentNumber = function(idOrEl) {
    const el = typeof idOrEl === 'string' ? document.getElementById(idOrEl) : idOrEl;
    if (!el) return 0;
    const cleaned = window.normalizeBulkPercentValue(el.value);
    const num = parseFloat(cleaned);
    return isNaN(num) ? 0 : num;
};

window.stepBulkPercent = function(inputId, delta) {
    const el = document.getElementById(inputId);
    if (!el) return;
    const current = window.parseBulkPercentNumber(el);
    const next = Math.round((current + delta) * 100) / 100;
    el.value = String(next);
    window.handleBulkModeChange();
};

window.handleBulkModeChange = function() {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const mode = document.querySelector('input[name="bulkPricingMode"]:checked')?.value || 'direct_adjustment';
    const retDesc = document.getElementById('bulk_retail_desc');
    const wsDesc = document.getElementById('bulk_wholesale_desc');
    const repDesc = document.getElementById('bulk_rep_desc');

    const cleanNum = (id) => {
        const el = document.getElementById(id);
        if (!el) return 0;
        const normalized = window.normalizeBulkPercentValue(el.value);
        if (el.value !== normalized) {
            el.value = normalized;
        }
        const num = parseFloat(normalized);
        return isNaN(num) ? 0 : num;
    };

    const numRet = cleanNum('bulk_input_retail_percent');
    const numWs = cleanNum('bulk_input_wholesale_percent');
    const numRep = cleanNum('bulk_input_rep_percent');

    const formatDirectDesc = (n) => {
        const numSpan = `<span class="bulk-en-number" style="font-family: 'Inter', Arial, sans-serif !important; direction: ltr; display: inline-block; font-weight: 800; color: ${n < 0 ? '#f87171' : (n > 0 ? '#34d399' : 'inherit')};">(${n > 0 ? '+' : ''}${n}%)</span>`;
        if (n < 0) {
            return isAr ? `تخفيض السعر الحالي بنسبة ${numSpan}` : `Discount current price ${numSpan}`;
        } else if (n > 0) {
            return isAr ? `رفع السعر الحالي بنسبة ${numSpan}` : `Raise current price ${numSpan}`;
        }
        return isAr ? `تعديل السعر الحالي بنسبة ${numSpan}` : `Adjust current price ${numSpan}`;
    };

    const formatCostDesc = (n) => {
        const sign = n < 0 ? '-' : '+';
        const absN = Math.abs(n);
        const numSpan = `<span class="bulk-en-number" style="font-family: 'Inter', Arial, sans-serif !important; direction: ltr; display: inline-block; font-weight: 800;">${sign} ${absN}%</span>`;
        return isAr ? `سعر التكلفة ${numSpan}` : `Cost ${numSpan}`;
    };

    if (mode === 'direct_adjustment') {
        if (retDesc) retDesc.innerHTML = formatDirectDesc(numRet);
        if (wsDesc) wsDesc.innerHTML = formatDirectDesc(numWs);
        if (repDesc) repDesc.innerHTML = formatDirectDesc(numRep);
    } else {
        if (retDesc) retDesc.innerHTML = formatCostDesc(numRet);
        if (wsDesc) wsDesc.innerHTML = formatCostDesc(numWs);
        if (repDesc) repDesc.innerHTML = formatCostDesc(numRep);
    }
};

window.renderBulkCategoriesChecklist = async function() {
    const container = document.getElementById('bulkCategoriesChecklist');
    if (!container) return;

    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';

    let cats = (window.allCategoriesData && window.allCategoriesData.length > 0) ? window.allCategoriesData : [];
    if (cats.length === 0 && typeof supabaseClient !== 'undefined' && supabaseClient) {
        try {
            const { data } = await supabaseClient
                .from('categories')
                .select('*')
                .eq('tenant_id', tenantId)
                .order('display_order', { ascending: true });
            if (data) {
                cats = data;
                window.allCategoriesData = data;
            }
        } catch (_) {}
    }

    // Filter out trashed categories
    const activeCats = cats.filter(c => !(typeof isCategoryTrashed === 'function' && isCategoryTrashed(c)) && !c.is_deleted);

    if (activeCats.length === 0) {
        container.innerHTML = `<div style="grid-column: 1 / -1; text-align: center; padding: 14px; font-size: 0.78rem; color: var(--text-dim);">${isAr ? 'لا توجد أقسام متاحة' : 'No categories available'}</div>`;
        return;
    }

    // Sort so primary categories come first followed by their subcategories
    const primaryCats = activeCats.filter(c => !c.parent_id);
    const orderedCats = [];
    const visited = new Set();

    const addWithChildren = (cat, depth = 0) => {
        if (visited.has(String(cat.id))) return;
        visited.add(String(cat.id));
        orderedCats.push({ cat, depth });
        const children = activeCats.filter(ch => String(ch.parent_id) === String(cat.id));
        children.forEach(ch => addWithChildren(ch, depth + 1));
    };

    primaryCats.forEach(p => addWithChildren(p, 0));
    activeCats.forEach(c => {
        if (!visited.has(String(c.id))) addWithChildren(c, 0);
    });

    const allChecked = document.getElementById('bulk_select_all_categories')?.checked !== false;

    container.innerHTML = orderedCats.map(({ cat, depth }) => {
        const name = isAr ? (cat.name_ar || cat.name_en || '') : (cat.name_en || cat.name_ar || '');
        const parentCat = cat.parent_id ? activeCats.find(p => String(p.id) === String(cat.parent_id)) : null;
        const parentName = parentCat ? (isAr ? (parentCat.name_ar || parentCat.name_en) : (parentCat.name_en || parentCat.name_ar)) : '';
        const typeLabel = depth === 0
            ? (isAr ? 'قسم رئيسي' : 'Primary')
            : (parentName ? `${isAr ? 'فرع من:' : 'Sub of:'} ${parentName}` : (isAr ? 'قسم فرعي' : 'Subcategory'));

        const prefixHtml = depth > 0
            ? `<span class="bulk-subcat-branch-icon" aria-hidden="true"><svg viewBox="0 0 16 16" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M12.5 2V9C12.5 10.1046 11.6046 11 10.5 11H3.5M3.5 11L6.8 7.8M3.5 11L6.8 14.2" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></span>`
            : `<span class="bulk-maincat-folder-icon" aria-hidden="true">📁</span>`;
        const safeSearch = `${cat.name_ar || ''} ${cat.name_en || ''} ${parentName || ''}`.toLowerCase().replace(/"/g, '&quot;');

        return `
        <label class="bulk-cat-check-item ${allChecked ? 'is-checked' : ''} ${depth > 0 ? 'is-subcat-item' : 'is-maincat-item'}" data-search="${safeSearch}" data-cat-id="${cat.id}" data-parent-id="${cat.parent_id || ''}">
            <input type="checkbox" class="bulk-category-checkbox" value="${cat.id}" ${allChecked ? 'checked' : ''} onchange="handleBulkCategoryItemToggle(this)">
            <div class="bulk-cat-check-label">
                <span class="bulk-cat-check-name" title="${name.replace(/"/g, '&quot;')}">${prefixHtml}<span class="bulk-cat-check-name-text">${name}</span></span>
                <span class="bulk-cat-check-meta">${typeLabel}</span>
            </div>
        </label>`;
    }).join('');

    window.updateBulkCategoryBadge();
};

window.toggleAllBulkCategories = function(isChecked) {
    const checkboxes = document.querySelectorAll('#bulkCategoriesChecklist .bulk-category-checkbox');
    checkboxes.forEach(cb => {
        cb.checked = isChecked;
        const row = cb.closest('.bulk-cat-check-item');
        if (row) row.classList.toggle('is-checked', isChecked);
    });
    window.updateBulkCategoryBadge();
};

window.handleBulkCategoryItemToggle = function(checkboxEl) {
    const isChecked = checkboxEl.checked;
    const catId = String(checkboxEl.value);
    const row = checkboxEl.closest('.bulk-cat-check-item');
    if (row) row.classList.toggle('is-checked', isChecked);

    // Also auto-toggle direct & nested subcategories of this category for convenience
    const allCats = window.allCategoriesData || [];
    const getDescendants = (parentId) => {
        const res = [];
        const children = allCats.filter(c => String(c.parent_id) === String(parentId));
        children.forEach(ch => {
            res.push(String(ch.id));
            res.push(...getDescendants(ch.id));
        });
        return res;
    };
    const descendantIds = new Set(getDescendants(catId));
    if (descendantIds.size > 0) {
        document.querySelectorAll('#bulkCategoriesChecklist .bulk-category-checkbox').forEach(cb => {
            if (descendantIds.has(String(cb.value))) {
                cb.checked = isChecked;
                const r = cb.closest('.bulk-cat-check-item');
                if (r) r.classList.toggle('is-checked', isChecked);
            }
        });
    }

    const allCbs = Array.from(document.querySelectorAll('#bulkCategoriesChecklist .bulk-category-checkbox'));
    const allSelected = allCbs.length > 0 && allCbs.every(cb => cb.checked);
    const selectAllEl = document.getElementById('bulk_select_all_categories');
    if (selectAllEl) selectAllEl.checked = allSelected;

    window.updateBulkCategoryBadge();
};

window.updateBulkCategoryBadge = function() {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const badge = document.getElementById('bulkSelectedCatsBadge');
    if (!badge) return;

    const allCbs = Array.from(document.querySelectorAll('#bulkCategoriesChecklist .bulk-category-checkbox'));
    const checkedCbs = allCbs.filter(cb => cb.checked);
    const selectAllEl = document.getElementById('bulk_select_all_categories');

    if ((selectAllEl && selectAllEl.checked) || (allCbs.length > 0 && checkedCbs.length === allCbs.length)) {
        badge.textContent = allCbs.length > 0
            ? (isAr ? `جميع الأقسام (${allCbs.length})` : `All Categories (${allCbs.length})`)
            : (isAr ? 'جميع الأقسام' : 'All Categories');
    } else if (checkedCbs.length === 0) {
        badge.textContent = isAr ? 'لم يتم تحديد أي قسم (0)' : 'None selected (0)';
    } else {
        badge.textContent = isAr
            ? `تم تحديد ${checkedCbs.length} من ${allCbs.length}`
            : `${checkedCbs.length} of ${allCbs.length} selected`;
    }
};

window.filterBulkCategoriesList = function(query) {
    const normAr = (str) => String(str || '')
        .trim()
        .toLowerCase()
        .replace(/[أإآ]/g, 'ا')
        .replace(/ة/g, 'ه')
        .replace(/ى/g, 'ي')
        .replace(/[\u064B-\u065F]/g, '');

    const q = normAr(query);
    const container = document.getElementById('bulkCategoriesChecklist');
    const items = document.querySelectorAll('#bulkCategoriesChecklist .bulk-cat-check-item');
    let visibleCount = 0;

    items.forEach(item => {
        const hay = normAr(item.getAttribute('data-search') || item.textContent || '');
        const isMatch = !q || hay.includes(q);
        item.classList.toggle('is-hidden-search', !isMatch);
        if (isMatch) visibleCount++;
    });

    let emptyEl = document.getElementById('bulkCatSearchEmptyMsg');
    if (visibleCount === 0 && items.length > 0) {
        if (!emptyEl && container) {
            const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
            emptyEl = document.createElement('div');
            emptyEl.id = 'bulkCatSearchEmptyMsg';
            emptyEl.style.cssText = 'grid-column: 1 / -1; text-align: center; padding: 14px; font-size: 0.78rem; color: var(--text-dim);';
            emptyEl.textContent = isAr ? 'لا توجد نتائج مطابقة للبحث' : 'No matching categories found';
            container.appendChild(emptyEl);
        }
        if (emptyEl) emptyEl.style.display = 'block';
    } else if (emptyEl) {
        emptyEl.style.display = 'none';
    }
};

window.getUserCustomDiscount = function(userObj) {
    if (!userObj) return 0;
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    
    // 1. Supabase database value is the ultimate Single Source of Truth
    if (userObj.custom_discount_percent !== undefined && userObj.custom_discount_percent !== null) {
        const val = parseFloat(userObj.custom_discount_percent) || 0;
        // Keep localStorage in sync with database truth
        if (userObj.id) {
            try {
                const key = 'user_custom_discounts_' + tenantId;
                const map = JSON.parse(localStorage.getItem(key) || '{}');
                map[String(userObj.id)] = val;
                localStorage.setItem(key, JSON.stringify(map));
            } catch (_) {}
        }
        return val;
    }

    // 2. Fallback only if database column is not present on user object
    try {
        const map = JSON.parse(localStorage.getItem('user_custom_discounts_' + tenantId) || '{}');
        if (userObj.id && map[String(userObj.id)] !== undefined && map[String(userObj.id)] !== null) {
            return parseFloat(map[String(userObj.id)]) || 0;
        }
    } catch (_) {}

    return 0;
};

window.saveUserCustomDiscountLocal = function(userId, pct) {
    if (!userId) return;
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    try {
        const key = 'user_custom_discounts_' + tenantId;
        const map = JSON.parse(localStorage.getItem(key) || '{}');
        map[String(userId)] = parseFloat(pct) || 0;
        localStorage.setItem(key, JSON.stringify(map));
    } catch (_) {}
};

window.clearUserCustomDiscountLocal = function(userId) {
    if (!userId) return;
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    try {
        const key = 'user_custom_discounts_' + tenantId;
        const map = JSON.parse(localStorage.getItem(key) || '{}');
        delete map[String(userId)];
        localStorage.setItem(key, JSON.stringify(map));
    } catch (_) {}
};

window.calculateUserCustomPrice = function(itemOrVariant, userObjOrId) {
    if (!itemOrVariant) {
        return { basePrice: 0, finalPrice: 0, discountPercent: 0, isModified: false, roleLabel: '', userName: '' };
    }

    let user = null;
    if (typeof userObjOrId === 'object' && userObjOrId) {
        user = userObjOrId;
    } else if (userObjOrId && userObjOrId !== 'standard') {
        const allUsers = [
            ...(window.allTenantAppUsersCache || []),
            ...(window.allCustomersData || []),
            ...(window.allCustomerServiceData || []),
            ...(window.allRepresentativesData || [])
        ];
        user = allUsers.find(u => u && String(u.id) === String(userObjOrId));
    }

    const rawRetail = parseFloat(itemOrVariant.price) || (parseFloat(itemOrVariant.sale_price) || (parseFloat(itemOrVariant.cost_price) || 0));
    if (!user) {
        return {
            basePrice: rawRetail,
            finalPrice: rawRetail,
            discountPercent: 0,
            isModified: false,
            roleLabel: '',
            userName: ''
        };
    }

    const cls = (typeof window.classifyAppUserRole === 'function') ? window.classifyAppUserRole(user) : 'customer';
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    let basePrice = rawRetail;
    let roleLabel = isAr ? 'عميل' : 'Customer';

    if (cls === 'representative') {
        const repP = parseFloat(itemOrVariant.rep_price);
        basePrice = (!isNaN(repP) && repP > 0) ? repP : rawRetail;
        roleLabel = isAr ? 'مندوب' : 'Rep';
    } else if (cls === 'merchant' || cls === 'customer_service') {
        const wsP = parseFloat(itemOrVariant.wholesale_price);
        basePrice = (!isNaN(wsP) && wsP > 0) ? wsP : rawRetail;
        roleLabel = (cls === 'merchant') ? (isAr ? 'تاجر جملة' : 'Wholesale') : (isAr ? 'خدمة عملاء' : 'Customer Service');
    }

    if (basePrice <= 0 && rawRetail > 0) {
        basePrice = rawRetail;
    }

    const dbDiscountVal = (typeof window.getUserCustomDiscount === 'function') ? window.getUserCustomDiscount(user) : (parseFloat(user.custom_discount_percent) || 0);
    let finalPrice = basePrice;
    let displayPercent = 0;

    if (dbDiscountVal !== 0 && basePrice > 0) {
        // In DB custom_discount_percent: positive is discount (capped at 99%), negative is markup (raise price)
        const safeDiscount = Math.min(99, dbDiscountVal);
        finalPrice = Math.max(0.01, Math.round((basePrice * (1 - (safeDiscount / 100))) * 100) / 100);
        // In UI display: positive (+) is raise/markup, negative (-) is discount
        displayPercent = Math.round((-safeDiscount) * 10) / 10;
    }

    return {
        basePrice,
        finalPrice,
        discountPercent: displayPercent,
        rawDiscountPercent: dbDiscountVal,
        isModified: dbDiscountVal !== 0 || basePrice !== rawRetail,
        roleLabel,
        userName: user.full_name || user.business_name || (isAr ? 'حساب مخصص' : 'Custom User')
    };
};

window.populateMenuPricingPreviewSelect = function() {
    const select = document.getElementById('menuUserPricingPreviewSelect');
    if (!select) return;

    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const currentVal = select.value || 'standard';

    const allUsers = [
        ...(window.allTenantAppUsersCache || []),
        ...(window.allCustomersData || []),
        ...(window.allCustomerServiceData || []),
        ...(window.allRepresentativesData || [])
    ];
    const seen = new Set();
    const uniqueUsers = allUsers.filter(u => {
        if (!u || !u.id || seen.has(String(u.id))) return false;
        seen.add(String(u.id));
        return true;
    });

    let html = `<option value="standard" ${currentVal === 'standard' ? 'selected' : ''}>${isAr ? '🌐 الأسعار العامة الافتراضية' : '🌐 Standard Catalog Prices'}</option>`;

    // Group 1: Merchants & Customers
    const merchants = uniqueUsers.filter(u => {
        const c = window.classifyAppUserRole ? window.classifyAppUserRole(u) : 'customer';
        return c === 'merchant' || c === 'customer' || c === 'customer_service';
    });
    if (merchants.length > 0) {
        html += `<optgroup label="${isAr ? '🏪 تجار الجملة والعملاء' : 'Wholesale & Customers'}">`;
        merchants.forEach(u => {
            const rawPct = window.getUserCustomDiscount(u);
            const pct = Math.round((-rawPct) * 10) / 10;
            const pctText = pct !== 0 ? ` (${pct > 0 ? '+' : ''}${pct}%)` : '';
            const biz = (u.business_name && u.business_name !== 'EMPTY') ? ` • ${u.business_name}` : '';
            const name = `${u.full_name || 'حساب'}${biz}${pctText}`;
            html += `<option value="${u.id}" ${currentVal === String(u.id) ? 'selected' : ''}>${escapeHtml(name)}</option>`;
        });
        html += `</optgroup>`;
    }

    // Group 2: Representatives
    const reps = uniqueUsers.filter(u => {
        const c = window.classifyAppUserRole ? window.classifyAppUserRole(u) : 'customer';
        return c === 'representative';
    });
    if (reps.length > 0) {
        html += `<optgroup label="${isAr ? '👔 المناديب' : 'Sales Reps'}">`;
        reps.forEach(u => {
            const rawPct = window.getUserCustomDiscount(u);
            const pct = Math.round((-rawPct) * 10) / 10;
            const pctText = pct !== 0 ? ` (${pct > 0 ? '+' : ''}${pct}%)` : '';
            const name = `${u.full_name || 'مندوب'}${pctText}`;
            html += `<option value="${u.id}" ${currentVal === String(u.id) ? 'selected' : ''}>${escapeHtml(name)}</option>`;
        });
        html += `</optgroup>`;
    }

    select.innerHTML = html;
};

