window.deleteUserRecord = function(userId, accountType) {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const message = isAr ? 'هل أنت تأكد من رغبتك في حذف هذا الحساب نهائياً من قاعدة البيانات؟' : 'Are you sure you want to delete this account permanently?';

    if (typeof openConfirm === 'function') {
        openConfirm({
            title: isAr ? 'تأكيد حذف الحساب' : 'Confirm Delete Account',
            text: message,
            btnText: isAr ? 'نعم، احذف الحساب' : 'Yes, Delete Account',
            btnClass: 'btn-danger-confirm',
            onConfirm: async () => {
                try {
                    showToast(isAr ? 'جاري حذف الحساب...' : 'Deleting account...', 'info');
                    const { error } = await supabaseClient.from('app_users').delete().eq('id', userId).eq('tenant_id', tenantId);
                    if (error) throw error;

                    showToast(isAr ? '🗑️ تم حذف الحساب بنجاح' : 'Account deleted successfully', 'success');
                    if (accountType === 'customer') window.loadCustomersData();
                    else if (accountType === 'customer_service') window.loadCustomerServiceUsersData();
                    else window.loadRepresentativesData();
                } catch (err) {
                    console.error('Error deleting user:', err);
                    showToast(err.message || 'حدث خطأ أثناء حذف الحساب', 'error');
                }
            }
        });
    } else {
        if (confirm(message)) {
            (async () => {
                try {
                    showToast(isAr ? 'جاري حذف الحساب...' : 'Deleting account...', 'info');
                    const { error } = await supabaseClient.from('app_users').delete().eq('id', userId).eq('tenant_id', tenantId);
                    if (error) throw error;

                    showToast(isAr ? '🗑️ تم حذف الحساب بنجاح' : 'Account deleted successfully', 'success');
                    if (accountType === 'customer') window.loadCustomersData();
                    else if (accountType === 'customer_service') window.loadCustomerServiceUsersData();
                    else window.loadRepresentativesData();
                } catch (err) {
                    console.error('Error deleting user:', err);
                    showToast(err.message || 'حدث خطأ أثناء حذف الحساب', 'error');
                }
            })();
        }
    }
};

window.toggleAppUserActiveStatus = async function(userId, currentStatus, accountType) {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const newStatus = !currentStatus;

    try {
        showToast(isAr ? 'جاري تحديث حالة الحساب...' : 'Updating account status...', 'info');

        let { data, error } = await supabaseClient
            .from('app_users')
            .update({ is_active: newStatus, updated_at: new Date().toISOString() })
            .eq('id', userId)
            .eq('tenant_id', tenantId)
            .select();

        if (error) throw error;

        const list = accountType === 'customer' ? (window.allCustomersData || []) : (accountType === 'customer_service' ? (window.allCustomerServiceData || []) : (window.allRepresentativesData || []));
        const u = list.find(x => String(x.id) === String(userId));
        if (u) u.is_active = newStatus;

        if (accountType === 'customer') window.filterCustomersTable();
        else if (accountType === 'customer_service') window.filterCustomerServiceUsersTable();
        else window.filterRepresentativesTable();

        showToast(isAr ? (newStatus ? '✨ تم تفعيل الحساب بنجاح' : '🔒 تم تعطيل الحساب') : 'Status updated', 'success');
    } catch (err) {
        console.error('Error toggling app user status:', err);
        showToast(err.message || 'حدث خطأ أثناء تحديث الحالة', 'error');
    }
};

