/* --- SAAS TENANT PERSONAL ACCOUNT HANDLER --- */
window.loadUsersData = async function() {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const activeEmail = sessionStorage.getItem('admin_demo_email') || '';

    let localTenant = null;
    try {
        const stored = localStorage.getItem('local_tenant_profile_' + tenantId);
        if (stored) localTenant = JSON.parse(stored);
    } catch (_) {}

    try {
        let { data, error } = await supabaseClient
            .from('tenants')
            .select('*')
            .eq('tenant_id', tenantId)
            .maybeSingle();

        if (!data && activeEmail) {
            let { data: emailMatch } = await supabaseClient
                .from('tenants')
                .select('*')
                .eq('owner_email', activeEmail)
                .maybeSingle();
            if (emailMatch) data = emailMatch;
        }

        const t = Object.assign({}, localTenant || {}, data || {});
        window.currentTenantData = t;

        // Update top-left profile display name with actual owner name
        const adminNameEl = document.getElementById('admin-display-name');
        if (adminNameEl) {
            adminNameEl.textContent = t.owner_name || (activeEmail ? activeEmail.split('@')[0] : 'صاحب الحساب');
        }

        // Populate Editable Fields
        const ownerNameInput = document.getElementById('tenant_owner_name');
        if (ownerNameInput) ownerNameInput.value = t.owner_name || '';

        const ownerEmailInput = document.getElementById('tenant_owner_email');
        if (ownerEmailInput) {
            ownerEmailInput.value = t.owner_email || (typeof activeEmail !== 'undefined' ? activeEmail : '') || 'muneeralreesh@gmail.com';
            ownerEmailInput.readOnly = true;
            ownerEmailInput.style.cursor = 'not-allowed';
            ownerEmailInput.style.opacity = '0.75';
            ownerEmailInput.title = isAr ? 'البريد الإلكتروني غير قابل للتغيير من لوحة التحكم' : 'Email address is read-only';
        }

        const ownerPhoneInput = document.getElementById('tenant_owner_phone');
        if (ownerPhoneInput) ownerPhoneInput.value = t.owner_phone || '';

        const merchantBusinessInput = document.getElementById('merchant_business_name');
        if (merchantBusinessInput) merchantBusinessInput.value = t.business_name || '';

        const merchantCityInput = document.getElementById('merchant_city');
        if (merchantCityInput) merchantCityInput.value = t.city || '';

        // Populate ReadOnly SaaS Subscription Details
        const displayIdEl = document.getElementById('tenant_display_id');
        if (displayIdEl) displayIdEl.textContent = t.tenant_id || tenantId;

        const planBadge = document.getElementById('tenant_subscription_badge');
        if (planBadge) planBadge.textContent = t.subscription_plan || 'الباقة الذهبية';

        const statusBadge = document.getElementById('tenant_status_badge');
        if (statusBadge) {
            const st = (t.status || 'active').toLowerCase().trim();
            if (st === 'active' || st === 'نشط') {
                statusBadge.textContent = '● نشط (Active)';
                statusBadge.style.background = 'rgba(16,185,129,0.18)';
                statusBadge.style.color = '#10b981';
            } else if (st === 'expired' || st === 'منتهي') {
                statusBadge.textContent = '● منتهي الاشتراك (Expired)';
                statusBadge.style.background = 'rgba(239,68,68,0.18)';
                statusBadge.style.color = '#ef4444';
            } else {
                statusBadge.textContent = '● معلّق (Suspended)';
                statusBadge.style.background = 'rgba(245,158,11,0.18)';
                statusBadge.style.color = '#f59e0b';
            }
        }

        function formatArabicDateWithMonthName(dateStr) {
            if (!dateStr) return '---';
            const monthsAr = [
                'يناير', 'فبراير', 'مارس', 'أبريل', 'مايو', 'يونيو',
                'يوليو', 'أغسطس', 'سبتمبر', 'أكتوبر', 'نوفمبر', 'ديسمبر'
            ];
            const d = new Date(dateStr);
            if (isNaN(d.getTime())) return dateStr;
            const day = d.getDate();
            const monthName = monthsAr[d.getMonth()];
            const year = d.getFullYear();
            return isAr ? `${day} ${monthName} ${year}` : d.toLocaleDateString('en-US', { year: 'numeric', month: 'short', day: 'numeric' });
        }

        const expiryEl = document.getElementById('tenant_expiry_display');
        const daysLeftEl = document.getElementById('tenant_expiry_days_left');
        if (expiryEl) {
            if (t.expiry_date) {
                expiryEl.textContent = formatArabicDateWithMonthName(t.expiry_date);
                const expDate = new Date(t.expiry_date);
                const diffTime = expDate - new Date();
                const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
                if (daysLeftEl) {
                    if (diffDays > 0) {
                        daysLeftEl.innerHTML = `<i class="fas fa-clock"></i> ${isAr ? `متبقي ${diffDays} يوماً على انتهاء الاشتراك` : `${diffDays} days remaining`}`;
                        daysLeftEl.className = 'days-remaining-pill';
                    } else {
                        daysLeftEl.innerHTML = `<i class="fas fa-exclamation-triangle"></i> ${isAr ? 'منتهي الاشتراك' : 'Expired'}`;
                        daysLeftEl.className = 'days-remaining-pill badge-days-expired';
                    }
                }
            } else {
                expiryEl.textContent = isAr ? 'اشتراك مفتوح (دائم)' : 'Permanent / Lifetime';
                if (daysLeftEl) {
                    daysLeftEl.innerHTML = `<i class="fas fa-infinity"></i> ${isAr ? 'اشتراك سارٍ بشكل دائم' : 'Lifetime subscription'}`;
                    daysLeftEl.className = 'days-remaining-pill';
                }
            }
        }

        const createdEl = document.getElementById('tenant_created_at_display');
        if (createdEl) {
            if (t.created_at) {
                createdEl.textContent = formatArabicDateWithMonthName(t.created_at);
            } else {
                createdEl.textContent = isAr ? '30 أكتوبر 2026' : 'October 30, 2026';
            }
        }

    } catch (err) {
        console.error('Error loading tenant profile:', err);
    }
};

