window.saveTenantProfile = async function(e) {
    if (e) e.preventDefault();
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';

    // Security: only profile fields are editable by the owner. tenant_id / owner_email / status / expiry_date
    // must never be sent from the client (changing owner_email would hand the store to another account).
    const payload = {
        owner_name: document.getElementById('tenant_owner_name')?.value?.trim() || '',
        owner_phone: document.getElementById('tenant_owner_phone')?.value?.trim() || '',
        business_name: document.getElementById('merchant_business_name')?.value?.trim() || '',
        city: document.getElementById('merchant_city')?.value?.trim() || ''
    };

    try {
        showToast(isAr ? 'جاري حفظ بيانات الحساب الشخصي...' : 'Saving tenant profile...', 'info');

        try {
            const cachedProfile = Object.assign({ tenant_id: tenantId, owner_email: document.getElementById('tenant_owner_email')?.value?.trim() || '' }, payload);
            localStorage.setItem('local_tenant_profile_' + tenantId, JSON.stringify(cachedProfile));
        } catch (err) {
            console.warn('LocalStorage save error:', err);
        }

        let res = await supabaseClient
            .from('tenants')
            .update(payload)
            .eq('tenant_id', tenantId)
            .select('tenant_id');

        // Retry without columns that don't exist in this database schema
        let guard = 0;
        while (res.error && guard < 4) {
            guard++;
            const missingCol = res.error.message ? (res.error.message.match(/Could not find the '([^']+)' column/i) || [])[1] : null;
            if (!missingCol || !(missingCol in payload)) break;
            delete payload[missingCol];
            res = await supabaseClient.from('tenants').update(payload).eq('tenant_id', tenantId).select('tenant_id');
        }

        if (res.error || !Array.isArray(res.data) || res.data.length === 0) {
            console.warn('Supabase tenants save note:', res.error ? res.error.message : 'no row updated (RLS)');
            showToast(isAr ? '⚠️ تعذر حفظ بيانات الحساب في قاعدة البيانات' : 'Could not save profile to the database', 'error');
            return;
        }

        showToast(isAr ? '✨ تم حفظ بيانات الحساب الشخصي بنجاح' : 'Personal account saved successfully', 'success');
        if (payload.owner_name) {
            const adminNameEl = document.getElementById('admin-display-name');
            if (adminNameEl) adminNameEl.textContent = payload.owner_name;
        }
        window.loadUsersData();
        await validateTenantSession();

    } catch (err) {
        console.error('Error saving tenant profile:', err);
        showToast(err.message || 'حدث خطأ أثناء حفظ الحساب الشخصي', 'error');
    }
};

window.togglePassVisibility = function(inputId, btnEl) {
    const input = document.getElementById(inputId);
    if (!input) return;
    const icon = btnEl?.querySelector('i');
    if (input.type === 'password') {
        input.type = 'text';
        if (icon) icon.className = 'fas fa-eye-slash';
    } else {
        input.type = 'password';
        if (icon) icon.className = 'fas fa-eye';
    }
};

window.updateTenantPassword = async function() {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const currentPass = document.getElementById('tenant_current_password')?.value?.trim();
    const newPass = document.getElementById('tenant_new_password')?.value?.trim();
    const confirmPass = document.getElementById('tenant_confirm_password')?.value?.trim();

    if (!newPass || newPass.length < 6) {
        showToast(isAr ? '⚠️ يجب أن تكون كلمة المرور الجديدة 6 أحرف على الأقل' : 'Password must be at least 6 characters', 'error');
        return;
    }

    if (newPass !== confirmPass) {
        showToast(isAr ? '⚠️ كلمة المرور الجديدة وتأكيد كلمة المرور غير متطابقين' : 'Passwords do not match', 'error');
        return;
    }

    try {
        showToast(isAr ? 'جاري تحديث كلمة المرور...' : 'Updating password...', 'info');

        if (typeof supabaseClient !== 'undefined' && supabaseClient.auth) {
            const ownerEmail = document.getElementById('tenant_owner_email')?.value?.trim() || sessionStorage.getItem('admin_demo_email') || localStorage.getItem('admin_demo_email');

            // If user provided current password, verify it cryptographically against Supabase Auth
            if (currentPass && ownerEmail) {
                const { error: verifyErr } = await supabaseClient.auth.signInWithPassword({
                    email: ownerEmail,
                    password: currentPass
                });
                if (verifyErr) {
                    showToast(isAr ? '⚠️ كلمة المرور الحالية غير صحيحة' : 'Current password is incorrect', 'error');
                    return;
                }
            }

            const { error: updateError } = await supabaseClient.auth.updateUser({
                password: newPass
            });

            if (updateError) {
                throw updateError;
            }
        }

        // Purge any legacy plaintext password from localStorage
        localStorage.removeItem('local_tenant_password');
        localStorage.removeItem('local_tenant_password_' + tenantId);

        const passInput0 = document.getElementById('tenant_current_password');
        const passInput1 = document.getElementById('tenant_new_password');
        const passInput2 = document.getElementById('tenant_confirm_password');
        if (passInput0) passInput0.value = '';
        if (passInput1) passInput1.value = '';
        if (passInput2) passInput2.value = '';

        showToast(isAr ? '🔒 تم تحديث كلمة المرور بنجاح! استخدمها عند الدخول القادم' : 'Password updated successfully', 'success');
        const ownerEmail = document.getElementById('tenant_owner_email')?.value?.trim() || sessionStorage.getItem('admin_demo_email') || '';
        if (typeof window.openCustomPasswordSaveModal === 'function') {
            window.openCustomPasswordSaveModal(ownerEmail, newPass, () => {});
        }

    } catch (err) {
        console.error('Error updating tenant password:', err);
        showToast(err.message || (isAr ? 'حدث خطأ أثناء تحديث كلمة المرور' : 'Error updating password'), 'error');
    }
};

