window.getCurrencySymbol = function() {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const settings = window.currentSiteSettingsData;
    if (settings) {
        if (isAr && settings.currency_ar && settings.currency_ar.trim() !== '') {
            return settings.currency_ar.trim();
        }
        if (!isAr && settings.currency_en && settings.currency_en.trim() !== '') {
            return settings.currency_en.trim();
        }
    }
    const selEl = document.getElementById('setting_currency_select');
    if (selEl && selEl.value && window.currencyMap && window.currencyMap[selEl.value]) {
        const curObj = window.currencyMap[selEl.value];
        return isAr ? curObj.ar : curObj.en;
    }
    const elAr = document.getElementById('setting_currency_ar')?.value;
    const elEn = document.getElementById('setting_currency_en')?.value;
    if (isAr && elAr && elAr.trim() !== '') return elAr.trim();
    if (!isAr && elEn && elEn.trim() !== '') return elEn.trim();

    return isAr ? 'ر.س' : 'SAR';
};

window.onCurrencySelectChange = function(code) {
    const cur = window.currencyMap[code] || window.currencyMap['YER'];
    const elAr = document.getElementById('setting_currency_ar');
    const elEn = document.getElementById('setting_currency_en');
    if (elAr) elAr.value = cur.ar;
    if (elEn) elEn.value = cur.en;
    if (!window.currentSiteSettingsData) window.currentSiteSettingsData = {};
    window.currentSiteSettingsData.currency_ar = cur.ar;
    window.currentSiteSettingsData.currency_en = cur.en;
};

async function loadSettingsData() {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';

    let localData = null;
    try {
        const stored = localStorage.getItem('local_site_settings_' + tenantId);
        if (stored) localData = JSON.parse(stored);
    } catch (_) {}

    try {
        let { data, error } = await supabaseClient
            .from('site_settings')
            .select('*')
            .eq('tenant_id', tenantId)
            .maybeSingle();

        if (error) {
            console.warn('Fetch site_settings note:', error.message);
        }

        // Supabase DB data takes precedence so direct changes in DB reflect immediately in dashboard
        const d = Object.assign({}, localData || {}, data || {});
        window.currentSiteSettingsData = d;
        if (data && Object.keys(data).length > 0) {
            try {
                localStorage.setItem('local_site_settings_' + tenantId, JSON.stringify(d));
            } catch (_) {}
        }

        // Fetch tenant details from public.tenants to get store name & contact for new tenants
        let tenantRow = null;
        try {
            let { data: tData } = await supabaseClient
                .from('tenants')
                .select('restaurant_name_ar, restaurant_name_en, owner_phone, owner_email')
                .eq('tenant_id', tenantId)
                .maybeSingle();
            if (tData) tenantRow = tData;
        } catch (_) {}

        const fallbackAr = tenantRow?.restaurant_name_ar || '';
        const fallbackEn = tenantRow?.restaurant_name_en || '';
        const fallbackPhone = tenantRow?.owner_phone || '';
        const fallbackEmail = tenantRow?.owner_email || '';

        // Update sidebar store name branding
        const sideBrandEl = document.querySelector('.sidebar .restaurant-name');
        if (sideBrandEl) sideBrandEl.textContent = d.site_name_ar || fallbackAr;

        const setVal = (id, val, defaultVal) => {
            const el = document.getElementById(id);
            if (el) {
                el.value = (val !== undefined && val !== null) ? val : (defaultVal !== undefined ? defaultVal : '');
            }
        };

        const logoMain = (d.logo_url && !d.logo_url.includes('logo.png')) ? d.logo_url : '';
        const logoLight = (d.logo_url_light && !d.logo_url_light.includes('logo-light.png')) ? d.logo_url_light : '';

        // 1. Identity & Logos
        setVal('setting_site_name_ar', d.site_name_ar, fallbackAr);
        setVal('setting_site_name_en', d.site_name_en, fallbackEn);

        const logoMainInput = document.getElementById('setting_logo_url');
        if (logoMainInput) logoMainInput.value = logoMain;

        const logoLightInput = document.getElementById('setting_logo_url_light');
        if (logoLightInput) logoLightInput.value = logoLight;

        // Populate hidden multi-size logo tracking inputs
        if (document.getElementById('setting_logo_favicon_url')) document.getElementById('setting_logo_favicon_url').value = d.favicon_url || '';
        if (document.getElementById('setting_logo_apple_icon_url')) document.getElementById('setting_logo_apple_icon_url').value = d.apple_icon_url || '';
        if (document.getElementById('setting_logo_pwa_192_url')) document.getElementById('setting_logo_pwa_192_url').value = d.pwa_icon_url || '';
        if (document.getElementById('setting_logo_og_url')) document.getElementById('setting_logo_og_url').value = d.og_image_url || '';
        if (document.getElementById('setting_logo_r2_key')) document.getElementById('setting_logo_r2_key').value = d.logo_r2_key || '';
        if (document.getElementById('setting_logo_hash')) document.getElementById('setting_logo_hash').value = d.logo_hash || '';

        if (document.getElementById('setting_logo_favicon_url_light')) document.getElementById('setting_logo_favicon_url_light').value = d.favicon_url_light || '';
        if (document.getElementById('setting_logo_apple_icon_url_light')) document.getElementById('setting_logo_apple_icon_url_light').value = d.apple_icon_url_light || '';
        if (document.getElementById('setting_logo_pwa_192_url_light')) document.getElementById('setting_logo_pwa_192_url_light').value = d.pwa_icon_url_light || '';
        if (document.getElementById('setting_logo_og_url_light')) document.getElementById('setting_logo_og_url_light').value = d.og_image_url_light || '';
        if (document.getElementById('setting_logo_light_r2_key')) document.getElementById('setting_logo_light_r2_key').value = d.logo_light_r2_key || '';
        if (document.getElementById('setting_logo_light_hash')) document.getElementById('setting_logo_light_hash').value = d.logo_light_hash || '';

        if (typeof window.updateLogoButtonState === 'function') {
            window.updateLogoButtonState('setting_logo_url', 'btn_logo_main_text', 'btn_logo_main_icon');
            window.updateLogoButtonState('setting_logo_url_light', 'btn_logo_light_text', 'btn_logo_light_icon');
        }

        if (typeof window.updateSidebarLogo === 'function') {
            window.updateSidebarLogo();
        }

        if (typeof window.updateStoreLogoMultiPreview === 'function') {
            window.updateStoreLogoMultiPreview(logoMain, d.favicon_url, d.pwa_icon_url, d.og_image_url);
        }

        if (typeof window.initAdaptiveThemeIcons === 'function') {
            window.initAdaptiveThemeIcons(d);
        }

        const bgLight = (d.logo_bg_light && d.logo_bg_light.trim() !== '') ? d.logo_bg_light : '#ffffff';
        setVal('setting_logo_bg_light', bgLight, '#ffffff');
        if (document.getElementById('setting_logo_bg_light_picker')) document.getElementById('setting_logo_bg_light_picker').value = bgLight;

        const bgDark = (d.logo_bg_dark && d.logo_bg_dark.trim() !== '') ? d.logo_bg_dark : '#22073e';
        setVal('setting_logo_bg_dark', bgDark, '#22073e');
        if (document.getElementById('setting_logo_bg_dark_picker')) document.getElementById('setting_logo_bg_dark_picker').value = bgDark;

        // 2. Country, Currency & Admin Language
        const countryEl = document.getElementById('setting_country_select');
        if (countryEl) {
            countryEl.value = d.country || 'YE';
            if (typeof makeCustomDropdown === 'function') makeCustomDropdown('setting_country_select', true);
        }

        let curCode = 'YER';
        if (d.currency_en) {
            const cleanEn = d.currency_en.trim().toUpperCase();
            const foundCode = Object.keys(window.currencyMap).find(k => k === cleanEn || window.currencyMap[k].en.toUpperCase() === cleanEn);
            if (foundCode) curCode = foundCode;
        } else if (d.currency_ar) {
            const cleanAr = d.currency_ar.trim();
            const foundCode = Object.keys(window.currencyMap).find(k => window.currencyMap[k].ar === cleanAr || cleanAr.includes(window.currencyMap[k].ar));
            if (foundCode) curCode = foundCode;
        }

        const selEl = document.getElementById('setting_currency_select');
        if (selEl) {
            selEl.value = curCode;
            window.onCurrencySelectChange(curCode);
            if (typeof makeCustomDropdown === 'function') makeCustomDropdown('setting_currency_select', true);
        }

        const langEl = document.getElementById('setting_admin_lang');
        if (langEl) {
            langEl.value = d.admin_lang || localStorage.getItem('adminLang') || 'ar';
            if (typeof makeCustomDropdown === 'function') makeCustomDropdown('setting_admin_lang', true);
            langEl.onchange = function() {
                const lang = this.value;
                localStorage.setItem('adminLang', lang);
                if (typeof applyLanguage === 'function') applyLanguage(lang);
            };
        }

        if (typeof applyTheme === 'function') applyTheme('dark');

        // 3. Contact & Social
        setVal('setting_phone_number', d.phone_number, fallbackPhone);
        setVal('setting_whatsapp_number', d.whatsapp_number, fallbackPhone);
        setVal('setting_email', d.email, fallbackEmail);
        setVal('setting_facebook_url', d.facebook_url, '');
        setVal('setting_instagram_url', d.instagram_url, '');
        setVal('setting_twitter_url', d.twitter_url, '');
        setVal('setting_tiktok_url', d.tiktok_url, '');
        setVal('setting_snapchat_url', d.snapchat_url, '');

        // 4. Copyright & Theme Colors
        setVal('setting_copyright_ar', d.copyright_ar, '');
        setVal('setting_copyright_en', d.copyright_en, '');

        const primaryCol = (d.primary_color && d.primary_color.trim() !== '') ? d.primary_color : '#d97706';
        setVal('setting_primary_color', primaryCol, '#d97706');
        if (document.getElementById('setting_primary_color_picker')) document.getElementById('setting_primary_color_picker').value = primaryCol;

        const iconsCol = (d.icons_color && d.icons_color.trim() !== '') ? d.icons_color : '#fbbf24';
        setVal('setting_icons_color', iconsCol, '#fbbf24');
        if (document.getElementById('setting_icons_color_picker')) document.getElementById('setting_icons_color_picker').value = iconsCol;

        const iconsColDark = (d.icons_color_dark && d.icons_color_dark.trim() !== '') ? d.icons_color_dark : '#f59e0b';
        setVal('setting_icons_color_dark', iconsColDark, '#f59e0b');
        if (document.getElementById('setting_icons_color_dark_picker')) document.getElementById('setting_icons_color_dark_picker').value = iconsColDark;

        const brandTextLight = (d.brand_text_light && d.brand_text_light.trim() !== '') ? d.brand_text_light : '#0f172a';
        setVal('setting_brand_text_light', brandTextLight, '#0f172a');
        if (document.getElementById('setting_brand_text_light_picker')) document.getElementById('setting_brand_text_light_picker').value = brandTextLight;

        const brandTextDark = (d.brand_text_dark && d.brand_text_dark.trim() !== '') ? d.brand_text_dark : '#ffffff';
        setVal('setting_brand_text_dark', brandTextDark, '#ffffff');
        if (document.getElementById('setting_brand_text_dark_picker')) document.getElementById('setting_brand_text_dark_picker').value = brandTextDark;

        if (typeof window.updateSidebarThemeColors === 'function') {
            window.updateSidebarThemeColors();
        }

        // 4.5 Store Pricing Policy & Visibility Settings
        const repVal = (d.default_markup_rep !== undefined) ? d.default_markup_rep : (d.rep_discount_percent !== undefined ? d.rep_discount_percent : 5);
        const wholesaleVal = (d.default_markup_wholesale !== undefined) ? d.default_markup_wholesale : (d.customer_discount_percent !== undefined ? d.customer_discount_percent : 10);
        const retailVal = (d.default_markup_retail !== undefined) ? d.default_markup_retail : (d.cost_margin_percent !== undefined ? d.cost_margin_percent : 15);
        const hideGuestsVal = (d.hide_prices_guests !== undefined) ? d.hide_prices_guests : (d.hide_guest_prices === true);

        setVal('setting_default_markup_rep', repVal, 5);
        setVal('setting_default_markup_wholesale', wholesaleVal, 10);
        setVal('setting_default_markup_retail', retailVal, 15);
        if (document.getElementById('setting_hide_prices_guests')) {
            document.getElementById('setting_hide_prices_guests').checked = hideGuestsVal;
        }
        if (document.getElementById('setting_hide_prices_wholesale')) {
            document.getElementById('setting_hide_prices_wholesale').checked = d.hide_prices_wholesale === true || d.hide_customer_prices === true;
        }
        if (document.getElementById('setting_hide_prices_rep')) {
            document.getElementById('setting_hide_prices_rep').checked = d.hide_prices_rep === true;
        }

        // 5. AI Settings
        setVal('setting_gemini_api_key', d.gemini_api_key, '');
        setVal('setting_ai_system_prompt', d.ai_system_prompt, 'أنت مساعد ذكي مخصص لمتجر التقوى للتجارة، تجيب عن استفسارات العملاء بدقة ولباقت وحرفية عالية.');

    } catch (err) {
        console.error('Error loading site settings:', err);
    }
}

window.toggleEditGeminiKey = function() {
    const input = document.getElementById('setting_gemini_api_key');
    const textEl = document.getElementById('text_gemini_key');
    const iconEl = document.getElementById('icon_gemini_key');
    const btn = document.getElementById('btn_toggle_gemini_key');
    if (!input) return;

    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const isCurrentlyDisabled = input.disabled || input.readOnly;

    if (isCurrentlyDisabled) {
        // Unlock field for editing (keep masked as password dots, no raw text reveal)
        input.disabled = false;
        input.readOnly = false;
        input.type = 'password';
        input.focus();
        input.select();

        if (textEl) textEl.textContent = isAr ? 'تأكيد' : 'Confirm';
        if (iconEl) iconEl.className = 'fas fa-check';
        if (btn) btn.style.background = 'linear-gradient(135deg, #10b981 0%, #059669 100%)';
        showToast(isAr ? 'ℹ️ يمكنك الآن تعديل أو إدخال مفتاح API جديد' : 'You can now edit API Key', 'info');
    } else {
        // Lock field after editing
        input.disabled = true;
        input.type = 'password';

        if (textEl) textEl.textContent = isAr ? 'تعديل' : 'Edit';
        if (iconEl) iconEl.className = 'fas fa-key';
        if (btn) btn.style.background = '';
        showToast(isAr ? '✨ تم تأكيد وتأمين مفتاح API بنجاح' : 'API Key confirmed & locked', 'success');
    }
};

window.updateLogoButtonState = function(inputId, textId, iconId) {
    const input = document.getElementById(inputId);
    const textEl = document.getElementById(textId);
    const iconEl = document.getElementById(iconId);
    if (!input) return;

    const hasValue = input.value && input.value.trim() !== '';
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';

    if (textEl) {
        textEl.textContent = hasValue ? (isAr ? 'تغيير' : 'Change') : (isAr ? 'رفع' : 'Upload');
    }
    if (iconEl) {
        iconEl.className = hasValue ? 'fas fa-sync-alt' : 'fas fa-upload';
    }
};

window.updateSidebarLogo = function() {
    const isLight = document.body.classList.contains('light-mode') || document.documentElement.getAttribute('data-theme') === 'light';
    const d = window.currentSiteSettingsData || {};

    const logoMain = (d.logo_url && !d.logo_url.includes('logo.png')) ? d.logo_url : '';
    const logoLight = (d.logo_url_light && !d.logo_url_light.includes('logo-light.png')) ? d.logo_url_light : '';

    let activeLogo = '';
    if (isLight) {
        activeLogo = logoLight || logoMain;
    } else {
        activeLogo = logoMain || logoLight;
    }

    const logoImg = document.querySelector('.sidebar .admin-logo');
    if (logoImg) {
        if (activeLogo) {
            logoImg.src = activeLogo;
            logoImg.style.display = 'block';
        } else {
            logoImg.src = '';
            logoImg.style.display = 'none';
        }
    }

    if (typeof window.updateHeaderProfileAvatar === 'function') {
        window.updateHeaderProfileAvatar();
    }
};

