window.handleLogout = function(event) {
    if (event) {
        try { event.preventDefault(); event.stopPropagation(); } catch(_) {}
    }

    // Immediately close sidebar drawer and backdrop overlay
    try {
        const sidebar = document.getElementById('sidebar');
        const overlay = document.getElementById('sidebarOverlay');
        if (sidebar) sidebar.classList.remove('open');
        if (overlay) overlay.classList.remove('show');
    } catch (_) {}

    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    openConfirm({
        title: isAr ? 'تسجيل الخروج' : 'Log Out',
        text: isAr ? 'هل أنت متأكد من رغبتك في تسجيل الخروج من لوحة التحكم؟' : 'Are you sure you want to log out of the admin portal?',
        icon: 'fas fa-sign-out-alt',
        iconColor: '#ef4444',
        btnText: isAr ? 'نعم، تسجيل الخروج' : 'Yes, Log Out',
        btnClass: 'btn-danger-confirm',
        onConfirm: async () => {
            try {
                const sidebar = document.getElementById('sidebar');
                const overlay = document.getElementById('sidebarOverlay');
                if (sidebar) sidebar.classList.remove('open');
                if (overlay) overlay.classList.remove('show');
            } catch (_) {}
            sessionStorage.setItem('admin_logged_out', 'true');
            sessionStorage.removeItem('admin_demo_email');
            sessionStorage.removeItem('admin_session_active');
            localStorage.removeItem('sb-auth-token');
            if (typeof supabaseClient !== 'undefined' && supabaseClient?.auth) {
                try { await supabaseClient.auth.signOut(); } catch(e) {}
            }
            window.location.href = 'login.html';
        }
    });
};

window.saveGeneralSettings = async function(e) {
    if (e) e.preventDefault();
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';

    // Also persist custom storefront website URL when updated in General Settings
    try {
        const webUrlInput = document.getElementById('setting_website_url');
        if (webUrlInput && webUrlInput.value) {
            const cleanUrl = webUrlInput.value.trim();
            localStorage.setItem('client_website_url_' + tenantId, cleanUrl);
            if (typeof window.updateSaaSClientWebsiteLink === 'function') {
                window.updateSaaSClientWebsiteLink();
            }
        }
    } catch (_) {}

    const getVal = (id, defaultVal) => {
        const val = document.getElementById(id)?.value?.trim();
        return (val && val !== '') ? val : defaultVal;
    };

    const curCode = document.getElementById('setting_currency_select')?.value || 'YER';
    const curObj = (window.currencyMap && window.currencyMap[curCode]) ? window.currencyMap[curCode] : { ar: 'ريال يمني', en: 'YER' };
    const curAr = document.getElementById('setting_currency_ar')?.value?.trim() || curObj.ar;
    const curEn = document.getElementById('setting_currency_en')?.value?.trim() || curObj.en;

    const payload = {
        tenant_id: tenantId,
        country: document.getElementById('setting_country_select')?.value || 'YE',
        site_name_ar: document.getElementById('setting_site_name_ar')?.value?.trim() || '',
        site_name_en: document.getElementById('setting_site_name_en')?.value?.trim() || '',
        logo_url: document.getElementById('setting_logo_url')?.value?.trim() || '',
        logo_url_light: document.getElementById('setting_logo_url_light')?.value?.trim() || '',
        favicon_url: document.getElementById('setting_logo_favicon_url')?.value?.trim() || null,
        apple_icon_url: document.getElementById('setting_logo_apple_icon_url')?.value?.trim() || null,
        pwa_icon_url: document.getElementById('setting_logo_pwa_192_url')?.value?.trim() || null,
        og_image_url: document.getElementById('setting_logo_og_url')?.value?.trim() || null,
        logo_r2_key: document.getElementById('setting_logo_r2_key')?.value?.trim() || null,
        logo_hash: document.getElementById('setting_logo_hash')?.value?.trim() || null,
        favicon_url_light: document.getElementById('setting_logo_favicon_url_light')?.value?.trim() || null,
        apple_icon_url_light: document.getElementById('setting_logo_apple_icon_url_light')?.value?.trim() || null,
        pwa_icon_url_light: document.getElementById('setting_logo_pwa_192_url_light')?.value?.trim() || null,
        og_image_url_light: document.getElementById('setting_logo_og_url_light')?.value?.trim() || null,
        logo_light_r2_key: document.getElementById('setting_logo_light_r2_key')?.value?.trim() || null,
        logo_light_hash: document.getElementById('setting_logo_light_hash')?.value?.trim() || null,
        client_domain: (typeof window.getActiveClientDomain === 'function') ? window.getActiveClientDomain() : tenantId,
        logo_bg_light: document.getElementById('setting_logo_bg_light')?.value?.trim() || '#ffffff',
        logo_bg_dark: document.getElementById('setting_logo_bg_dark')?.value?.trim() || '#22073e',
        currency_ar: curAr,
        currency_en: curEn,
        admin_lang: document.getElementById('setting_admin_lang')?.value || 'ar',
        admin_theme: 'dark',
        phone_number: document.getElementById('setting_phone_number')?.value?.trim() || '',
        whatsapp_number: document.getElementById('setting_whatsapp_number')?.value?.trim() || '',
        email: document.getElementById('setting_email')?.value?.trim() || '',
        facebook_url: document.getElementById('setting_facebook_url')?.value?.trim() || '',
        instagram_url: document.getElementById('setting_instagram_url')?.value?.trim() || '',
        twitter_url: document.getElementById('setting_twitter_url')?.value?.trim() || '',
        tiktok_url: document.getElementById('setting_tiktok_url')?.value?.trim() || '',
        snapchat_url: document.getElementById('setting_snapchat_url')?.value?.trim() || '',
        copyright_ar: document.getElementById('setting_copyright_ar')?.value?.trim() || '',
        copyright_en: document.getElementById('setting_copyright_en')?.value?.trim() || '',
        primary_color: document.getElementById('setting_primary_color')?.value?.trim() || '#d97706',
        icons_color: document.getElementById('setting_icons_color')?.value?.trim() || '#fbbf24',
        icons_color_dark: document.getElementById('setting_icons_color_dark')?.value?.trim() || '#f59e0b',
        brand_text_light: document.getElementById('setting_brand_text_light')?.value?.trim() || '#0f172a',
        brand_text_dark: document.getElementById('setting_brand_text_dark')?.value?.trim() || '#ffffff',
        gemini_api_key: document.getElementById('setting_gemini_api_key')?.value?.trim() || '',
        ai_system_prompt: document.getElementById('setting_ai_system_prompt')?.value?.trim() || '',
        default_markup_rep: parseFloat(document.getElementById('setting_default_markup_rep')?.value) || 5,
        default_markup_wholesale: parseFloat(document.getElementById('setting_default_markup_wholesale')?.value) || 10,
        default_markup_retail: parseFloat(document.getElementById('setting_default_markup_retail')?.value) || 15,
        hide_prices_guests: document.getElementById('setting_hide_prices_guests')?.checked === true,
        hide_prices_wholesale: document.getElementById('setting_hide_prices_wholesale')?.checked === true,
        hide_prices_rep: document.getElementById('setting_hide_prices_rep')?.checked === true
    };

    window.currentSiteSettingsData = Object.assign(window.currentSiteSettingsData || {}, payload);

    try {
        showToast(isAr ? 'جاري حفظ الإعدادات العامة للموقع...' : 'Saving site settings...', 'info');

        // Always persist locally so clears/edits persist 100% across page reloads
        try {
            localStorage.setItem('local_site_settings_' + tenantId, JSON.stringify(payload));
        } catch (e) {
            console.warn('LocalStorage save error:', e);
        }

        // Always preserve current active UI language when saving settings
        const currentActiveLang = localStorage.getItem('adminLang') || 'ar';
        localStorage.setItem('adminLang', currentActiveLang);
        if (typeof applyLanguage === 'function') applyLanguage(currentActiveLang);

        // Whitelist of valid Supabase site_settings columns
        const KNOWN_SITE_SETTINGS_COLUMNS = new Set([
            'tenant_id', 'country', 'site_name_ar', 'site_name_en', 'logo_url', 'logo_url_light',
            'favicon_url', 'apple_icon_url', 'pwa_icon_url', 'og_image_url', 'logo_r2_key', 'logo_hash',
            'favicon_url_light', 'apple_icon_url_light', 'pwa_icon_url_light', 'og_image_url_light', 'logo_light_r2_key', 'logo_light_hash',
            'client_domain',
            'logo_bg_light', 'logo_bg_dark', 'currency_ar', 'currency_en', 'admin_lang',
            'phone_number', 'whatsapp_number', 'email', 'facebook_url', 'instagram_url',
            'twitter_url', 'tiktok_url', 'snapchat_url', 'copyright_ar', 'copyright_en',
            'primary_color', 'icons_color', 'icons_color_dark', 'brand_text_light', 'brand_text_dark',
            'gemini_api_key', 'ai_system_prompt', 'app_name_ar', 'app_name_en',
            'hide_guest_prices', 'hide_customer_prices', 'rep_discount_percent',
            'customer_discount_percent', 'cost_margin_percent', 'require_approval_to_view_prices',
            'b2b_registration_enabled'
        ]);

        // Build clean DB payload with valid schema columns
        const dbPayload = {};
        for (const [key, val] of Object.entries(payload)) {
            if (KNOWN_SITE_SETTINGS_COLUMNS.has(key)) {
                dbPayload[key] = val;
            }
        }
        // Map pricing policies to existing database columns
        dbPayload.rep_discount_percent = payload.default_markup_rep;
        dbPayload.customer_discount_percent = payload.default_markup_wholesale;
        dbPayload.cost_margin_percent = payload.default_markup_retail;
        dbPayload.hide_guest_prices = payload.hide_prices_guests;
        dbPayload.hide_customer_prices = payload.hide_prices_wholesale;

        // Check if row exists for update vs upsert
        let { data: existingRow } = await supabaseClient
            .from('site_settings')
            .select('id')
            .eq('tenant_id', tenantId)
            .maybeSingle();

        let saveError = null;
        let currentPayload = { ...dbPayload };

        // Self-healing save loop that handles any schema cache mismatch automatically
        for (let attempt = 0; attempt < 5; attempt++) {
            let res;
            if (existingRow && existingRow.id) {
                res = await supabaseClient
                    .from('site_settings')
                    .update(currentPayload)
                    .eq('tenant_id', tenantId);
            } else {
                res = await supabaseClient
                    .from('site_settings')
                    .upsert(currentPayload, { onConflict: 'tenant_id' });
            }

            saveError = res.error;
            if (!saveError) break; // Saved successfully!

            const errMsg = saveError.message || '';
            const colMatch = errMsg.match(/Could not find the '([^']+)' column/i);
            if (colMatch && colMatch[1]) {
                const missingCol = colMatch[1];
                console.warn(`Stripping unknown column '${missingCol}' from site_settings payload and retrying:`, errMsg);
                delete currentPayload[missingCol];
                continue;
            }

            if (errMsg.includes('brand_text') || saveError.code === 'PGRST204') {
                delete currentPayload.brand_text_light;
                delete currentPayload.brand_text_dark;
                continue;
            }

            break; // Other error, stop loop
        }

        if (saveError) {
            console.error('Supabase save error:', saveError.message);
            showToast(isAr ? '⚠️ خطأ أثناء الحفظ في قاعدة البيانات: ' + saveError.message : 'DB save error: ' + saveError.message, 'error');
        } else {
            showToast(isAr ? '✨ تم حفظ الإعدادات العامة بنجاح' : 'Site settings saved successfully', 'success');
        }

        // Always preserve current active UI language without page reload
        localStorage.setItem('adminLang', currentActiveLang);
        if (typeof applyLanguage === 'function') {
            applyLanguage(currentActiveLang);
        }
    } catch (err) {
        console.error('Error saving site_settings:', err);
        showToast(err.message || 'حدث خطأ أثناء حفظ الإعدادات', 'error');
    }
};



