/* ==========================================================================
   Brands Management (SaaS Multi-Tenant - Cards View Only)
   ========================================================================== */
window.allBrandsData = [];
window.brandsKpiFilter = 'all';

async function loadBrandsData(forceRefresh = false) {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const gridWrapper = document.getElementById('brands-grid-wrapper');
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';

    if (forceRefresh && typeof window.clearTenantStaleLocalOverrides === 'function') {
        window.clearTenantStaleLocalOverrides(tenantId, 'brands');
    }

    const hasPreCachedBrands = !forceRefresh && Array.isArray(window.allBrandsData) && window.allBrandsData.length > 0;

    if (hasPreCachedBrands) {
        const total = window.allBrandsData.length;
        const active = window.allBrandsData.filter(b => b.is_active !== false).length;
        const hidden = total - active;
        if (document.getElementById('kpi-brands-total')) document.getElementById('kpi-brands-total').innerText = total;
        if (document.getElementById('kpi-brands-active')) document.getElementById('kpi-brands-active').innerText = active;
        if (document.getElementById('kpi-brands-hidden')) document.getElementById('kpi-brands-hidden').innerText = hidden;
        filterBrandsTable();
    } else if (gridWrapper) {
        gridWrapper.innerHTML = renderShimmerCards(8);
    }

    try {
        const [brandRes, menuItemsRes, catsRes] = await Promise.all([
            supabaseClient.from('brands').select('*').eq('tenant_id', tenantId).order('created_at', { ascending: false }),
            supabaseClient.from('menu_items').select('*').eq('tenant_id', tenantId).order('created_at', { ascending: false }),
            supabaseClient.from('categories').select('*').eq('tenant_id', tenantId)
        ]);

        let data = brandRes.data;
        let error = brandRes.error;

        if (error) {
            console.warn('Supabase fetch brands note:', error.message);
            const retry = await supabaseClient
                .from('brands')
                .select('*')
                .eq('tenant_id', tenantId);
            if (retry.data) data = retry.data;
        }

        if (menuItemsRes && menuItemsRes.data && typeof mergeMenuItemsWithLocal === 'function') {
            window.allMenuItemsData = mergeMenuItemsWithLocal(tenantId, menuItemsRes.data);
        }
        if (catsRes && catsRes.data && typeof mergeCategoriesWithLocal === 'function') {
            window.allCategoriesData = mergeCategoriesWithLocal(tenantId, catsRes.data);
        }

        window.allBrandsData = mergeBrandsWithLocal(tenantId, data || []);

        // Update KPI Counters
        const total = window.allBrandsData.length;
        const active = window.allBrandsData.filter(b => b.is_active !== false).length;
        const hidden = total - active;

        const kpiTotal = document.getElementById('kpi-brands-total');
        const kpiActive = document.getElementById('kpi-brands-active');
        const kpiHidden = document.getElementById('kpi-brands-hidden');

        if (kpiTotal) kpiTotal.innerText = total;
        if (kpiActive) kpiActive.innerText = active;
        if (kpiHidden) kpiHidden.innerText = hidden;

        filterBrandsTable();

        if (typeof makeCustomDropdown === 'function') {
            makeCustomDropdown('brandsStatusFilter');
            makeCustomDropdown('brandsSortFilter');
        }
        if (window.sectionLoadedState) window.sectionLoadedState['brands'] = true;
    } catch (err) {
        console.error('Error loading brands:', err);
        window.allBrandsData = mergeBrandsWithLocal(tenantId, []);
        filterBrandsTable();
        if (gridWrapper && window.allBrandsData.length === 0) {
            gridWrapper.innerHTML = `
                <div style="grid-column: 1 / -1; text-align: center; padding: 30px; color: #ef4444;">
                    <i class="fas fa-exclamation-triangle fa-2x" style="margin-bottom:8px;"></i>
                    <p>${isAr ? 'فشل جلب العلامات التجارية' : 'Failed to load brands'}: ${err.message}</p>
                </div>
            `;
        }
    }
}

window.loadBrandsData = loadBrandsData;

window.refreshBrandsData = async function(btn) {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    if (btn) {
        const icon = btn.querySelector('i');
        if (icon) icon.classList.add('fa-spin');
        setTimeout(() => icon?.classList.remove('fa-spin'), 1000);
    }
    if (typeof window.clearTenantStaleLocalOverrides === 'function') {
        window.clearTenantStaleLocalOverrides(tenantId, 'brands');
        window.clearTenantStaleLocalOverrides(tenantId, 'menu');
    }
    await loadBrandsData(true);
    showToast(isAr ? '✨ تم تحديث بيانات العلامات التجارية من قاعدة البيانات' : 'Brands refreshed from database', 'success');
};

window.filterBrandsByKpi = function(filterType) {
    window.brandsKpiFilter = filterType;
    const statusSelect = document.getElementById('brandsStatusFilter');
    if (statusSelect) {
        statusSelect.value = filterType === 'active' ? 'active' : (filterType === 'hidden' ? 'hidden' : 'all');
        if (typeof makeCustomDropdown === 'function') {
            makeCustomDropdown('brandsStatusFilter', true);
        }
    }
    filterBrandsTable();
};

window.filterBrandsTable = function() {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';

    const searchVal = (document.getElementById('brandsSearchInput')?.value || '').toLowerCase().trim();
    const statusVal = document.getElementById('brandsStatusFilter')?.value || 'all';
    const sortVal = document.getElementById('brandsSortFilter')?.value || 'order';

    let list = [...(window.allBrandsData || [])];

    // Search filter
    if (searchVal) {
        list = list.filter(b =>
            (b.name_ar && b.name_ar.toLowerCase().includes(searchVal)) ||
            (b.name_en && b.name_en.toLowerCase().includes(searchVal))
        );
    }

    // Status filter
    if (statusVal === 'active') {
        list = list.filter(b => b.is_active !== false);
    } else if (statusVal === 'hidden') {
        list = list.filter(b => b.is_active === false);
    }

    // Sort
    if (sortVal === 'order') {
        list.sort((a, b) => (a.display_order || 0) - (b.display_order || 0));
    } else if (sortVal === 'newest') {
        list.sort((a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0));
    } else if (sortVal === 'name') {
        list.sort((a, b) => (a.name_ar || '').localeCompare(b.name_ar || ''));
    }

    window.currentFilteredBrandsData = list;
    updateBrandsBulkBarUI(isAr);
    renderBrandsGrid(list);
};

if (!window.selectedBrandIds) window.selectedBrandIds = new Set();

window.toggleBrandSelectionMode = () => {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const btn = document.getElementById('btn-toggle-brands-select');
    const label = document.getElementById('btnBrandsSelectLabel');

    const visibleList = window.currentFilteredBrandsData || window.allBrandsData || [];
    if (visibleList.length === 0) {
        showToast(isAr ? 'لا توجد علامات تجارية قابلة للتحديد' : 'No brands to select', 'warning');
        return;
    }

    if (window.isBrandSelectionModeActive) {
        window.isBrandSelectionModeActive = false;
        if (window.selectedBrandIds) window.selectedBrandIds.clear();
        if (btn) btn.classList.remove('active-selected');
        if (label) label.textContent = isAr ? 'تحديد' : 'Select';
    } else {
        window.isBrandSelectionModeActive = true;
        if (btn) btn.classList.add('active-selected');
        if (label) label.textContent = isAr ? 'إلغاء التحديد' : 'Deselect';
    }

    updateBrandsBulkBarUI(isAr);
    filterBrandsTable();
};

window.handleBrandCardClick = (event, brandId) => {
    if (!window.isBrandSelectionModeActive) return;
    if (event.target.closest('button, a, input, select, label')) return;

    const isSelected = window.selectedBrandIds ? window.selectedBrandIds.has(String(brandId)) : false;
    toggleBrandSelection(brandId, !isSelected);
};

window.toggleBrandSelection = (id, isChecked) => {
    if (!window.selectedBrandIds) window.selectedBrandIds = new Set();
    if (isChecked) {
        window.selectedBrandIds.add(String(id));
    } else {
        window.selectedBrandIds.delete(String(id));
    }
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    updateBrandsBulkBarUI(isAr);
    filterBrandsTable();
};

window.toggleSelectAllBrands = (isChecked) => {
    if (!window.selectedBrandIds) window.selectedBrandIds = new Set();
    const visibleBrands = window.currentFilteredBrandsData || window.allBrandsData || [];
    visibleBrands.forEach(b => {
        if (isChecked) {
            window.selectedBrandIds.add(String(b.id));
        } else {
            window.selectedBrandIds.delete(String(b.id));
        }
    });
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    updateBrandsBulkBarUI(isAr);
    filterBrandsTable();
};

window.clearSelectedBrands = () => {
    if (window.selectedBrandIds) window.selectedBrandIds.clear();
    window.isBrandSelectionModeActive = false;
    const btn = document.getElementById('btn-toggle-brands-select');
    const label = document.getElementById('btnBrandsSelectLabel');
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    if (btn) btn.classList.remove('active-selected');
    if (label) label.textContent = isAr ? 'تحديد' : 'Select';
    updateBrandsBulkBarUI(isAr);
    filterBrandsTable();
};

function updateBrandsBulkBarUI(isAr) {
    const bulkBar = document.getElementById('brands-bulk-actions-bar');
    const selectAllCheckbox = document.getElementById('brandsSelectAllCheckbox');
    const selectAllText = document.getElementById('brandsSelectAllText');
    const selectedCountText = document.getElementById('brandsSelectedCountText');

    const selectedCount = window.selectedBrandIds ? window.selectedBrandIds.size : 0;
    const visibleBrands = window.currentFilteredBrandsData || window.allBrandsData || [];
    const allPageSelected = visibleBrands.length > 0 && visibleBrands.every(b => window.selectedBrandIds.has(String(b.id)));

    if (selectAllCheckbox) selectAllCheckbox.checked = allPageSelected;

    if (selectAllText) {
        selectAllText.textContent = isAr ? `تحديد الكل (${visibleBrands.length})` : `Select All (${visibleBrands.length})`;
    }

    if (bulkBar) {
        if (window.isBrandSelectionModeActive || selectedCount > 0) {
            bulkBar.style.display = 'flex';
        } else {
            bulkBar.style.display = 'none';
        }
    }

    if (selectedCountText) {
        selectedCountText.textContent = isAr ? `تم تحديد ${selectedCount} عنصر` : `${selectedCount} selected`;
    }
}

window.bulkUpdateBrandsStatus = async (isActive) => {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const selectedIds = Array.from(window.selectedBrandIds || []);
    if (selectedIds.length === 0) {
        showToast(isAr ? 'يرجى تحديد علامة تجارية واحدة على الأقل' : 'Please select at least one brand first', 'warning');
        return;
    }

    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    showToast(isAr ? 'جاري تحديث حالة العلامات المحددة...' : 'Updating status...', 'info');

    try {
        const { error } = await supabaseClient
            .from('brands')
            .update({ is_active: isActive, updated_at: new Date().toISOString() })
            .in('id', selectedIds)
            .eq('tenant_id', tenantId);

        if (error) throw error;

        showToast(isAr ? '✨ تم تحديث حالة العلامات المحددة بنجاح' : 'Status updated successfully', 'success');
        clearSelectedBrands();
        loadBrandsData();
    } catch (err) {
        console.error('Error bulk updating brands status:', err);
        showToast(err.message, 'error');
    }
};

window.bulkDeleteBrands = () => {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const selectedIds = Array.from(window.selectedBrandIds || []);
    if (selectedIds.length === 0) {
        showToast(isAr ? 'يرجى تحديد علامة تجارية واحدة على الأقل' : 'Please select at least one brand first', 'warning');
        return;
    }

    openConfirm({
        title: isAr ? 'تأكيد الحذف الجماعي' : 'Confirm Bulk Delete',
        text: isAr ? `هل أنت متأكد من حذف ${selectedIds.length} علامة تجارية محددة؟` : `Are you sure you want to delete ${selectedIds.length} selected brands?`,
        onConfirm: async () => {
            const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
            showToast(isAr ? 'جاري حذف العلامات المحددة...' : 'Deleting selected brands...', 'info');

            try {
                const { error } = await supabaseClient
                    .from('brands')
                    .delete()
                    .in('id', selectedIds)
                    .eq('tenant_id', tenantId);

                if (error) throw error;

                showToast(isAr ? '✨ تم حذف العلامات المحددة بنجاح' : 'Brands deleted successfully', 'success');
                clearSelectedBrands();
                loadBrandsData();
            } catch (err) {
                console.error('Error bulk deleting brands:', err);
                showToast(err.message, 'error');
            }
        }
    });
};

function getBrandsEmptyMessage() {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const searchVal = (document.getElementById('brandsSearchInput')?.value || '').trim();
    const statusVal = document.getElementById('brandsStatusFilter')?.value || 'all';

    if (searchVal) {
        return isAr ? 'لا توجد علامات تجارية مطابقة للبحث' : 'No brands matching your search';
    }

    if (statusVal === 'active') {
        return isAr ? 'لا توجد علامات تجارية نشطة حالياً' : 'No active brands found';
    }

    if (statusVal === 'hidden') {
        return isAr ? 'لا توجد علامات تجارية غير نشطة حالياً' : 'No inactive brands found';
    }

    return isAr ? 'لا توجد علامات تجارية مضافة حتى الآن' : 'No brands added yet';
}

function renderBrandsGrid(list) {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const gridWrapper = document.getElementById('brands-grid-wrapper');
    if (!gridWrapper) return;

    // Dark Mode enforced permanently
    const isLightMode = false;

    if (!list || list.length === 0) {
        const emptyMsg = getBrandsEmptyMessage();
        gridWrapper.innerHTML = `
            <div style="grid-column: 1 / -1; text-align: center; padding: 50px 20px; background: #22073e; border: 1px dashed var(--border-subtle); border-radius: 18px;">
                <i class="fas fa-copyright" style="font-size: 2.8rem; color: var(--text-muted); margin-bottom: 12px; display: block;"></i>
                <p style="color: var(--text-muted); font-size: 1rem; font-weight: 700;">${emptyMsg}</p>
            </div>
        `;
        return;
    }

    gridWrapper.innerHTML = list.map(item => {
        const isActive = item.is_active !== false;
        const isSelected = window.selectedBrandIds ? window.selectedBrandIds.has(String(item.id)) : false;

        // Dynamic Logo Selection (Dark Mode)
        const logoUrl = item.logo_url || item.logo_url_light || 'logo.png';

        const trashedIds = typeof getTrashedMenuItemIds === 'function' ? getTrashedMenuItemIds() : [];
        const brandProductsCount = (window.allMenuItemsData || []).filter(m => !trashedIds.includes(String(m.id)) && m.brand_id && String(m.brand_id) === String(item.id)).length;

        return `
            <div class="brand-card-item menu-card-item glass ${isSelected ? 'selected-card' : ''}" onclick="handleBrandCardClick(event, '${item.id}')" style="position: relative; border-radius: 18px; padding: 16px; display: flex; flex-direction: column; justify-content: space-between; transition: all 0.25s ease; ${isSelected ? 'border-color: var(--primary-gold) !important; background: rgba(212,175,55,0.06) !important;' : ''}">

                ${window.isBrandSelectionModeActive ? `
                    <label class="card-select-overlay" onclick="event.stopPropagation();" style="position: absolute; top: 10px; right: 10px; z-index: 10; cursor: pointer; display: flex; align-items: center; justify-content: center; background: transparent !important; border: none !important; box-shadow: none !important; backdrop-filter: none !important; padding: 0;">
                        <input type="checkbox" ${isSelected ? 'checked' : ''} onchange="toggleBrandSelection('${item.id}', this.checked)" style="width: 18px; height: 18px; accent-color: var(--primary-gold); cursor: pointer; margin: 0; box-shadow: none !important;">
                    </label>
                ` : ''}

                <!-- Brand Logo Frame -->
                <div style="width: 100%; height: 110px; border-radius: 14px; background: #2e0a54; border: 1px solid var(--border-subtle); display: flex; align-items: center; justify-content: center; overflow: hidden; margin-bottom: 12px; padding: 10px; box-sizing: border-box;">
                    <img src="${logoUrl}" alt="${item.name_ar || 'Brand'}" onerror="this.onerror=null; this.src='logo.png';" style="max-width: 92%; max-height: 92%; object-fit: contain;">
                </div>

                <!-- Brand Name Details (Single Line with Explanatory Header) -->
                <div style="text-align: center; margin-bottom: 12px; width: 100%;">
                    <span style="display: block; font-size: 0.73rem; font-weight: 700; color: var(--text-muted); margin-bottom: 4px;">
                        <i class="fas fa-tag" style="margin-inline-end: 3px; color: var(--primary-gold); font-size: 0.7rem;"></i>
                        ${isAr ? 'اسم العلامة التجارية' : 'Brand Name'}
                    </span>
                    <h4 style="margin: 0; font-weight: 800; font-size: 0.98rem; color: var(--text-main); line-height: 1.3; display: flex; align-items: center; justify-content: center; gap: 5px; flex-wrap: wrap;">
                        <span>${escapeHtml(item.name_ar || '---')}</span>
                        ${item.name_en ? `<span style="font-weight: 600; color: var(--text-muted); font-size: 0.84rem;">(${escapeHtml(item.name_en)})</span>` : ''}
                    </h4>
                    <div style="margin-top: 8px; display: flex; justify-content: center;">
                        <button type="button" onclick="event.stopPropagation(); viewBrandMenuItems('${item.id}')" title="${isAr ? 'عرض جميع المنتجات المرتبطة بهذه العلامة' : 'View products linked to this brand'}" style="background: rgba(217, 119, 6, 0.12); border: 1px solid rgba(217, 119, 6, 0.3); color: var(--primary-gold); padding: 4px 10px; border-radius: 999px; font-size: 0.75rem; font-weight: 800; cursor: pointer; display: inline-flex; align-items: center; gap: 5px; transition: all 0.2s;">
                            <i class="fas fa-boxes" style="font-size: 0.7rem;"></i>
                            <span>${brandProductsCount} ${isAr ? 'منتج مرتبط' : 'Products'}</span>
                        </button>
                    </div>
                </div>

                <!-- Footer Actions & Toggle Bar -->
                <div style="display: flex; align-items: center; justify-content: space-between; padding-top: 12px; border-top: 1px dashed var(--border-subtle); width: 100%;">
                    <!-- Native Products Page Status Toggle Button (Compact Size) -->
                    <button type="button" onclick="toggleBrandActive('${item.id}', ${isActive})" class="category-status-toggle-btn ${isActive ? 'active' : 'hidden'}" title="${isAr ? 'تغيير حالة التفعيل والظهور بالمتجر' : 'Toggle store active status'}" style="padding: 3px 8px !important; font-size: 0.65rem !important; height: 28px !important; min-height: 28px !important; gap: 4px !important;">
                        <span class="switch-track ${isActive ? 'active' : ''}"><span class="switch-knob"></span></span>
                        <span>${isAr ? (isActive ? 'نشط' : 'غير نشط') : (isActive ? 'Active' : 'Inactive')}</span>
                    </button>

                    <!-- Action Buttons with Descriptive Tooltips & Label -->
                    <div style="display: flex; gap: 6px; align-items: center;">
                        <button type="button" class="btn-action edit" onclick="openBrandModal('${item.id}')" title="${isAr ? 'تعديل بيانات العلامة التجارية وربط المنتجات' : 'Edit brand details & link products'}" style="height: 34px; padding: 0 10px; border-radius: 9px; background: #2e0a54; border: 1px solid var(--border-gray, rgba(203, 213, 225, 0.28)); color: #ffffff; display: inline-flex; align-items: center; justify-content: center; gap: 5px; cursor: pointer; transition: all 0.2s; font-weight: 700; font-size: 0.78rem;">
                            <i class="fas fa-pen" style="font-size: 0.78rem; color: var(--icon-purple, #eab308);"></i>
                            <span>${isAr ? 'تعديل' : 'Edit'}</span>
                        </button>
                        <button type="button" onclick="deleteBrand('${item.id}', '${(item.name_ar || '').replace(/'/g, "\\'")}')" title="${isAr ? 'حذف هذه العلامة التجارية' : 'Delete this brand'}" style="width: 34px; height: 34px; border-radius: 9px; background: rgba(239, 68, 68, 0.12); border: 1px solid rgba(239, 68, 68, 0.25); color: #ef4444; display: inline-flex; align-items: center; justify-content: center; cursor: pointer; transition: all 0.2s;">
                            <i class="fas fa-trash-alt" style="font-size: 0.82rem;"></i>
                        </button>
                    </div>
                </div>

            </div>
        `;
    }).join('');
}

function renderBrandsTable(list) {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tbody = document.getElementById('brands-full-body');
    if (!tbody) return;

    if (!list || list.length === 0) {
        const emptyMsg = getBrandsEmptyMessage();
        tbody.innerHTML = `
            <tr>
                <td colspan="5" style="text-align: center; padding: 40px;">
                    <i class="fas fa-copyright" style="font-size: 2.5rem; color: var(--text-muted); margin-bottom: 12px; display: block;"></i>
                    <p style="color: var(--text-muted); font-size: 0.95rem; font-weight: 600;">${emptyMsg}</p>
                </td>
            </tr>
        `;
        return;
    }

    tbody.innerHTML = list.map(item => {
        const isActive = item.is_active !== false;
        const isSelected = window.selectedBrandIds ? window.selectedBrandIds.has(String(item.id)) : false;
        const logoUrl = item.logo_url || item.logo_url_light || 'logo.png';

        return `
            <tr style="vertical-align: middle; ${isSelected ? 'background: rgba(212,175,55,0.08) !important;' : ''}">
                ${window.isBrandSelectionModeActive ? `
                    <td style="text-align: center; width: 40px; padding: 12px 4px;">
                        <input type="checkbox" ${isSelected ? 'checked' : ''} onchange="toggleBrandSelection('${item.id}', this.checked)" style="width: 18px; height: 18px; accent-color: var(--primary-gold); cursor: pointer;">
                    </td>
                ` : ''}
                <td style="text-align: center; padding: 12px 8px;">
                    <div style="width: 52px; height: 52px; border-radius: 12px; background: rgba(255,255,255,0.05); border: 1px solid var(--border-subtle); display: flex; align-items: center; justify-content: center; overflow: hidden; margin: 0 auto;">
                        <img src="${escapeHtml(logoUrl)}" alt="${escapeHtml(item.name_ar || 'Brand')}" onerror="this.onerror=null; this.src='logo.png';" style="max-width: 88%; max-height: 88%; object-fit: contain;">
                    </div>
                </td>
                <td style="text-align: right; vertical-align: middle;">
                    <div style="display: flex; flex-direction: column; justify-content: center;">
                        <span style="font-weight: 800; color: var(--text-main); font-size: 0.98rem;">
                            ${item.name_ar ? escapeHtml(item.name_ar) : '<span style="color:var(--text-muted);">-</span>'}
                            ${item.icon_class ? `<i class="${escapeHtml(String(item.icon_class).replace(/[^a-zA-Z0-9_\s-]/g, ''))}" style="margin-inline-start: 6px; color: var(--primary-gold);"></i>` : ''}
                        </span>
                        ${item.name_en ? `<span style="font-weight: 600; color: var(--text-muted); font-size: 0.82rem; margin-top: 2px;">${escapeHtml(item.name_en)}</span>` : ''}
                    </div>
                </td>
                <td style="text-align: center;">
                    <span style="display: inline-block; padding: 4px 12px; border-radius: 8px; background: rgba(255,255,255,0.05); border: 1px solid var(--border-subtle); font-weight: 800; font-family: monospace; font-size: 0.9rem;">
                        ${item.display_order ?? 1}
                    </span>
                </td>
                <td style="text-align: center;">
                    <div style="display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 5px 12px; border-radius: 20px; background: ${isActive ? 'rgba(16, 185, 129, 0.12)' : 'rgba(239, 68, 68, 0.12)'}; border: 1px solid ${isActive ? 'rgba(16, 185, 129, 0.28)' : 'rgba(239, 68, 68, 0.28)'};">
                        <span style="font-weight: 700; font-size: 0.84rem; color: ${isActive ? '#10b981' : '#ef4444'};">
                            ${isActive ? (isAr ? 'نشط' : 'Active') : (isAr ? 'غير نشط' : 'Inactive')}
                        </span>
                        <label class="switch-toggle" style="display: inline-flex; align-items: center; cursor: pointer; margin: 0;" title="${isAr ? 'تغيير حالة التفعيل' : 'Toggle active status'}">
                            <input type="checkbox" ${isActive ? 'checked' : ''} onchange="toggleBrandActive('${item.id}', ${isActive})">
                            <span class="toggle-slider"></span>
                        </label>
                    </div>
                </td>
                <td style="text-align: center;">
                    <div style="display: flex; gap: 8px; justify-content: center; align-items: center;">
                        <button type="button" class="btn-action edit" onclick="openBrandModal('${item.id}')" title="${isAr ? 'تعديل' : 'Edit'}" style="width: 36px; height: 36px; border-radius: 10px; background: #2e0a54; border: 1px solid var(--border-gray, rgba(203, 213, 225, 0.28)); color: #ffffff; display: inline-flex; align-items: center; justify-content: center; cursor: pointer; transition: all 0.2s;">
                            <i class="fas fa-pen" style="font-size: 0.88rem; color: var(--icon-purple, #eab308);"></i>
                        </button>
                        <button type="button" onclick="deleteBrand('${item.id}', '${(item.name_ar || '').replace(/'/g, "\\'")}')" title="${isAr ? 'حذف' : 'Delete'}" style="width: 36px; height: 36px; border-radius: 10px; background: rgba(239, 68, 68, 0.12); border: 1px solid rgba(239, 68, 68, 0.25); color: #ef4444; display: inline-flex; align-items: center; justify-content: center; cursor: pointer; transition: all 0.2s;">
                            <i class="fas fa-trash-alt" style="font-size: 0.88rem;"></i>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');
}

window.brandModalSelectedItemIds = new Set();
window.brandModalInitialItemIds = new Set();
window.brandModalProductsFilterMode = 'all';

window.updateBrandModalSelectedCountUI = function() {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const countEl = document.getElementById('brandModalSelectedProductsCount');
    const count = window.brandModalSelectedItemIds ? window.brandModalSelectedItemIds.size : 0;
    if (countEl) {
        countEl.textContent = isAr ? `${count} منتج محدد` : `${count} selected`;
    }
};

window.setBrandModalProductsFilter = function(mode) {
    window.brandModalProductsFilterMode = mode || 'all';
    ['all', 'selected', 'unassigned'].forEach(m => {
        const btn = document.getElementById('brandProdFilter_' + m);
        if (btn) {
            if (m === window.brandModalProductsFilterMode) {
                btn.style.background = 'var(--primary-gold)';
                btn.style.color = '#111827';
            } else {
                btn.style.background = 'rgba(255,255,255,0.06)';
                btn.style.color = 'var(--text-muted)';
            }
        }
    });
    window.renderBrandModalProductsList();
};

window.toggleBrandModalProductSelection = function(itemId) {
    if (!window.brandModalSelectedItemIds) window.brandModalSelectedItemIds = new Set();
    const strId = String(itemId);
    if (window.brandModalSelectedItemIds.has(strId)) {
        window.brandModalSelectedItemIds.delete(strId);
    } else {
        window.brandModalSelectedItemIds.add(strId);
    }
    window.updateBrandModalSelectedCountUI();
    window.renderBrandModalProductsList();
};

window.toggleBrandModalProductItem = function(itemId, isChecked) {
    if (!window.brandModalSelectedItemIds) window.brandModalSelectedItemIds = new Set();
    if (isChecked) {
        window.brandModalSelectedItemIds.add(String(itemId));
    } else {
        window.brandModalSelectedItemIds.delete(String(itemId));
    }
    window.updateBrandModalSelectedCountUI();
    window.renderBrandModalProductsList();
};

window.selectAllBrandModalProducts = function(selectAll) {
    if (!window.brandModalSelectedItemIds) window.brandModalSelectedItemIds = new Set();
    const visibleIds = window.currentBrandModalFilteredItemIds || [];
    if (selectAll) {
        visibleIds.forEach(id => window.brandModalSelectedItemIds.add(String(id)));
    } else {
        if (visibleIds.length > 0 && (document.getElementById('brandModalProductSearchInput')?.value || '').trim() !== '') {
            visibleIds.forEach(id => window.brandModalSelectedItemIds.delete(String(id)));
        } else {
            window.brandModalSelectedItemIds.clear();
        }
    }
    window.updateBrandModalSelectedCountUI();
    window.renderBrandModalProductsList();
};

window.renderBrandModalProductsList = function() {
    const container = document.getElementById('brandModalProductsListContainer');
    if (!container) return;
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const currentBrandId = (document.getElementById('brand_id')?.value || '').trim();
    const searchVal = (document.getElementById('brandModalProductSearchInput')?.value || '').trim().toLowerCase();
    const filterMode = window.brandModalProductsFilterMode || 'all';

    const trashedIds = typeof getTrashedMenuItemIds === 'function' ? getTrashedMenuItemIds() : [];
    const categories = window.allCategoriesData || [];
    const brands = window.allBrandsData || [];

    let items = (window.allMenuItemsData || []).filter(i => !trashedIds.includes(String(i.id)));

    if (filterMode === 'selected') {
        items = items.filter(i => window.brandModalSelectedItemIds && window.brandModalSelectedItemIds.has(String(i.id)));
    } else if (filterMode === 'unassigned') {
        items = items.filter(i => !i.brand_id || String(i.brand_id).trim() === '' || (currentBrandId && String(i.brand_id) === String(currentBrandId)));
    }

    if (searchVal) {
        items = items.filter(i => {
            const nameAr = (i.name_ar || '').toLowerCase();
            const nameEn = (i.name_en || '').toLowerCase();
            const cat = categories.find(c => String(c.id) === String(i.category_id));
            const catName = cat ? ((cat.name_ar || '') + ' ' + (cat.name_en || '')).toLowerCase() : '';
            return nameAr.includes(searchVal) || nameEn.includes(searchVal) || catName.includes(searchVal);
        });
    }

    // Sort: selected items first, then newest
    items.sort((a, b) => {
        const aSel = window.brandModalSelectedItemIds && window.brandModalSelectedItemIds.has(String(a.id)) ? 1 : 0;
        const bSel = window.brandModalSelectedItemIds && window.brandModalSelectedItemIds.has(String(b.id)) ? 1 : 0;
        if (aSel !== bSel) return bSel - aSel;
        return (a.name_ar || '').localeCompare(b.name_ar || '');
    });

    window.currentBrandModalFilteredItemIds = items.map(i => String(i.id));

    if (items.length === 0) {
        container.innerHTML = `
            <div style="text-align: center; padding: 24px 12px; color: var(--text-muted); font-size: 0.84rem;">
                <i class="fas fa-box-open" style="font-size: 1.5rem; color: var(--primary-gold); margin-bottom: 6px; display: block; opacity: 0.8;"></i>
                <span>${searchVal ? (isAr ? 'لا توجد منتجات تطابق بحثك' : 'No products match your search') : (isAr ? 'لا توجد منتجات في هذه القائمة' : 'No products in this list')}</span>
            </div>
        `;
        return;
    }

    const variantsList = window.allItemVariantsData || [];

    let cardsHtml = '<div class="brand-modal-products-grid">';
    items.forEach(item => {
        const itemId = String(item.id);
        const isSel = window.brandModalSelectedItemIds && window.brandModalSelectedItemIds.has(itemId);
        const name = isAr ? (item.name_ar || item.name_en || 'منتج بدون اسم') : (item.name_en || item.name_ar || 'Unnamed Product');
        const cat = categories.find(c => String(c.id) === String(item.category_id));
        const catName = cat ? (isAr ? cat.name_ar : (cat.name_en || cat.name_ar)) : '';
        const imgUrl = item.image_url || 'https://cdn.sahalacompany.com/placeholder.webp';

        // Check if item has sizes/variants
        const itemVars = variantsList.filter(v => String(v.item_id) === itemId);
        let variantBadgeHtml = '';
        if (itemVars.length > 0) {
            variantBadgeHtml = `
                <span class="brand-prod-var-pill" title="${itemVars.length} ${isAr ? 'مقاسات / خيارات' : 'options'}">
                    <i class="fas fa-ruler-combined"></i>
                    <span>${itemVars.length} ${isAr ? 'مقاسات' : 'sizes'}</span>
                </span>
            `;
        } else if (item.base_unit_ar || item.base_unit_en) {
            const unit = isAr ? (item.base_unit_ar || item.base_unit_en) : (item.base_unit_en || item.base_unit_ar);
            variantBadgeHtml = `
                <span class="brand-prod-var-pill" style="opacity:0.85;">
                    <i class="fas fa-box"></i>
                    <span>${unit}</span>
                </span>
            `;
        }

        const priceVal = (item.sale_price !== undefined && item.sale_price !== null && item.sale_price !== '') ? item.sale_price : (item.price || 0);

        cardsHtml += `
            <div class="brand-prod-quick-card ${isSel ? 'is-selected' : ''}" onclick="toggleBrandModalProductSelection('${itemId}')" title="${name}">
                <div class="card-check-badge">
                    <i class="fas ${isSel ? 'fa-check' : 'fa-plus'}"></i>
                </div>
                <div class="card-thumb-wrap">
                    <img src="${imgUrl}" onerror="this.src='https://cdn.sahalacompany.com/placeholder.webp'" alt="${name}" loading="lazy">
                </div>
                <div class="card-info-wrap">
                    <div class="card-prod-name">${name}</div>
                    ${variantBadgeHtml}
                    <div class="card-meta-row">
                        <span class="card-cat-name">${catName || '-'}</span>
                        <span class="card-price-text">${priceVal} <small>${isAr ? 'ر.س' : 'SAR'}</small></span>
                    </div>
                </div>
            </div>
        `;
    });
    cardsHtml += '</div>';

    container.innerHTML = cardsHtml;
};

window.openBrandModal = async function(brandId) {
    const modal = document.getElementById('brandModal');
    if (!modal) return;

    const form = document.getElementById('brandForm');
    if (form) form.reset();

    const title = document.getElementById('brandModalTitle');
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';

    if (brandId) {
        const brand = (window.allBrandsData || []).find(b => String(b.id) === String(brandId));
        if (brand) {
            if (title) title.innerText = isAr ? 'تعديل العلامة التجارية' : 'Edit Brand';
            document.getElementById('brand_id').value = brand.id || '';
            document.getElementById('brand_name_ar').value = brand.name_ar || '';
            document.getElementById('brand_name_en').value = brand.name_en || '';
            document.getElementById('brand_logo_url').value = brand.logo_url || '';
            document.getElementById('brand_logo_url_light').value = brand.logo_url_light || '';
            document.getElementById('brand_link_url').value = brand.link_url || '#';
            document.getElementById('brand_display_order').value = brand.display_order ?? 1;
            document.getElementById('brand_icon_class').value = brand.icon_class || '';
            document.getElementById('brand_is_active').checked = brand.is_active !== false;

            if (document.getElementById('brand_image_source_main')) document.getElementById('brand_image_source_main').value = brand.image_source || 'custom';
            if (document.getElementById('brand_image_hash_main')) document.getElementById('brand_image_hash_main').value = brand.image_hash || '';
            if (document.getElementById('brand_r2_key_main')) document.getElementById('brand_r2_key_main').value = brand.r2_key || '';

            if (document.getElementById('brand_image_source_light')) document.getElementById('brand_image_source_light').value = brand.image_source_light || 'custom';
            if (document.getElementById('brand_image_hash_light')) document.getElementById('brand_image_hash_light').value = brand.image_hash_light || '';
            if (document.getElementById('brand_r2_key_light')) document.getElementById('brand_r2_key_light').value = brand.r2_key_light || '';
        }
    } else {
        if (title) title.innerText = isAr ? 'إضافة علامة تجارية جديدة' : 'Add New Brand';
        document.getElementById('brand_id').value = '';
        document.getElementById('brand_link_url').value = '#';

        const maxOrder = (window.allBrandsData || []).reduce((max, b) => Math.max(max, b.display_order || 0), 0);
        document.getElementById('brand_display_order').value = maxOrder + 1;
        document.getElementById('brand_is_active').checked = true;

        if (document.getElementById('brand_image_source_main')) document.getElementById('brand_image_source_main').value = 'custom';
        if (document.getElementById('brand_image_hash_main')) document.getElementById('brand_image_hash_main').value = '';
        if (document.getElementById('brand_r2_key_main')) document.getElementById('brand_r2_key_main').value = '';

        if (document.getElementById('brand_image_source_light')) document.getElementById('brand_image_source_light').value = 'custom';
        if (document.getElementById('brand_image_hash_light')) document.getElementById('brand_image_hash_light').value = '';
        if (document.getElementById('brand_r2_key_light')) document.getElementById('brand_r2_key_light').value = '';
    }

    if (typeof updateBrandLogoPreview === 'function') {
        updateBrandLogoPreview('main');
        updateBrandLogoPreview('light');
    }

    // Ensure menu items and categories are loaded for the Brand Products selector
    if (!window.allMenuItemsData || window.allMenuItemsData.length === 0) {
        try {
            const [itemRes, catRes] = await Promise.all([
                supabaseClient.from('menu_items').select('*').eq('tenant_id', tenantId).order('created_at', { ascending: false }),
                supabaseClient.from('categories').select('*').eq('tenant_id', tenantId)
            ]);
            if (itemRes.data && typeof mergeMenuItemsWithLocal === 'function') {
                window.allMenuItemsData = mergeMenuItemsWithLocal(tenantId, itemRes.data);
            }
            if (catRes.data && typeof mergeCategoriesWithLocal === 'function') {
                window.allCategoriesData = mergeCategoriesWithLocal(tenantId, catRes.data);
            }
        } catch (err) {
            console.warn('Error loading menu items for brand modal:', err);
        }
    }

    const searchInp = document.getElementById('brandModalProductSearchInput');
    if (searchInp) searchInp.value = '';

    const linkedIds = brandId
        ? (window.allMenuItemsData || []).filter(i => i.brand_id && String(i.brand_id) === String(brandId)).map(i => String(i.id))
        : [];
    window.brandModalInitialItemIds = new Set(linkedIds);
    window.brandModalSelectedItemIds = new Set(linkedIds);
    window.updateBrandModalSelectedCountUI();
    window.setBrandModalProductsFilter('all');

    modal.classList.add('show');
    modal.classList.add('active');
    modal.style.display = 'flex';
};

window.handleBrandLogoBtnClick = async function(e, type) {
    if (e) {
        e.preventDefault();
        e.stopPropagation();
    }
    const urlInput = document.getElementById(type === 'main' ? 'brand_logo_url' : 'brand_logo_url_light');
    const fileInput = document.getElementById(type === 'main' ? 'brand_logo_file_main' : 'brand_logo_file_light');
    const sourceInput = document.getElementById(type === 'main' ? 'brand_image_source_main' : 'brand_image_source_light');
    const hashInput = document.getElementById(type === 'main' ? 'brand_image_hash_main' : 'brand_image_hash_light');
    const r2KeyInput = document.getElementById(type === 'main' ? 'brand_r2_key_main' : 'brand_r2_key_light');
    const brandId = document.getElementById('brand_id')?.value || null;

    if (urlInput && urlInput.value.trim()) {
        const oldUrl = urlInput.value.trim();
        const oldSource = sourceInput?.value || 'custom';
        const oldR2Key = r2KeyInput?.value || '';

        // Real-time deletion from Cloudflare R2
        if (typeof window.deleteSectionImageSmart === 'function') {
            await window.deleteSectionImageSmart(oldUrl, oldSource, oldR2Key, brandId);
        }

        urlInput.value = '';
        if (sourceInput) sourceInput.value = 'custom';
        if (hashInput) hashInput.value = '';
        if (r2KeyInput) r2KeyInput.value = '';
        if (fileInput) fileInput.value = '';
        updateBrandLogoPreview(type);
    } else {
        if (fileInput) fileInput.click();
    }
};

window.updateBrandLogoPreview = function(type) {
    const urlInput = document.getElementById(type === 'main' ? 'brand_logo_url' : 'brand_logo_url_light');
    const previewBox = document.getElementById(type === 'main' ? 'brand_logo_preview_main' : 'brand_logo_preview_light');
    const imgEl = document.getElementById(type === 'main' ? 'brand_logo_img_main' : 'brand_logo_img_light');
    const iconEl = document.getElementById(type === 'main' ? 'brand_logo_icon_main' : 'brand_logo_icon_light');
    const textEl = document.getElementById(type === 'main' ? 'brand_logo_text_main' : 'brand_logo_text_light');
    const btnEl = document.getElementById(type === 'main' ? 'brand_logo_btn_main' : 'brand_logo_btn_light');
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';

    if (urlInput && previewBox && imgEl) {
        const val = urlInput.value.trim();
        if (val) {
            imgEl.src = val;
            previewBox.style.display = 'flex';
            if (iconEl) {
                iconEl.className = 'fas fa-trash-alt';
                iconEl.style.color = '#ef4444';
            }
            if (textEl) {
                textEl.setAttribute('data-ar', 'حذف');
                textEl.setAttribute('data-en', 'Delete');
                textEl.textContent = isAr ? 'حذف' : 'Delete';
            }
            if (btnEl) {
                btnEl.title = isAr ? 'حذف الصورة' : 'Remove Image';
            }
        } else {
            previewBox.style.display = 'none';
            imgEl.src = '';
            if (iconEl) {
                iconEl.className = 'fas fa-upload';
                iconEl.style.color = 'var(--primary-gold)';
            }
            if (textEl) {
                textEl.setAttribute('data-ar', 'رفع');
                textEl.setAttribute('data-en', 'Upload');
                textEl.textContent = isAr ? 'رفع' : 'Upload';
            }
            if (btnEl) {
                btnEl.title = isAr ? 'رفع صورة من الجهاز' : 'Upload image';
            }
        }
    }
};

window.handleBrandLogoUpload = async function(e, type) {
    const file = e.target.files[0];
    if (!file) return;
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const clientDomain = (typeof window.getActiveClientDomain === 'function') ? window.getActiveClientDomain() : tenantId;

    showToast(isAr ? "جاري ضغط ورفع الشعار بدقة متناهية..." : "Compressing and uploading logo...", "info");
    try {
        // 1. WebP compression (0.5 quality)
        const webpBlob = typeof convertToWebP === 'function' ? await convertToWebP(file, 0.5) : file;
        // 2. SHA-256 hash
        const compressedHash = typeof computeBlobSHA256 === 'function' ? await computeBlobSHA256(webpBlob) : '';
        // 3. Unique filename
        const fileName = `brand-${type}-${tenantId}-${Date.now()}.webp`;

        let publicUrl = '';
        let r2Key = '';

        try {
            const base64Data = typeof blobToBase64 === 'function' ? await blobToBase64(webpBlob) : '';
            if (base64Data) {
                const r2Res = await fetch('/api/r2/upload', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        base64Data,
                        fileName,
                        tenantId,
                        clientDomain,
                        target: 'brand',
                        contentType: 'image/webp'
                    })
                });
                const r2Data = await r2Res.json();
                if (r2Res.ok && r2Data && r2Data.success && r2Data.publicUrl) {
                    publicUrl = r2Data.publicUrl;
                    r2Key = r2Data.r2Key || '';
                } else if (r2Data && r2Data.r2Key) {
                    r2Key = r2Data.r2Key;
                }
            }
        } catch (r2Err) {
            console.warn('R2 upload endpoint note, using fallback:', r2Err);
        }

        // Fallback to Supabase Storage if R2 failed
        if (!publicUrl) {
            const { error: upErr } = await supabaseClient.storage.from('images').upload(fileName, webpBlob, { contentType: 'image/webp' });
            if (upErr) throw upErr;
            const { data: { publicUrl: sbUrl } } = supabaseClient.storage.from('images').getPublicUrl(fileName);
            publicUrl = sbUrl;
            if (!r2Key) r2Key = fileName;
        }

        if (type === 'main') {
            document.getElementById('brand_logo_url').value = publicUrl;
            if (document.getElementById('brand_image_source_main')) document.getElementById('brand_image_source_main').value = 'custom';
            if (document.getElementById('brand_image_hash_main')) document.getElementById('brand_image_hash_main').value = compressedHash;
            if (document.getElementById('brand_r2_key_main')) document.getElementById('brand_r2_key_main').value = r2Key;
            updateBrandLogoPreview('main');
        } else {
            document.getElementById('brand_logo_url_light').value = publicUrl;
            if (document.getElementById('brand_image_source_light')) document.getElementById('brand_image_source_light').value = 'custom';
            if (document.getElementById('brand_image_hash_light')) document.getElementById('brand_image_hash_light').value = compressedHash;
            if (document.getElementById('brand_r2_key_light')) document.getElementById('brand_r2_key_light').value = r2Key;
            updateBrandLogoPreview('light');
        }
        showToast(isAr ? "✨ تم رفع الشعار بنجاح" : "Logo uploaded successfully", "success");
    } catch (err) {
        console.error('Error uploading logo:', err);
        showToast(err.message || 'Upload failed', "error");
    }
};

window.closeBrandModal = function() {
    const modal = document.getElementById('brandModal');
    if (modal) {
        modal.classList.remove('show');
        modal.classList.remove('active');
        modal.style.display = 'none';
    }
};

window.handleSaveBrand = async function(e) {
    if (e) e.preventDefault();
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const btnSave = document.getElementById('btnSaveBrand');

    const brandId = document.getElementById('brand_id').value.trim();
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const clientDomain = (typeof window.getActiveClientDomain === 'function') ? window.getActiveClientDomain() : tenantId;

    const currentLogoMain = document.getElementById('brand_logo_url').value.trim();
    const currentLogoLight = document.getElementById('brand_logo_url_light').value.trim();

    // If editing and logos changed, delete old images from R2
    if (brandId) {
        const oldBrand = (window.allBrandsData || []).find(b => String(b.id) === String(brandId));
        if (oldBrand) {
            if (oldBrand.logo_url && oldBrand.logo_url !== currentLogoMain) {
                if (typeof window.deleteSectionImageSmart === 'function') {
                    await window.deleteSectionImageSmart(oldBrand.logo_url, oldBrand.image_source || 'custom', oldBrand.r2_key || '', brandId);
                }
            }
            if (oldBrand.logo_url_light && oldBrand.logo_url_light !== currentLogoLight) {
                if (typeof window.deleteSectionImageSmart === 'function') {
                    await window.deleteSectionImageSmart(oldBrand.logo_url_light, oldBrand.image_source_light || 'custom', oldBrand.r2_key_light || '', brandId);
                }
            }
        }
    }

    const basePayload = {
        tenant_id: tenantId,
        name_ar: document.getElementById('brand_name_ar').value.trim(),
        name_en: document.getElementById('brand_name_en').value.trim(),
        logo_url: currentLogoMain,
        logo_url_light: currentLogoLight,
        link_url: document.getElementById('brand_link_url').value.trim() || '#',
        display_order: parseInt(document.getElementById('brand_display_order').value) || 1,
        icon_class: document.getElementById('brand_icon_class').value.trim(),
        is_active: document.getElementById('brand_is_active').checked,
        updated_at: new Date().toISOString()
    };

    const extendedPayload = {
        ...basePayload,
        client_domain: clientDomain,
        r2_key: document.getElementById('brand_r2_key_main')?.value || null,
        image_hash: document.getElementById('brand_image_hash_main')?.value || null,
        image_source: document.getElementById('brand_image_source_main')?.value || 'custom',
        r2_key_light: document.getElementById('brand_r2_key_light')?.value || null,
        image_hash_light: document.getElementById('brand_image_hash_light')?.value || null,
        image_source_light: document.getElementById('brand_image_source_light')?.value || 'custom'
    };

    if (!basePayload.name_ar) {
        showToast(isAr ? 'يرجى إدخال اسم العلامة التجارية بالعربية' : 'Please enter Arabic brand name', 'warning');
        return;
    }

    if (!basePayload.logo_url) {
        showToast(isAr ? 'يرجى إدخال رابط صورة الشعار الأساسي' : 'Please enter logo URL', 'warning');
        return;
    }

    try {
        if (btnSave) btnSave.disabled = true;
        showToast(isAr ? 'جاري حفظ بيانات العلامة التجارية...' : 'Saving brand...', 'info');

        let res;
        if (brandId) {
            res = await window.supabaseWriteRow('brands', 'update', extendedPayload, brandId, tenantId);
            if (res.error && (res.error.code === '42703' || (res.error.message && res.error.message.includes('column')))) {
                res = await window.supabaseWriteRow('brands', 'update', basePayload, brandId, tenantId);
            }
        } else {
            res = await window.supabaseWriteRow('brands', 'insert', extendedPayload, null, tenantId);
            if (res.error && (res.error.code === '42703' || (res.error.message && res.error.message.includes('column')))) {
                res = await window.supabaseWriteRow('brands', 'insert', basePayload, null, tenantId);
            }
        }

        let finalBrandId = brandId;
        const returnedRow = (res && Array.isArray(res.data) && res.data[0]) ? res.data[0] : null;
        const existingBrand = brandId ? ((window.allBrandsData || []).find(b => String(b.id) === String(brandId)) || {}) : {};
        finalBrandId = (returnedRow && returnedRow.id) ? returnedRow.id : (brandId || generateFallbackUUID());
        const syncedBrand = returnedRow || {
            ...existingBrand,
            id: finalBrandId,
            created_at: existingBrand.created_at || new Date().toISOString(),
            ...extendedPayload
        };

        if (returnedRow && returnedRow.id) {
            clearLocalBrandOverride(tenantId, returnedRow.id);
        } else {
            saveLocalBrandOverride(tenantId, syncedBrand);
        }

        // Sync linked/unlinked products for this brand (update all selected products so DB is 100% consistent)
        if (finalBrandId) {
            const selectedSet = window.brandModalSelectedItemIds || new Set();
            const initialSet = window.brandModalInitialItemIds || new Set();

            const allSelectedIds = Array.from(selectedSet);
            const toUnlinkIds = Array.from(initialSet).filter(id => !selectedSet.has(String(id)));

            const brandObj = (window.allBrandsData || []).find(b => String(b.id) === String(finalBrandId));
            const bNameAr = brandObj ? (brandObj.name_ar || basePayload.name_ar) : basePayload.name_ar;
            const bNameEn = brandObj ? (brandObj.name_en || basePayload.name_en) : (basePayload.name_en || basePayload.name_ar);

            if (allSelectedIds.length > 0) {
                try {
                    await window.supabaseWriteBatch('menu_items', {
                        brand_id: finalBrandId,
                        badge_ar: bNameAr,
                        badge_en: bNameEn
                    }, 'id', allSelectedIds, tenantId);
                } catch (linkErr) {
                    console.warn('Supabase link brand_id note:', linkErr);
                }
                allSelectedIds.forEach(itemId => {
                    const itemObj = (window.allMenuItemsData || []).find(i => String(i.id) === String(itemId));
                    if (itemObj) {
                        itemObj.brand_id = finalBrandId;
                        itemObj.badge_ar = bNameAr;
                        itemObj.badge_en = bNameEn;
                        clearLocalMenuItemOverride(tenantId, itemId);
                    }
                });
            }

            if (toUnlinkIds.length > 0) {
                try {
                    await window.supabaseWriteBatch('menu_items', {
                        brand_id: null,
                        badge_ar: null,
                        badge_en: null
                    }, 'id', toUnlinkIds, tenantId);
                } catch (unlinkErr) {
                    console.warn('Supabase unlink brand_id note:', unlinkErr);
                }
                toUnlinkIds.forEach(itemId => {
                    const itemObj = (window.allMenuItemsData || []).find(i => String(i.id) === String(itemId));
                    if (itemObj) {
                        itemObj.brand_id = null;
                        itemObj.badge_ar = null;
                        itemObj.badge_en = null;
                        clearLocalMenuItemOverride(tenantId, itemId);
                    }
                });
            }
        }

        showToast(isAr ? '✨ تم حفظ العلامة التجارية وربط المنتجات في قاعدة البيانات بنجاح' : 'Brand and linked products saved to database', 'success');
        closeBrandModal();
        await loadBrandsData(true);
    } catch (err) {
        console.error('Error saving brand:', err);
        showToast(isAr ? `فشل الحفظ: ${err.message}` : `Save failed: ${err.message}`, 'error');
    } finally {
        if (btnSave) btnSave.disabled = false;
    }
};

window.toggleBrandActive = async function(brandId, currentStatus) {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const newStatus = !currentStatus;

    try {
        showToast(isAr ? 'جاري تحديث حالة العلامة التجارية...' : 'Updating status...', 'info');

        const res = await window.supabaseWriteRow('brands', 'update', { is_active: newStatus, updated_at: new Date().toISOString() }, brandId, tenantId);

        const brand = (window.allBrandsData || []).find(b => String(b.id) === String(brandId));
        if (brand) {
            brand.is_active = newStatus;
            if (res && res.data && res.data[0]) {
                clearLocalBrandOverride(tenantId, brandId);
            } else {
                saveLocalBrandOverride(tenantId, brand);
            }
        }

        showToast(isAr ? (newStatus ? '✨ تم تفعيل العلامة التجارية' : '👁️ تم إخفاء العلامة التجارية') : 'Status updated', 'success');
        await loadBrandsData(true);
    } catch (err) {
        console.error('Error toggling brand status:', err);
        showToast(err.message, 'error');
    }
};

window.deleteBrand = function(brandId, brandName) {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';

    openConfirm({
        title: isAr ? 'تأكيد الحذف' : 'Confirm Delete',
        text: isAr ? `هل أنت متأكد من حذف العلامة التجارية "${brandName}"؟` : `Are you sure you want to delete "${brandName}"?`,
        onConfirm: async () => {
            try {
                showToast(isAr ? 'جاري حذف العلامة التجارية والصور...' : 'Deleting brand and images...', 'info');

                // Delete images from R2
                const brand = (window.allBrandsData || []).find(b => String(b.id) === String(brandId));
                if (brand) {
                    if (brand.logo_url && typeof window.deleteSectionImageSmart === 'function') {
                        await window.deleteSectionImageSmart(brand.logo_url, brand.image_source || 'custom', brand.r2_key || '', brandId);
                    }
                    if (brand.logo_url_light && typeof window.deleteSectionImageSmart === 'function') {
                        await window.deleteSectionImageSmart(brand.logo_url_light, brand.image_source_light || 'custom', brand.r2_key_light || '', brandId);
                    }
                }

                await window.supabaseWriteRow('brands', 'delete', null, brandId, tenantId);
                clearLocalBrandOverride(tenantId, brandId);

                showToast(isAr ? '🗑️ تم حذف العلامة التجارية بنجاح' : 'Brand deleted', 'success');
                await loadBrandsData(true);
            } catch (err) {
                console.error('Error deleting brand:', err);
                showToast(err.message, 'error');
            }
        }
    });
};

/* ==========================================================================
   Announcements / Hero Banners Slider Management
   ========================================================================== */
if (!window.selectedAnnouncementIds) window.selectedAnnouncementIds = new Set();

async function loadAnnouncementsData(forceRefresh = false) {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const gridWrapper = document.getElementById('announcements-grid-wrapper');
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';

    if (forceRefresh && typeof window.clearTenantStaleLocalOverrides === 'function') {
        window.clearTenantStaleLocalOverrides(tenantId, 'announcements');
    }

    const hasPreCachedAnns = !forceRefresh && Array.isArray(window.allAnnouncementsData) && window.allAnnouncementsData.length > 0;

    if (hasPreCachedAnns) {
        const total = window.allAnnouncementsData.length;
        const active = window.allAnnouncementsData.filter(a => a.is_active !== false).length;
        const hidden = total - active;
        if (document.getElementById('kpi-announcements-total')) document.getElementById('kpi-announcements-total').innerText = total;
        if (document.getElementById('kpi-announcements-active')) document.getElementById('kpi-announcements-active').innerText = active;
        if (document.getElementById('kpi-announcements-hidden')) document.getElementById('kpi-announcements-hidden').innerText = hidden;
        filterAnnouncementsTable();
    } else if (gridWrapper) {
        gridWrapper.innerHTML = renderShimmerCards(6);
    }

    try {
        let { data, error } = await supabaseClient
            .from('announcements')
            .select('*')
            .eq('tenant_id', tenantId)
            .order('created_at', { ascending: false });

        if (error) {
            console.warn('Supabase fetch announcements note:', error.message);
            const retry = await supabaseClient
                .from('announcements')
                .select('*')
                .eq('tenant_id', tenantId);
            if (retry.data) data = retry.data;
        }

        window.allAnnouncementsData = mergeAnnouncementsWithLocal(tenantId, data || []);

        // Update KPI Counters
        const total = window.allAnnouncementsData.length;
        const active = window.allAnnouncementsData.filter(a => a.is_active !== false).length;
        const hidden = total - active;

        const kpiTotal = document.getElementById('kpi-announcements-total');
        const kpiActive = document.getElementById('kpi-announcements-active');
        const kpiHidden = document.getElementById('kpi-announcements-hidden');

        if (kpiTotal) kpiTotal.innerText = total;
        if (kpiActive) kpiActive.innerText = active;
        if (kpiHidden) kpiHidden.innerText = hidden;

        filterAnnouncementsTable();

        if (typeof makeCustomDropdown === 'function') {
            makeCustomDropdown('announcementsStatusFilter');
            makeCustomDropdown('announcementsSortFilter');
        }
        if (window.sectionLoadedState) window.sectionLoadedState['announcements'] = true;
    } catch (err) {
        console.error('Error loading announcements:', err);
        window.allAnnouncementsData = mergeAnnouncementsWithLocal(tenantId, []);
        filterAnnouncementsTable();
        if (gridWrapper && window.allAnnouncementsData.length === 0) {
            gridWrapper.innerHTML = `
                <div style="grid-column: 1 / -1; text-align: center; padding: 30px; color: #ef4444;">
                    <i class="fas fa-exclamation-triangle fa-2x" style="margin-bottom:8px;"></i>
                    <p>${isAr ? 'فشل جلب الإعلانات' : 'Failed to load announcements'}: ${err.message}</p>
                </div>
            `;
        }
    }
}

window.loadAnnouncementsData = loadAnnouncementsData;

window.refreshAnnouncementsData = async function(btn) {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    if (btn) {
        const icon = btn.querySelector('i');
        if (icon) icon.classList.add('fa-spin');
        setTimeout(() => icon?.classList.remove('fa-spin'), 1000);
    }
    if (typeof window.clearTenantStaleLocalOverrides === 'function') {
        window.clearTenantStaleLocalOverrides(tenantId, 'announcements');
    }
    await loadAnnouncementsData(true);
    showToast(isAr ? '✨ تم تحديث إعلانات السلايدر من قاعدة البيانات' : 'Slider announcements refreshed from database', 'success');
};

window.filterAnnouncementsByKpi = function(filterType) {
    const statusSelect = document.getElementById('announcementsStatusFilter');
    if (statusSelect) {
        statusSelect.value = filterType === 'active' ? 'active' : (filterType === 'hidden' ? 'hidden' : 'all');
        if (typeof makeCustomDropdown === 'function') {
            makeCustomDropdown('announcementsStatusFilter', true);
        }
    }
    filterAnnouncementsTable();
};

window.filterAnnouncementsTable = function() {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';

    const searchVal = (document.getElementById('announcementsSearchInput')?.value || '').toLowerCase().trim();
    const statusVal = document.getElementById('announcementsStatusFilter')?.value || 'all';
    const sortVal = document.getElementById('announcementsSortFilter')?.value || 'order';

    let list = [...(window.allAnnouncementsData || [])];

    // Search filter
    if (searchVal) {
        list = list.filter(a =>
            (a.text_ar && a.text_ar.toLowerCase().includes(searchVal)) ||
            (a.text_en && a.text_en.toLowerCase().includes(searchVal)) ||
            (a.subtitle_ar && a.subtitle_ar.toLowerCase().includes(searchVal)) ||
            (a.code && a.code.toLowerCase().includes(searchVal))
        );
    }

    // Status filter
    if (statusVal === 'active') {
        list = list.filter(a => a.is_active !== false);
    } else if (statusVal === 'hidden') {
        list = list.filter(a => a.is_active === false);
    }

    // Sort
    if (sortVal === 'order') {
        list.sort((a, b) => (a.display_order || 0) - (b.display_order || 0));
    } else if (sortVal === 'newest') {
        list.sort((a, b) => new Date(b.created_at || 0) - new Date(a.created_at || 0));
    } else if (sortVal === 'name') {
        list.sort((a, b) => (a.text_ar || '').localeCompare(b.text_ar || ''));
    }

    window.currentFilteredAnnouncementsData = list;
    updateAnnouncementsBulkBarUI(isAr);
    renderAnnouncementsGrid(list);
};

function getAnnouncementsEmptyMessage() {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const searchVal = (document.getElementById('announcementsSearchInput')?.value || '').trim();
    const statusVal = document.getElementById('announcementsStatusFilter')?.value || 'all';

    if (searchVal) {
        return isAr ? 'لا توجد إعلانات مطابقة للبحث' : 'No announcements matching search';
    }
    if (statusVal === 'active') {
        return isAr ? 'لا توجد إعلانات نشطة حالياً' : 'No active slides found';
    }
    if (statusVal === 'hidden') {
        return isAr ? 'لا توجد إعلانات معطلة حالياً' : 'No inactive slides found';
    }
    return isAr ? 'لا توجد إعلانات مضافة بالسلايدر حتى الآن' : 'No slider banners added yet';
}

function renderAnnouncementsGrid(list) {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const gridWrapper = document.getElementById('announcements-grid-wrapper');
    if (!gridWrapper) return;

    if (!list || list.length === 0) {
        const emptyMsg = getAnnouncementsEmptyMessage();
        gridWrapper.innerHTML = `
            <div style="grid-column: 1 / -1; text-align: center; padding: 50px 20px; background: rgba(255,255,255,0.02); border: 1px dashed var(--border-subtle); border-radius: 18px;">
                <i class="fas fa-sliders-h" style="font-size: 2.8rem; color: var(--text-muted); margin-bottom: 12px; display: block;"></i>
                <p style="color: var(--text-muted); font-size: 1rem; font-weight: 700;">${emptyMsg}</p>
            </div>
        `;
        return;
    }

    gridWrapper.innerHTML = list.map(item => {
        const isActive = item.is_active !== false;
        const isSelected = window.selectedAnnouncementIds ? window.selectedAnnouncementIds.has(String(item.id)) : false;
        const bgImg = item.image_url || 'https://cdn.sahalacompany.com/placeholder.webp';
        const titleText = escapeHtml(isAr ? (item.text_ar || item.title_ar || '---') : (item.text_en || item.title_en || item.text_ar || item.title_ar || '---'));
        const subtitleText = escapeHtml(isAr ? (item.subtitle_ar || '') : (item.subtitle_en || item.subtitle_ar || ''));
        const badgeText = escapeHtml(isAr ? (item.badge_text_ar || '') : (item.badge_text_en || item.badge_text_ar || ''));
        const promoCode = escapeHtml(item.code || '');

        return `
            <div class="announcement-card-item ${isSelected ? 'selected-card' : ''}" onclick="handleAnnouncementCardClick(event, '${item.id}')" style="${isSelected ? 'border-color: var(--primary-gold) !important; background: rgba(212,175,55,0.08) !important;' : ''}">

                ${window.isAnnouncementSelectionModeActive ? `
                    <label class="card-select-overlay" onclick="event.stopPropagation();" style="position: absolute; top: 10px; right: 10px; z-index: 10; cursor: pointer; display: flex; align-items: center; justify-content: center;">
                        <input type="checkbox" ${isSelected ? 'checked' : ''} onchange="toggleAnnouncementSelection('${item.id}', this.checked)" style="width: 18px; height: 18px; accent-color: var(--primary-gold); cursor: pointer; margin: 0;">
                    </label>
                ` : ''}

                <!-- Hero Banner Slide Preview Frame -->
                <div class="hero-banner-preview-box" style="display: flex; flex-direction: column; justify-content: space-between; padding: 14px; box-sizing: border-box;">
                    <!-- Real Image Element with Fallback -->
                    <img src="${bgImg}" onerror="this.src='https://cdn.sahalacompany.com/placeholder.webp'" class="hero-banner-img" alt="${titleText}">

                    <!-- Dark Gradient Overlay for Readability -->
                    <div class="hero-banner-overlay"></div>

                    <!-- Top Bar: Order & Badge Tag -->
                    <div style="position: relative; z-index: 2; display: flex; justify-content: space-between; align-items: center; width: 100%;">
                        <span style="font-size: 0.72rem; font-weight: 800; font-family: monospace; padding: 2px 8px; border-radius: 12px; background: rgba(0,0,0,0.55); backdrop-filter: blur(4px); border: 1px solid rgba(255,255,255,0.25); color: #ffffff;">
                            #${item.display_order ?? 1}
                        </span>
                        ${badgeText ? `
                            <span style="font-size: 0.72rem; font-weight: 800; padding: 3px 10px; border-radius: 20px; background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%); color: #ffffff; box-shadow: 0 2px 8px rgba(239, 68, 68, 0.4);">
                                ${badgeText}
                            </span>
                        ` : ''}
                    </div>

                    <!-- Middle Content: Title & Subtitle -->
                    <div style="position: relative; z-index: 2; text-align: center; color: #ffffff;">
                        <h4 style="margin: 0 0 4px 0; font-size: 0.98rem; font-weight: 800; text-shadow: 0 2px 6px rgba(0,0,0,0.9); line-height: 1.3; color: #ffffff;">
                            ⚡ ${titleText}
                        </h4>
                        ${subtitleText ? `
                            <p style="margin: 0; font-size: 0.76rem; color: rgba(255,255,255,0.9); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; text-shadow: 0 1px 3px rgba(0,0,0,0.9);">
                                ${subtitleText}
                            </p>
                        ` : ''}
                    </div>

                    <!-- Bottom Bar: Promo Code Box -->
                    <div style="position: relative; z-index: 2; text-align: center;">
                        ${promoCode ? `
                            <span style="display: inline-block; font-size: 0.72rem; font-weight: 800; padding: 2px 10px; border-radius: 8px; background: rgba(0,0,0,0.65); border: 1px dashed #ef4444; color: #ffffff; letter-spacing: 0.5px;">
                                🎟️ ${isAr ? 'كود الخصم' : 'Code'}: ${promoCode}
                            </span>
                        ` : ''}
                    </div>
                </div>

                <!-- Footer Actions & Toggle Bar -->
                <div style="padding: 12px 14px; display: flex; align-items: center; justify-content: space-between; gap: 6px; width: 100%; box-sizing: border-box; background: rgba(255,255,255,0.02); border-top: 1px solid var(--border-subtle, rgba(255,255,255,0.08)); border-bottom-left-radius: 19px; border-bottom-right-radius: 19px;">
                    <!-- Status Toggle Switch -->
                    <button type="button" onclick="toggleAnnouncementActive('${item.id}', ${isActive})" class="category-status-toggle-btn ${isActive ? 'active' : 'hidden'}" title="${isAr ? 'تغيير حالة تفعيل الإعلان بالسلايدر' : 'Toggle active status'}" style="padding: 2px 6px !important; font-size: 0.68rem !important; height: 30px !important; min-height: 30px !important; gap: 4px !important; flex-shrink: 0; border-radius: 8px !important;">
                        <span class="switch-track ${isActive ? 'active' : ''}"><span class="switch-knob"></span></span>
                        <span>${isAr ? (isActive ? 'نشط' : 'معطل') : (isActive ? 'Active' : 'Inactive')}</span>
                    </button>

                    <!-- Action Buttons -->
                    <div style="display: flex; gap: 4px; align-items: center; flex-wrap: nowrap;">
                        <button type="button" onclick="openAnnouncementModal('${item.id}')" class="btn-action edit" title="${isAr ? 'تعديل بيانات الشريحة الإعلانية' : 'Edit slide'}" style="width: auto !important; height: 30px !important; padding: 0 8px !important; border-radius: 8px !important; display: inline-flex !important; align-items: center !important; gap: 3px !important; font-weight: 700 !important; font-size: 0.70rem !important; white-space: nowrap !important; flex-shrink: 0;">
                            <i class="fas fa-pen" style="font-size: 0.70rem;"></i>
                            <span>${isAr ? 'تعديل' : 'Edit'}</span>
                        </button>
                        <button type="button" onclick="deleteAnnouncement('${item.id}', '${titleText.replace(/'/g, "\\'")}')" class="btn-action delete" title="${isAr ? 'حذف هذه الشريحة' : 'Delete slide'}" style="width: auto !important; height: 30px !important; padding: 0 8px !important; border-radius: 8px !important; display: inline-flex !important; align-items: center !important; gap: 3px !important; font-weight: 700 !important; font-size: 0.70rem !important; white-space: nowrap !important; flex-shrink: 0;">
                            <i class="fas fa-trash-alt" style="font-size: 0.70rem;"></i>
                            <span>${isAr ? 'حذف' : 'Delete'}</span>
                        </button>
                    </div>
                </div>

            </div>
        `;
    }).join('');
}

window.openAnnouncementModal = function(announcementId) {
    const modal = document.getElementById('announcementModal');
    const title = document.getElementById('announcementModalTitle');
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';

    if (!modal) return;

    // Reset Form
    document.getElementById('announcementForm')?.reset();
    document.getElementById('announcement_id').value = '';

    if (announcementId) {
        if (title) title.innerText = isAr ? 'تعديل الشريحة الإعلانية' : 'Edit Slider Banner';
        const item = (window.allAnnouncementsData || []).find(a => String(a.id) === String(announcementId));
        if (item) {
            document.getElementById('announcement_id').value = item.id;
            document.getElementById('announcement_text_ar').value = item.text_ar || item.title_ar || '';
            document.getElementById('announcement_text_en').value = item.text_en || item.title_en || '';
            document.getElementById('announcement_subtitle_ar').value = item.subtitle_ar || '';
            document.getElementById('announcement_subtitle_en').value = item.subtitle_en || '';
            document.getElementById('announcement_badge_text_ar').value = item.badge_text_ar || '';
            document.getElementById('announcement_code').value = item.code || '';
            document.getElementById('announcement_image_url').value = item.image_url || '';
            document.getElementById('announcement_display_order').value = item.display_order ?? 1;
            document.getElementById('announcement_is_active').checked = item.is_active !== false;

            if (document.getElementById('announcement_image_source')) document.getElementById('announcement_image_source').value = item.image_source || 'custom';
            if (document.getElementById('announcement_image_hash')) document.getElementById('announcement_image_hash').value = item.image_hash || '';
            if (document.getElementById('announcement_r2_key')) document.getElementById('announcement_r2_key').value = item.r2_key || '';
        }
    } else {
        if (title) title.innerText = isAr ? 'إضافة إعلان جديد للسلايدر' : 'Add New Slider Banner';
        document.getElementById('announcement_id').value = '';
        const maxOrder = (window.allAnnouncementsData || []).reduce((max, a) => Math.max(max, a.display_order || 0), 0);
        document.getElementById('announcement_display_order').value = maxOrder + 1;
        document.getElementById('announcement_is_active').checked = true;

        if (document.getElementById('announcement_image_source')) document.getElementById('announcement_image_source').value = 'custom';
        if (document.getElementById('announcement_image_hash')) document.getElementById('announcement_image_hash').value = '';
        if (document.getElementById('announcement_r2_key')) document.getElementById('announcement_r2_key').value = '';
    }

    updateAnnouncementImagePreview();

    modal.classList.add('show');
    modal.classList.add('active');
    modal.style.display = 'flex';
};

window.closeAnnouncementModal = function() {
    const modal = document.getElementById('announcementModal');
    if (modal) {
        modal.classList.remove('show');
        modal.classList.remove('active');
        modal.style.display = 'none';
    }
};

window.handleAnnouncementImageBtnClick = async function(e) {
    if (e) {
        e.preventDefault();
        e.stopPropagation();
    }
    const urlInput = document.getElementById('announcement_image_url');
    const fileInput = document.getElementById('announcement_image_file');
    const sourceInput = document.getElementById('announcement_image_source');
    const hashInput = document.getElementById('announcement_image_hash');
    const r2KeyInput = document.getElementById('announcement_r2_key');
    const annId = document.getElementById('announcement_id')?.value || null;

    if (urlInput && urlInput.value.trim()) {
        const oldUrl = urlInput.value.trim();
        const oldSource = sourceInput?.value || 'custom';
        const oldR2Key = r2KeyInput?.value || '';

        // Real-time deletion from Cloudflare R2
        if (typeof window.deleteSectionImageSmart === 'function') {
            await window.deleteSectionImageSmart(oldUrl, oldSource, oldR2Key, annId);
        }

        urlInput.value = '';
        if (sourceInput) sourceInput.value = 'custom';
        if (hashInput) hashInput.value = '';
        if (r2KeyInput) r2KeyInput.value = '';
        if (fileInput) fileInput.value = '';
        updateAnnouncementImagePreview();
    } else {
        if (fileInput) fileInput.click();
    }
};

window.updateAnnouncementImagePreview = function() {
    const urlInput = document.getElementById('announcement_image_url');
    const previewBox = document.getElementById('announcement_image_preview');
    const imgEl = document.getElementById('announcement_image_img');
    const iconEl = document.getElementById('announcement_image_icon');
    const textEl = document.getElementById('announcement_image_text');
    const btnEl = document.getElementById('announcement_image_btn');
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';

    if (urlInput && previewBox && imgEl) {
        const val = urlInput.value.trim();
        if (val) {
            imgEl.src = val;
            previewBox.style.display = 'flex';
            if (iconEl) {
                iconEl.className = 'fas fa-trash-alt';
                iconEl.style.color = '#ef4444';
            }
            if (textEl) {
                textEl.setAttribute('data-ar', 'حذف');
                textEl.setAttribute('data-en', 'Delete');
                textEl.textContent = isAr ? 'حذف' : 'Delete';
            }
            if (btnEl) btnEl.title = isAr ? 'حذف الصورة' : 'Remove Image';
        } else {
            previewBox.style.display = 'none';
            imgEl.src = '';
            if (iconEl) {
                iconEl.className = 'fas fa-upload';
                iconEl.style.color = 'var(--primary-gold)';
            }
            if (textEl) {
                textEl.setAttribute('data-ar', 'رفع');
                textEl.setAttribute('data-en', 'Upload');
                textEl.textContent = isAr ? 'رفع' : 'Upload';
            }
            if (btnEl) btnEl.title = isAr ? 'رفع صورة من الجهاز' : 'Upload image';
        }
    }
};

window.handleAnnouncementImageUpload = async function(e) {
    const file = e.target.files[0];
    if (!file) return;
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const clientDomain = (typeof window.getActiveClientDomain === 'function') ? window.getActiveClientDomain() : tenantId;

    showToast(isAr ? "جاري ضغط ورفع صورة الإعلان بدقة متناهية..." : "Compressing and uploading slide image...", "info");
    try {
        // 1. WebP compression (0.5 quality)
        const webpBlob = typeof convertToWebP === 'function' ? await convertToWebP(file, 0.5) : file;
        // 2. SHA-256 hash
        const compressedHash = typeof computeBlobSHA256 === 'function' ? await computeBlobSHA256(webpBlob) : '';
        // 3. Filename
        const fileName = `announcement-${tenantId}-${Date.now()}.webp`;

        let publicUrl = '';
        let r2Key = '';

        try {
            const base64Data = typeof blobToBase64 === 'function' ? await blobToBase64(webpBlob) : '';
            if (base64Data) {
                const r2Res = await fetch('/api/r2/upload', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        base64Data,
                        fileName,
                        tenantId,
                        clientDomain,
                        target: 'announcement',
                        contentType: 'image/webp'
                    })
                });
                const r2Data = await r2Res.json();
                if (r2Res.ok && r2Data && r2Data.success && r2Data.publicUrl) {
                    publicUrl = r2Data.publicUrl;
                    r2Key = r2Data.r2Key || '';
                } else if (r2Data && r2Data.r2Key) {
                    r2Key = r2Data.r2Key;
                }
            }
        } catch (r2Err) {
            console.warn('R2 announcement upload note, using fallback:', r2Err);
        }

        // Fallback to Supabase Storage if R2 failed
        if (!publicUrl) {
            const { error: upErr } = await supabaseClient.storage.from('images').upload(fileName, webpBlob, { contentType: 'image/webp' });
            if (upErr) throw upErr;
            const { data: { publicUrl: sbUrl } } = supabaseClient.storage.from('images').getPublicUrl(fileName);
            publicUrl = sbUrl;
            if (!r2Key) r2Key = fileName;
        }

        document.getElementById('announcement_image_url').value = publicUrl;
        if (document.getElementById('announcement_image_source')) document.getElementById('announcement_image_source').value = 'custom';
        if (document.getElementById('announcement_image_hash')) document.getElementById('announcement_image_hash').value = compressedHash;
        if (document.getElementById('announcement_r2_key')) document.getElementById('announcement_r2_key').value = r2Key;

        updateAnnouncementImagePreview();
        showToast(isAr ? "✨ تم رفع صورة الإعلان بنجاح" : "Slide image uploaded successfully", "success");
    } catch (err) {
        console.error('Error uploading slide image:', err);
        showToast(err.message, 'error');
    }
};

window.handleSaveAnnouncement = async function(e) {
    e.preventDefault();
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const btnSave = document.getElementById('btnSaveAnnouncement');
    if (btnSave) btnSave.disabled = true;

    const id = document.getElementById('announcement_id').value.trim();
    const textAr = document.getElementById('announcement_text_ar').value.trim();
    const textEn = document.getElementById('announcement_text_en').value.trim();
    const subtitleAr = document.getElementById('announcement_subtitle_ar').value.trim();
    const subtitleEn = document.getElementById('announcement_subtitle_en').value.trim();
    const badgeTextAr = document.getElementById('announcement_badge_text_ar').value.trim();
    const codeVal = document.getElementById('announcement_code').value.trim();
    const imageUrl = document.getElementById('announcement_image_url').value.trim();
    const displayOrder = parseInt(document.getElementById('announcement_display_order').value || '1', 10);
    const isActive = document.getElementById('announcement_is_active').checked;

    if (!textAr || !imageUrl) {
        showToast(isAr ? 'يرجى تعبئة العنوان الرئيسي وصورة خلفية الإعلان' : 'Please fill in main title and image URL', 'warning');
        if (btnSave) btnSave.disabled = false;
        return;
    }

    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const clientDomain = (typeof window.getActiveClientDomain === 'function') ? window.getActiveClientDomain() : tenantId;

    // If editing and image changed, delete old custom image from R2
    if (id) {
        const oldAnn = (window.allAnnouncementsData || []).find(a => String(a.id) === String(id));
        if (oldAnn && oldAnn.image_url && oldAnn.image_url !== imageUrl) {
            if (typeof window.deleteSectionImageSmart === 'function') {
                await window.deleteSectionImageSmart(oldAnn.image_url, oldAnn.image_source || 'custom', oldAnn.r2_key || '', id);
            }
        }
    }

    const safeBasePayload = {
        tenant_id: tenantId,
        text_ar: textAr,
        text_en: textEn || textAr,
        subtitle_ar: subtitleAr,
        subtitle_en: subtitleEn || subtitleAr,
        badge_text_ar: badgeTextAr,
        badge_text: badgeTextAr,
        image_url: imageUrl,
        display_order: displayOrder,
        is_active: isActive,
        r2_key: document.getElementById('announcement_r2_key')?.value || null,
        image_hash: document.getElementById('announcement_image_hash')?.value || null,
        image_source: document.getElementById('announcement_image_source')?.value || 'custom',
        client_domain: clientDomain
    };

    const extendedPayload = {
        ...safeBasePayload,
        code: codeVal || null
    };

    try {
        showToast(isAr ? 'جاري حفظ بيانات الشريحة الإعلانية...' : 'Saving slide data...', 'info');

        let res;
        if (id) {
            res = await window.supabaseWriteRow('announcements', 'update', extendedPayload, id, tenantId);
            if (res.error && (res.error.code === '42703' || res.error.code === 'PGRST204' || (res.error.message && res.error.message.includes('column')))) {
                res = await window.supabaseWriteRow('announcements', 'update', safeBasePayload, id, tenantId);
            }
        } else {
            res = await window.supabaseWriteRow('announcements', 'insert', extendedPayload, null, tenantId);
            if (res.error && (res.error.code === '42703' || res.error.code === 'PGRST204' || (res.error.message && res.error.message.includes('column')))) {
                res = await window.supabaseWriteRow('announcements', 'insert', safeBasePayload, null, tenantId);
            }
        }

        const data = res ? res.data : null;
        const error = res ? res.error : null;

        if (error || !data || data.length === 0) {
            console.warn('Supabase announcements fallback note:', error ? error.message : 'No rows returned');
            const existingAnn = id ? ((window.allAnnouncementsData || []).find(a => String(a.id) === String(id)) || {}) : {};
            const localSavedAnn = {
                ...existingAnn,
                id: id || generateFallbackUUID(),
                created_at: existingAnn.created_at || new Date().toISOString(),
                ...extendedPayload
            };
            saveLocalAnnouncementOverride(tenantId, localSavedAnn);
        } else {
            const syncedAnn = data[0];
            if (syncedAnn && syncedAnn.id) {
                clearLocalAnnouncementOverride(tenantId, syncedAnn.id);
            }
        }

        showToast(isAr ? '✨ تم حفظ الشريحة الإعلانية بنجاح في قاعدة البيانات' : 'Slide saved successfully to database', 'success');
        closeAnnouncementModal();
        await loadAnnouncementsData(true);
    } catch (err) {
        console.error('Error saving announcement:', err);
        showToast(err.message, 'error');
    } finally {
        if (btnSave) btnSave.disabled = false;
    }
};

window.toggleAnnouncementActive = async function(announcementId, currentStatus) {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    const newStatus = !currentStatus;

    try {
        showToast(isAr ? 'جاري تحديث حالة الشريحة الإعلانية...' : 'Updating slide status...', 'info');

        const res = await window.supabaseWriteRow('announcements', 'update', { is_active: newStatus }, announcementId, tenantId);

        if (window.allAnnouncementsData) {
            const item = window.allAnnouncementsData.find(a => String(a.id) === String(announcementId));
            if (item) {
                item.is_active = newStatus;
                if (res && res.data && res.data[0]) {
                    clearLocalAnnouncementOverride(tenantId, announcementId);
                } else {
                    saveLocalAnnouncementOverride(tenantId, item);
                }
            }
        }
        filterAnnouncementsTable();

        showToast(isAr ? (newStatus ? '✨ تم تفعيل الشريحة الإعلانية' : '👁️ تم تعطيل الشريحة الإعلانية') : 'Status updated', 'success');
        await loadAnnouncementsData(true);
    } catch (err) {
        console.error('Error toggling announcement status:', err);
        showToast(err.message, 'error');
    }
};

window.deleteAnnouncement = function(announcementId, title) {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';

    openConfirm({
        title: isAr ? 'تأكيد الحذف' : 'Confirm Delete',
        text: isAr ? `هل أنت متأكد من حذف الشريحة الإعلانية "${title}"؟` : `Are you sure you want to delete slide "${title}"?`,
        onConfirm: async () => {
            try {
                showToast(isAr ? 'جاري حذف الشريحة الإعلانية والصورة...' : 'Deleting slide and image...', 'info');

                // Delete image from R2
                const item = (window.allAnnouncementsData || []).find(a => String(a.id) === String(announcementId));
                if (item && item.image_url && typeof window.deleteSectionImageSmart === 'function') {
                    await window.deleteSectionImageSmart(item.image_url, item.image_source || 'custom', item.r2_key || '', announcementId);
                }

                await window.supabaseWriteRow('announcements', 'delete', null, announcementId, tenantId);
                clearLocalAnnouncementOverride(tenantId, announcementId);

                showToast(isAr ? '🗑️ تم حذف الشريحة الإعلانية بنجاح' : 'Slide deleted', 'success');
                await loadAnnouncementsData(true);
            } catch (err) {
                console.error('Error deleting announcement:', err);
                showToast(err.message, 'error');
            }
        }
    });
};

/* Selection Mode Functions for Announcements */
if (!window.selectedAnnouncementIds) window.selectedAnnouncementIds = new Set();

window.toggleAnnouncementSelectionMode = () => {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const btn = document.getElementById('btn-toggle-announcements-select');
    const label = document.getElementById('btnAnnouncementsSelectLabel');

    const visibleList = window.currentFilteredAnnouncementsData || window.allAnnouncementsData || [];
    if (visibleList.length === 0) {
        showToast(isAr ? 'لا توجد إعلانات قابلة للتحديد' : 'No slides to select', 'warning');
        return;
    }

    if (window.isAnnouncementSelectionModeActive) {
        window.isAnnouncementSelectionModeActive = false;
        if (window.selectedAnnouncementIds) window.selectedAnnouncementIds.clear();
        if (btn) btn.classList.remove('active-selected');
        if (label) label.textContent = isAr ? 'تحديد' : 'Select';
    } else {
        window.isAnnouncementSelectionModeActive = true;
        if (btn) btn.classList.add('active-selected');
        if (label) label.textContent = isAr ? 'إلغاء التحديد' : 'Deselect';
    }

    updateAnnouncementsBulkBarUI(isAr);
    filterAnnouncementsTable();
};

window.handleAnnouncementCardClick = (event, announcementId) => {
    if (!window.isAnnouncementSelectionModeActive) return;
    if (event.target.closest('button, a, input, select, label')) return;

    const isSelected = window.selectedAnnouncementIds ? window.selectedAnnouncementIds.has(String(announcementId)) : false;
    toggleAnnouncementSelection(announcementId, !isSelected);
};

window.toggleAnnouncementSelection = (id, isChecked) => {
    if (!window.selectedAnnouncementIds) window.selectedAnnouncementIds = new Set();
    if (isChecked) {
        window.selectedAnnouncementIds.add(String(id));
    } else {
        window.selectedAnnouncementIds.delete(String(id));
    }
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    updateAnnouncementsBulkBarUI(isAr);
    filterAnnouncementsTable();
};

window.toggleSelectAllAnnouncements = (isChecked) => {
    if (!window.selectedAnnouncementIds) window.selectedAnnouncementIds = new Set();
    const visibleSlides = window.currentFilteredAnnouncementsData || window.allAnnouncementsData || [];
    visibleSlides.forEach(a => {
        if (isChecked) {
            window.selectedAnnouncementIds.add(String(a.id));
        } else {
            window.selectedAnnouncementIds.delete(String(a.id));
        }
    });
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    updateAnnouncementsBulkBarUI(isAr);
    filterAnnouncementsTable();
};

window.clearSelectedAnnouncements = () => {
    if (window.selectedAnnouncementIds) window.selectedAnnouncementIds.clear();
    window.isAnnouncementSelectionModeActive = false;
    const btn = document.getElementById('btn-toggle-announcements-select');
    const label = document.getElementById('btnAnnouncementsSelectLabel');
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    if (btn) btn.classList.remove('active-selected');
    if (label) label.textContent = isAr ? 'تحديد' : 'Select';
    updateAnnouncementsBulkBarUI(isAr);
    filterAnnouncementsTable();
};

function updateAnnouncementsBulkBarUI(isAr) {
    const bulkBar = document.getElementById('announcements-bulk-actions-bar');
    const selectAllCheckbox = document.getElementById('announcementsSelectAllCheckbox');
    const selectAllText = document.getElementById('announcementsSelectAllText');
    const selectedCountText = document.getElementById('announcementsSelectedCountText');

    const selectedCount = window.selectedAnnouncementIds ? window.selectedAnnouncementIds.size : 0;
    const visibleSlides = window.currentFilteredAnnouncementsData || window.allAnnouncementsData || [];
    const allPageSelected = visibleSlides.length > 0 && visibleSlides.every(a => window.selectedAnnouncementIds.has(String(a.id)));

    if (selectAllCheckbox) selectAllCheckbox.checked = allPageSelected;

    if (selectAllText) {
        selectAllText.textContent = isAr ? `تحديد الكل (${visibleSlides.length})` : `Select All (${visibleSlides.length})`;
    }

    if (bulkBar) {
        if (window.isAnnouncementSelectionModeActive || selectedCount > 0) {
            bulkBar.style.display = 'flex';
        } else {
            bulkBar.style.display = 'none';
        }
    }

    if (selectedCountText) {
        selectedCountText.textContent = isAr ? `تم تحديد ${selectedCount} عنصر` : `${selectedCount} selected`;
    }
}

window.bulkUpdateAnnouncementsStatus = async (isActive) => {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const selectedIds = Array.from(window.selectedAnnouncementIds || []);
    if (selectedIds.length === 0) {
        showToast(isAr ? 'يرجى تحديد إعلان واحد على الأقل' : 'Please select at least one slide first', 'warning');
        return;
    }

    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
    showToast(isAr ? 'جاري تحديث حالة الإعلانات المحددة...' : 'Updating status...', 'info');

    try {
        let { data, error } = await supabaseClient
            .from('announcements')
            .update({ is_active: isActive })
            .in('id', selectedIds)
            .eq('tenant_id', tenantId)
            .select();

        if (error || !data || data.length === 0) {
            const numIds = selectedIds.map(id => Number(id) || id);
            const retry = await supabaseClient
                .from('announcements')
                .update({ is_active: isActive })
                .in('id', numIds)
                .eq('tenant_id', tenantId)
                .select();
            if (retry.error) throw retry.error;
            data = retry.data;
        }

        // Immediate local state update for instant UI response
        if (window.allAnnouncementsData) {
            window.allAnnouncementsData.forEach(a => {
                if (selectedIds.includes(String(a.id))) {
                    a.is_active = isActive;
                }
            });
        }
        filterAnnouncementsTable();

        showToast(isAr ? '✨ تم تحديث حالة الإعلانات المحددة بنجاح' : 'Status updated successfully', 'success');
        clearSelectedAnnouncements();
        await loadAnnouncementsData();
    } catch (err) {
        console.error('Error bulk updating announcements status:', err);
        showToast(err.message, 'error');
    }
};

window.bulkDeleteAnnouncements = async () => {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const selectedIds = Array.from(window.selectedAnnouncementIds || []);
    if (selectedIds.length === 0) {
        showToast(isAr ? 'يرجى تحديد إعلان واحد على الأقل' : 'Please select at least one slide first', 'warning');
        return;
    }

    openConfirm({
        title: isAr ? 'تأكيد الحذف الجماعي' : 'Confirm Bulk Delete',
        text: isAr ? `هل أنت متأكد من حذف ${selectedIds.length} إعلان محدد من السلايدر؟` : `Are you sure you want to delete ${selectedIds.length} selected slides?`,
        onConfirm: async () => {
            const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';
            showToast(isAr ? 'جاري حذف الإعلانات المحددة...' : 'Deleting selected slides...', 'info');

            try {
                const { error } = await supabaseClient
                    .from('announcements')
                    .delete()
                    .in('id', selectedIds)
                    .eq('tenant_id', tenantId);

                if (error) throw error;

                showToast(isAr ? '✨ تم حذف الإعلانات المحددة بنجاح' : 'Slides deleted successfully', 'success');
                clearSelectedAnnouncements();
                loadAnnouncementsData();
            } catch (err) {
                console.error('Error bulk deleting announcements:', err);
                showToast(err.message, 'error');
            }
        }
    });
};

