window.handleSaveAboutStore = async function(e) {
    if (e) e.preventDefault();
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';

    const payload = {
        tenant_id: tenantId,
        hero_badge_ar: (document.getElementById('about_hero_badge_ar')?.value || '').trim(),
        hero_badge_en: (document.getElementById('about_hero_badge_en')?.value || '').trim(),
        hero_title_ar: (document.getElementById('about_hero_title_ar')?.value || '').trim(),
        hero_title_en: (document.getElementById('about_hero_title_en')?.value || '').trim(),
        hero_subtitle_ar: (document.getElementById('about_hero_subtitle_ar')?.value || '').trim(),
        hero_subtitle_en: (document.getElementById('about_hero_subtitle_en')?.value || '').trim(),

        story_heading_ar: (document.getElementById('about_story_heading_ar')?.value || '').trim(),
        story_heading_en: (document.getElementById('about_story_heading_en')?.value || '').trim(),
        story_p1_ar: (document.getElementById('about_story_p1_ar')?.value || '').trim(),
        story_p1_en: (document.getElementById('about_story_p1_en')?.value || '').trim(),
        story_p2_ar: (document.getElementById('about_story_p2_ar')?.value || '').trim(),
        story_p2_en: (document.getElementById('about_story_p2_en')?.value || '').trim(),
        commitments_heading_ar: (document.getElementById('about_commitments_heading_ar')?.value || '').trim(),
        commitments_heading_en: (document.getElementById('about_commitments_heading_en')?.value || '').trim(),

        pillars_tag_ar: (document.getElementById('about_pillars_tag_ar')?.value || '').trim(),
        pillars_tag_en: (document.getElementById('about_pillars_tag_en')?.value || '').trim(),
        pillars_title_ar: (document.getElementById('about_pillars_title_ar')?.value || '').trim(),
        pillars_title_en: (document.getElementById('about_pillars_title_en')?.value || '').trim(),
        pillars_desc_ar: (document.getElementById('about_pillars_desc_ar')?.value || '').trim(),
        pillars_desc_en: (document.getElementById('about_pillars_desc_en')?.value || '').trim(),

        vision_title_ar: (document.getElementById('about_vision_title_ar')?.value || '').trim(),
        vision_title_en: (document.getElementById('about_vision_title_en')?.value || '').trim(),
        vision_desc_ar: (document.getElementById('about_vision_desc_ar')?.value || '').trim(),
        vision_desc_en: (document.getElementById('about_vision_desc_en')?.value || '').trim(),

        mission_title_ar: (document.getElementById('about_mission_title_ar')?.value || '').trim(),
        mission_title_en: (document.getElementById('about_mission_title_en')?.value || '').trim(),
        mission_desc_ar: (document.getElementById('about_mission_desc_ar')?.value || '').trim(),
        mission_desc_en: (document.getElementById('about_mission_desc_en')?.value || '').trim(),

        values_title_ar: (document.getElementById('about_values_title_ar')?.value || '').trim(),
        values_title_en: (document.getElementById('about_values_title_en')?.value || '').trim(),
        values_desc_ar: (document.getElementById('about_values_desc_ar')?.value || '').trim(),
        values_desc_en: (document.getElementById('about_values_desc_en')?.value || '').trim()
    };

    try {
        showToast(isAr ? 'جاري حفظ بيانات صفحة عن المتجر...' : 'Saving About Store info...', 'info');

        const currentObj = window.currentAboutStoreData;
        let res;
        if (currentObj && currentObj.id) {
            res = await supabaseClient
                .from('store_about_info')
                .update(payload)
                .eq('id', currentObj.id)
                .eq('tenant_id', tenantId)
                .select();
        } else {
            res = await supabaseClient
                .from('store_about_info')
                .insert([payload])
                .select();
        }

        if (res.error) throw res.error;

        showToast(isAr ? '✨ تم حفظ بيانات صفحة عن المتجر بنجاح' : 'About Store info saved successfully', 'success');
        await loadAboutStoreData();
    } catch (err) {
        console.error('Error saving about store info:', err);
        showToast(err.message, 'error');
    }
};

/* ==========================================================================
   Customer Service Page Management (store_customer_service)
   ========================================================================== */

// 1. Data Structures & Variables
window.currentCustomerServiceData = null;
window.csBranches = [];
window.csSalesReps = [];
window.csPaymentMethods = [];

// 2. Load Data
async function loadCustomerServiceData() {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const tenantId = (typeof window.getActiveTenantId === 'function') ? window.getActiveTenantId() : 'altaqwa_for_tranding_01';

    try {
        let { data, error } = await supabaseClient
            .from('store_customer_service')
            .select('*')
            .eq('tenant_id', tenantId)
            .maybeSingle();

        if (error) {
            console.warn('Fetch store_customer_service note:', error.message);
        }

        if (data) {
            window.currentCustomerServiceData = data;

            // Populate basic fields
            if (document.getElementById('cs_complaints_phone')) {
                document.getElementById('cs_complaints_phone').value = data.complaints_phone || '';
            }
            if (document.getElementById('cs_marketing_emails')) {
                document.getElementById('cs_marketing_emails').value = Array.isArray(data.marketing_emails) ? data.marketing_emails.join(', ') : '';
            }

            // Populate JSON arrays
            window.csBranches = Array.isArray(data.branches) ? [...data.branches] : [];
            window.csSalesReps = Array.isArray(data.sales_reps) ? [...data.sales_reps] : [];
            window.csPaymentMethods = Array.isArray(data.payment_methods) ? [...data.payment_methods] : [];

        } else {
            // Default empty state
            window.currentCustomerServiceData = null;
            if (document.getElementById('cs_complaints_phone')) document.getElementById('cs_complaints_phone').value = '';
            if (document.getElementById('cs_marketing_emails')) document.getElementById('cs_marketing_emails').value = '';
            window.csBranches = [];
            window.csSalesReps = [];
            window.csPaymentMethods = [];
        }

        renderCsBranches();
        renderCsSalesReps();
        renderCsPaymentMethods();

    } catch (err) {
        console.error('Error loading customer service info:', err);
        showToast(err.message, 'error');
    }
}
window.loadCustomerServiceData = loadCustomerServiceData;

window.refreshCustomerServiceData = function(btn) {
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    if (btn) {
        const icon = btn.querySelector('i');
        if (icon) icon.classList.add('fa-spin');
        setTimeout(() => icon?.classList.remove('fa-spin'), 1000);
    }
    showToast(isAr ? '✨ جاري تحديث بيانات خدمة العملاء...' : 'Refreshing Customer Service data...', 'info');
    loadCustomerServiceData();
};

// 3. Render Helpers for dynamic JSON Arrays

// 3A. Branches
function renderCsBranches() {
    const container = document.getElementById('cs_branches_container');
    if (!container) return;
    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';

    if (window.csBranches.length === 0) {
        container.innerHTML = `<div style="text-align: center; color: var(--text-muted); padding: 20px;">${isAr ? 'لا يوجد فروع مضافة' : 'No branches added'}</div>`;
        return;
    }

    container.innerHTML = window.csBranches.map((branch, index) => `
        <div class="dynamic-item-card" style="padding: 16px 18px; border: 1px solid var(--border-subtle); border-radius: 14px; background: rgba(0,0,0,0.02); position: relative; margin-bottom: 14px;">
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px; border-bottom: 1px dashed var(--border-subtle); padding-bottom: 8px;">
                <div style="display: inline-flex; align-items: center; gap: 8px;">
                    <i class="fas fa-building" style="color: var(--icon-purple); font-size: 0.88rem;"></i>
                    <span style="font-size: 0.84rem; font-weight: 700; color: var(--text-main);">${branch.name_ar ? escapeHtml(branch.name_ar) : (isAr ? `فرع رقم #${index + 1}` : `Branch #${index + 1}`)}</span>
                </div>
                <button type="button" onclick="removeCsBranch(${index})" style="color: #ef4444; background: rgba(239, 68, 68, 0.1); border: 1px solid rgba(239, 68, 68, 0.25); border-radius: 8px; cursor: pointer; padding: 4px 10px; font-size: 0.78rem; display: inline-flex; align-items: center; gap: 5px; transition: all 0.2s ease;" title="${isAr ? 'حذف الفرع' : 'Delete Branch'}">
                    <i class="fas fa-trash-alt"></i> <span style="font-size: 0.72rem;">${isAr ? 'حذف' : 'Delete'}</span>
                </button>
            </div>
            <div class="cs-responsive-grid" style="display: grid; gap: 10px; align-items: end;">
                <div class="form-group cs-grid-item" style="margin-bottom:0; width: 100%;">
                    <div style="display:flex; align-items:center; justify-content:space-between; gap:8px; margin-bottom:6px; flex-wrap:nowrap; width:100%;">
                        <label style="font-size:0.78rem; font-weight:700; margin:0 !important; padding:0 !important; color:var(--text-main); white-space:nowrap !important; flex-shrink:0;">${isAr ? 'الاسم (عربي)' : 'Name (AR)'}</label>
                        <label class="cs-main-branch-pill" style="display: inline-flex !important; flex-direction: row !important; align-items: center !important; justify-content: center !important; gap: 6px !important; cursor: pointer; margin: 0 !important; padding: 3px 10px !important; height: 26px !important; min-height: 26px !important; width: auto !important; min-width: max-content !important; flex-shrink: 0 !important; white-space: nowrap !important; border-radius: 8px !important; background: ${branch.is_main ? 'rgba(217, 119, 6, 0.22)' : 'rgba(255, 255, 255, 0.05)'} !important; border: 1.5px solid ${branch.is_main ? '#d97706' : 'var(--border-subtle)'} !important; font-size: 0.74rem !important; font-weight: 800 !important; color: ${branch.is_main ? 'var(--icon-purple)' : 'var(--text-muted)'} !important; user-select: none; transition: all 0.2s ease;">
                            <input type="checkbox" style="width: 14px !important; height: 14px !important; min-width: 14px !important; max-width: 14px !important; padding: 0 !important; margin: 0 !important; accent-color: #d97706 !important; cursor: pointer; flex-shrink: 0 !important;" ${branch.is_main ? 'checked' : ''} onchange="updateCsBranch(${index}, 'is_main', this.checked)">
                            <span style="white-space: nowrap !important; display: inline-block !important; line-height: 1 !important;">${isAr ? '★ فرع رئيسي' : '★ Main Branch'}</span>
                        </label>
                    </div>
                    <input type="text" style="height:38px; padding:0 8px; font-size:0.85rem;" placeholder="${isAr ? 'مثال: المستودع المركزي' : 'e.g. Central Warehouse'}" value="${escapeHtml(branch.name_ar || '')}" onchange="updateCsBranch(${index}, 'name_ar', this.value)">
                </div>
                <div class="form-group cs-grid-item" style="margin-bottom:0; width: 100%;"><label style="font-size:0.75rem;">الاسم (إنجليزي)</label><input type="text" style="height:38px; padding:0 8px; font-size:0.85rem;" value="${escapeHtml(branch.name_en || '')}" onchange="updateCsBranch(${index}, 'name_en', this.value)"></div>
                <div class="form-group cs-grid-item" style="margin-bottom:0; width: 100%;"><label style="font-size:0.75rem;">التوصيف</label><input type="text" style="height:38px; padding:0 8px; font-size:0.85rem;" value="${escapeHtml(branch.subtitle_ar || '')}" onchange="updateCsBranch(${index}, 'subtitle_ar', this.value)"></div>
                <div class="form-group cs-grid-item" style="margin-bottom:0; width: 100%;"><label style="font-size:0.75rem;">العنوان</label><input type="text" style="height:38px; padding:0 8px; font-size:0.85rem;" value="${escapeHtml(branch.address_ar || '')}" onchange="updateCsBranch(${index}, 'address_ar', this.value)"></div>
                <div class="form-group cs-grid-item" style="margin-bottom:0; width: 100%;"><label style="font-size:0.75rem;">الجوال</label><input type="text" style="height:38px; padding:0 8px; font-size:0.85rem;" value="${escapeHtml(branch.mobile || '')}" onchange="updateCsBranch(${index}, 'mobile', this.value)"></div>
                <div class="form-group cs-grid-item" style="margin-bottom:0; width: 100%;"><label style="font-size:0.75rem;">الثابت</label><input type="text" style="height:38px; padding:0 8px; font-size:0.85rem;" value="${escapeHtml(branch.landline || '')}" onchange="updateCsBranch(${index}, 'landline', this.value)"></div>
            </div>
        </div>
    `).join('');
}

window.addCsBranch = () => {
    window.csBranches.unshift({ name_ar: '', name_en: '', subtitle_ar: '', address_ar: '', mobile: '', landline: '', is_main: false });
    renderCsBranches();
};

window.removeCsBranch = (index) => {
    window.csBranches.splice(index, 1);
    renderCsBranches();
};

window.updateCsBranch = (index, field, value) => {
    window.csBranches[index][field] = value;
    if (field === 'is_main' && value === true) {
        // Only one main branch allowed ideally, unset others
        window.csBranches.forEach((b, i) => { if (i !== index) b.is_main = false; });
        renderCsBranches();
    }
};

// 3B. Sales Reps
