window.sendAiSuggestion = function(promptText) {
    const input = document.getElementById('aiPromptInput');
    if (input) {
        input.value = promptText || '';
        input.focus();
    }
    window.handleSendAiPrompt();
};

window.handleSendAiPrompt = async function(event) {
    if (event && typeof event.preventDefault === 'function') event.preventDefault();
    const input = document.getElementById('aiPromptInput');
    const messagesBox = document.getElementById('aiChatMessages');
    if (!input || !messagesBox) return;
    const text = input.value.trim();
    if (!text) return;
    input.value = '';

    const isAr = (localStorage.getItem('adminLang') || 'ar') === 'ar';
    const userMsg = document.createElement('div');
    userMsg.className = 'ai-message user';
    userMsg.innerHTML = `<div class="msg-bubble"><p>${escapeHtml(text)}</p></div>`;
    messagesBox.appendChild(userMsg);

    const botMsg = document.createElement('div');
    botMsg.className = 'ai-message bot';
    const apiKey = document.getElementById('setting_gemini_api_key')?.value?.trim() || window.currentSiteSettingsData?.gemini_api_key || '';
    const replyText = apiKey
        ? (isAr ? 'تم استلام أمرك بنجاح. يرجى استخدام أقسام لوحة التحكم لتأكيد العملية.' : 'Command received. Please use the dashboard sections to confirm the action.')
        : (isAr ? 'يرجى إضافة مفتاح Gemini API أولاً من قسم الإعدادات العامة لتفعيل الوكيل الذكي.' : 'Please configure your Gemini API Key in General Settings first to enable the AI Agent.');
    botMsg.innerHTML = `<div class="msg-avatar"><i class="fas fa-robot"></i></div><div class="msg-bubble"><p>${escapeHtml(replyText)}</p></div>`;
    messagesBox.appendChild(botMsg);
    messagesBox.scrollTop = messagesBox.scrollHeight;
};
